window.__Q=window.__Q||{};window.__Q["prev/2/A2"]=[{"q":"患儿，女，3岁。咳嗽、低热1周。今出现抓耳朵，喊耳朵疼，并发现有分泌物自外耳道流出，怀疑中耳炎并发鼓膜穿孔。幼儿容易患中耳炎的原因是","o":["幼儿抵抗力低","幼儿咽鼓管短而平，管径大","幼儿咽鼓管主要为软骨部构成","幼儿咽鼓管主要由骨部构成","幼儿咽鼓管始终处于开放状态"],"a":1,"e":"幼儿咽鼓管较成人短、宽且略呈水平位，咽部感染易经此管侵入鼓室，故急性中耳炎发病率高。抵抗力低非解剖学主因；咽鼓管软骨部或骨部的构成比例并非关键；咽鼓管咽口平时关闭，并非始终开放"},{"q":"患儿，男，7岁。跌倒时肘关节过伸造成伸直型髁上骨折。肱骨髁上骨折的部位是","o":["肱骨外上髁处","肱骨内上髁处","肱骨下端和体交界处","肱骨上端和体交界处","肱骨体"],"a":2,"e":"肱骨下端与体交界处即内、外上髁稍上方骨质较薄弱，为肱骨髁上骨折的好发部位，伸直型骨折多见。肱骨上端与体交界处为外科颈；内、外上髁为骨性标志；肱骨体骨折不属髁上骨折"},{"q":"患者，男。从高处落下后，X线显示右前臂桡骨粉碎性骨折，需手术治疗。在前臂桡侧施行手术时容易损伤到的浅静脉是","o":["头静脉","前臂正中静脉","贵要静脉","肘正中静脉","肱静脉"],"a":0,"e":"头静脉起自手背静脉网桡侧，沿前臂桡侧上行，收集手和前臂桡侧浅层静脉血，前臂桡侧手术易伤及。贵要静脉沿前臂尺侧上行；前臂正中静脉位于前臂前面正中，收集掌侧浅层血液；肘正中静脉位于肘窝；肱静脉为伴行动脉的深静脉，均不在桡侧浅层"},{"q":"患者，男，63岁。因肿瘤压迫中脑被盖后出现右上、下肢意向性震颤，右上、下肢及躯干意识性本体觉和精细触觉障碍。请问该患者可能损伤了哪些结构","o":["右小脑丘脑纤维、右红核、右内侧丘系","左小脑丘脑纤维、左红核、左脊髓丘脑束","右小脑丘脑纤维、右红核、右脊髓丘脑束","左小脑丘脑纤维、左红核、左内侧丘系","左三叉神经脊束、左红核、左内侧丘系"],"a":3,"e":"小脑丘脑纤维（已交叉的小脑上脚纤维）和红核损伤出现对侧肢体意向性震颤、共济失调；内侧丘系损伤出现对侧意识性本体感觉和精细触觉障碍，故右侧症状定位于左侧三结构。脊髓丘脑束司痛温觉；三叉神经脊束司同侧头面部感觉，均与本题不符"},{"q":"患者，男，72岁。诊断为前列腺癌，需手术治疗。医生在手术中必须清楚该腺体的位置与毗邻。下列关于该腺体的描述错误的是","o":["位于膀胱与尿生殖膈之间","前方为耻骨联合","后方与直肠壶腹毗邻","底与精囊，输精管壶腹相毗邻","尖与膀胱颈邻接"],"a":4,"e":"前列腺呈栗子形，底朝上，与膀胱颈、精囊及输精管壶腹相邻；尖朝下，邻接尿生殖膈，故尖与膀胱颈邻接的描述颠倒了上下毗邻关系。前列腺位于膀胱与尿生殖膈之间，前方为耻骨联合，后方与直肠壶腹毗邻，后方面对直肠可经直肠指诊触及，三项描述均正确"},{"q":"患者，男，35岁。3天前于头部外伤后出现右眼上睑下垂，伴眼球不能向上、向内运动。诊断为动眼神经麻痹。下列眼球外肌中可能受累的是","o":["上睑提肌和外直肌","上睑提肌和下斜肌","上睑提肌和上斜肌","内直肌和上斜肌","外直肌和下斜肌"],"a":1,"e":"动眼神经支配上睑提肌、上直肌、内直肌、下直肌和下斜肌；上睑下垂提示上睑提肌受累，眼球不能向上、向内提示上直肌与内直肌等麻痹，选项中上睑提肌与下斜肌均属动眼神经支配。外直肌由展神经支配；上斜肌由滑车神经支配；含此二者或上斜肌的组合均可排除"},{"q":"患者，男，60岁。在胸腔手术中见到了一些黑色淋巴结，它们是","o":["气管旁淋巴结","纵隔前淋巴结","膈上淋巴结","纵隔后淋巴结","肋间淋巴结"],"a":0,"e":"气管旁淋巴结沿气管排列，长期吸入炭末等颗粒可使其呈黑色，胸腔手术中易见，且收纳气管、食管及肺门区域的淋巴。纵隔前、后淋巴结，膈上淋巴结及肋间淋巴结引流区域和位置不同，非典型的黑色淋巴结"},{"q":"患者，女，43岁。某日从梯子上摔下来，左脚踝局部肿胀、疼痛、青紫。X线诊断为单纯内踝撕脱骨折。内踝是位于","o":["胫骨下端内下的突起","胫骨下端外下的突起","腓骨下端内下的突起","腓骨下端外下的突起","腓骨上端的膨大"],"a":0,"e":"内踝为胫骨下端内下方的突起，可在体表扪及，参与构成踝关节内侧壁；单纯内踝撕脱骨折定位于此。胫骨下端外下突起为外踝的说法错误（外踝属腓骨）；腓骨下端内下或外下突起及腓骨上端膨大均非内踝"},{"q":"患者，男，18岁。在一次篮球比赛中，不慎右肩膀重重摔到了篮球架上，锁骨处疼痛难忍，医生检查结果是锁骨骨折。锁骨易发生骨折的部位是","o":["锁骨的肩峰端","锁骨内侧2/3段","锁骨胸骨端","锁骨内外侧1/3段","锁骨内侧2/3段和外侧1/3段交界处"],"a":4,"e":"锁骨内侧三分之二凸向前呈三棱形、外侧三分之一凸向后呈扁平形，两部交界处为应力集中点且位置表浅，是锁骨骨折最好发部位。肩峰端与胸骨端并非骨折好发处；单纯内侧或外侧段骨折均不如交界处常见"},{"q":"患者，女，35岁。诊断为脊髓空洞症，患者出现上睑下垂，瞳孔缩小的表现。试分析脊髓损伤的节段","o":["C4～5","C5～6","C7～8","T1～2","T3～4"],"a":3,"e":"上睑下垂、瞳孔缩小属Horner综合征，源于脊髓T1～2侧角交感神经元（睫状脊髓中枢）受损，脊髓空洞症累及该节段即可出现。C4～C5至C7～C8节段与膈神经及上肢神经相关，不含支配头面部的交感中枢；T3～4平面偏低"},{"q":"患者，男，44岁。手术中损伤椎动脉后出现右侧上、下肢及躯干痛、温觉障碍。请问该患者可能损伤了以下哪个结构","o":["左侧薄束","左侧锥体束","右侧薄束","右侧脊髓丘脑束","左侧脊髓丘脑束"],"a":4,"e":"脊髓丘脑束在脊髓内交叉后上行，左侧脊髓丘脑束损伤导致对侧即右侧躯干四肢痛温觉障碍，本例右侧痛温觉障碍故定位于左侧脊髓丘脑束。薄束传导同侧本体感觉；锥体束损伤表现为对侧运动障碍；右侧脊髓丘脑束损伤体征应在左侧"},{"q":"患者，中年男性。主诉腘窝部不适或行走后发胀感。检查可见腘窝有囊性肿物需手术治疗。在腘窝手术时注意勿损伤注入腘静脉的较粗的浅静脉是","o":["大隐静脉","胫后静脉","胫前静脉","小隐静脉","腓静脉"],"a":3,"e":"小隐静脉起自足背静脉弓外侧端，经外踝后方沿小腿后面上行，至腘窝下角穿深筋膜后注入腘静脉，腘窝手术时须避免损伤。大隐静脉经内踝前方上行注入股静脉，不经过腘窝；胫前、胫后静脉和腓静脉为伴行动脉的深静脉，非注入腘静脉的浅静脉"},{"q":"患者，男，32岁，木匠。从屋顶上摔了下来，足外侧纵弓后端承重点骨折而变平。损伤的骨是","o":["跟骨","骰骨","距骨头","内侧楔骨","足舟骨"],"a":0,"e":"外侧纵弓由跟骨、骰骨和外侧重两块跖骨构成，后端承重点为跟骨的跟结节，从高处坠落足跟着地时该处承受垂直撞击，骨折后纵弓塌陷变平，最常见的是跟骨骨折。骰骨为外侧纵弓最高点；距骨头为内侧纵弓最高点；内侧楔骨、足舟骨属内侧纵弓，均非外侧纵弓后端承重点"},{"q":"患者，男，50岁。无明显诱因出现眩晕、恶心、呕吐以及吞咽困难等症状，经临床检查诊断为血管闭塞引起延髓背外侧综合征。出现闭塞的血管最有可能是","o":["大脑中动脉","大脑后动脉","小脑下前动脉","小脑下后动脉","迷路动脉"],"a":3,"e":"延髓背外侧综合征由椎动脉延髓支或小脑下后动脉闭塞引起，该动脉供应延髓后外侧部与小脑下面后部，损伤后出现眩晕、呕吐、吞咽困难及交叉性感觉障碍。大脑中、后动脉供血大脑半球；小脑下前动脉供小脑前下部；迷路动脉主要供应内耳，均不导致典型延髓背外侧综合征"},{"q":"患者，女，64岁。因生锈铁钉穿破伤口，引起破伤风，造成牙颌（口腔）无法张开。最可能瘫痪的肌是","o":["颞肌","咬肌","颊肌","翼内肌","翼外肌"],"a":4,"e":"翼外肌是主要的开口肌，收缩使下颌前伸并张口，其瘫痪（或破伤风时闭口肌痉挛占优势）致口腔不能张开。咬肌、颞肌、翼内肌均为上提下颌的闭口肌，痉挛时反而加重牙关紧闭；颊肌属表情肌，不参与张口运动"},{"q":"患者，男，34岁。患者自诉主要为前鼻滴涕，有时鼻分泌物随头部姿势改变而流出，痰多且臭，分泌物为黏液脓性或脓性，经医生诊断为慢性上颌窦炎。上颌窦位于上颌骨体内，开口于","o":["中鼻道","上鼻道","下鼻道","鼻前孔","鼻后孔"],"a":0,"e":"上颌窦位于上颌骨体内，开口于中鼻道的半月裂孔，其开口位置较高，分泌物不易排出，易致慢性炎症。上鼻道为后筛窦开口处；下鼻道为鼻泪管开口处；鼻前孔、鼻后孔为鼻腔的前后出入口，均非上颌窦开口"},{"q":"老年女性患者，股骨头骨折后发现左侧肘关节屈曲无力，前臂外侧皮肤感觉丧失，肱二头肌腱反射消失，可能受损伤的神经是","o":["胸长神经","肌皮神经","正中神经","胸背神经","桡神经"],"a":1,"e":"肌皮神经穿过喙肱肌后行于肱二头肌与肱肌之间，支配这两块屈肘肌，并发出前臂外侧皮神经；损伤表现为屈肘无力、肱二头肌腱反射消失及前臂外侧感觉丧失。桡神经支配伸肌群，损伤致垂腕；腋神经损伤致方肩；胸长、胸背神经不支配屈肘肌"},{"q":"患者，男，60岁。因血尿就诊。医生为其做膀胱镜检查，下镜时需调整阴茎方位以使尿道耻骨前弯消失减轻损伤。关于男性尿道的耻骨前弯，错误的描述是","o":["是阴茎根与体之间的弯","此弯曲凹向下","此弯曲位于耻骨联合前方","由尿道膜部和尿道海绵体构成","向上提阴茎时，此弯曲消失"],"a":3,"e":"耻骨前弯位于耻骨联合前下方、阴茎根与体之间，凹向下，上提阴茎即可消失，由阴茎海绵体部形成，不包括尿道膜部，故该描述错误。耻骨下弯才包含尿道前列腺部、膜部和海绵体部起始段，位置恒定不能消失"},{"q":"患者，男，27岁，棒球选手。在比赛中，前臂被高速球击中，肘前部的深部肌被撕裂。该患者失去功能的肌是","o":["肱桡肌","肱肌和旋后肌","旋前圆肌","旋后肌和旋前方肌","肱肌和旋前圆肌"],"a":4,"e":"肱肌位于上臂前面深层，旋前圆肌居前臂前群，二者均参与屈肘并使前臂旋前，肘前部深部肌撕裂后其功能丧失。肱桡肌位置浅表且主要屈肘；旋后肌、旋前方肌主司前臂旋后或旋前，非肘前屈肌群"},{"q":"患者，男，43岁。因背部外伤，出现下肢二点辨别觉丧失。患者睁眼时，运动尚可，但在闭目时，出现站立不稳，走路如踩棉花。试分析患者哪个传导束受损","o":["楔小脑束","脊髓丘脑束","脊髓小脑前束","脊髓小脑后束","薄束"],"a":4,"e":"薄束传导下半身的意识性本体感觉和精细触觉，司位置觉、两点辨别觉，损伤后深感觉缺失，睁眼可凭视觉代偿，闭目则站立不稳、行走如踩棉花，即感觉性共济失调。脊髓丘脑束传导痛温觉，损伤表现为痛温觉障碍；脊髓小脑前、后束及楔小脑束传导非意识性本体感觉，不产生上述深感觉丧失"},{"q":"患者，男，78岁。左足从麻木、发凉发展至间歇性跛行加重，直至溃疡和坏死。诊断为下肢持续性血管痉挛。可能考虑切除的结构是","o":["马尾","奇神经节","腰交感干","盆内脏神经","骶交感干"],"a":2,"e":"腰交感干发出的灰交通支随腰神经分布至下肢的血管、汗腺和竖毛肌，切除腰交感干可解除下肢血管痉挛、改善循环。奇神经节与骶交感干主要支配会阴和盆腔脏器；马尾为脊神经根；盆内脏神经属副交感，均不支配下肢血管舒缩"},{"q":"患者，男，30岁。因不育就诊。医生检查后告诉小王，其不育的原因在于其生殖器输送管道梗阻。男性生殖器输送管道不包括","o":["附睾","尿道","睾丸","射精管","输精管"],"a":2,"e":"男性生殖管道包括附睾、输精管、射精管和男性尿道，负责精子贮存与运输；睾丸为生殖腺，功能是产生精子和分泌雄激素，不属于输送管道。附睾、输精管、射精管及尿道均为精子排出路径的组成部分，题干所问输送管道不应包含睾丸"},{"q":"患者，男，35岁。因心动过缓入院。心率45次/min。拟行起搏器手术治疗，起搏器导联应该连接到哪个解剖构造","o":["窦房结","房室束","房室结","右束支","左束支"],"a":0,"e":"窦房结是心的正常起搏点，位于上腔静脉与右心房交界处界沟上1／3的心外膜深面，心动过缓型起搏器需将电极导联置于此处或贴近该区。房室结、房室束及左右束支为传导途径的后续结构，主要起传导作用而非主导心率，不作为慢心率的起搏靶点"},{"q":"患者因脑外伤入院，检查发现经检查光照右眼，左眼无对光反射；光照左眼无对光反射，右眼有对光反射，可能损伤了","o":["左视神经损伤","左动眼神经损伤","右视神经损伤","右动眼神经损伤","视交叉中央部损伤"],"a":1,"e":"光照右眼左眼无反应、光照左眼左眼仍无反应而右眼有反应，说明左眼传出通路中断，即左动眼神经损伤，其直接、间接对光反射均消失。左视神经损伤时照左眼双眼无反应、照右眼双眼有反应；右动眼神经损伤体征应在右眼；视交叉中央部损伤致双颞侧偏盲"},{"q":"患者，男，65岁。因排尿困难就诊。临床常见的由于增生而引起老年男性排尿困难的是","o":["睾丸","附睾","前列腺","精囊","尿道球腺"],"a":2,"e":"前列腺增生多发生于中叶和侧叶，增生的腺体压迫尿道，使尿道狭窄、阻力增加，导致老年男性排尿困难甚至尿潴留。睾丸产生精子与雄激素，附睾贮存精子，精囊、尿道球腺为附属腺，这些器官增生均不直接压迫尿道，不致排尿困难"},{"q":"患者，女，40岁。受凉后出现发热、鼻塞、咳嗽，并伴有流泪现象。这是因为","o":["鼻泪管开口处黏膜充血堵塞","结膜有炎症","泪道堵塞","泪囊炎","泪腺分泌过多"],"a":0,"e":"鼻泪管开口处黏膜内含丰富静脉丛，感冒时黏膜充血肿胀致鼻泪管下口闭塞，泪液向鼻腔引流不畅而出现流泪。泪腺分泌过多多因情绪或局部刺激；泪道堵塞、泪囊炎、结膜炎症为独立病变，均非受凉感冒时流泪的主要机制"},{"q":"患者，男，47岁。因车祸受伤后表现为，左侧下肢足尖下垂，不能抬起足尖，不能正常行走。最容易受损的神经是","o":["胫神经","坐骨神经","腓浅神经","腓深神经","闭孔神经"],"a":3,"e":"腓深神经支配小腿前群肌与足背肌，使足背屈、伸趾；受损后前群肌瘫痪，足不能背屈而下垂，伴第1、2趾相对缘感觉障碍，呈跨阈步态。胫神经支配小腿后群，损伤呈钩状足；腓浅神经支配外侧群、主司外翻；闭孔神经支配大腿内收肌群，均不引起足尖下垂"},{"q":"患者，女，45岁。临床诊断宫颈癌行宫颈癌切除术，术后出现排尿功能障碍。可能损伤了下列哪一神经","o":["闭孔神经","阴部神经","内脏大神经","内脏小神经","盆内脏神经"],"a":4,"e":"盆内脏神经起自骶髓S2～S4副交感核，经盆丛支配膀胱逼尿肌，是控制排尿的重要传出通路，宫颈癌根治术清扫盆腔时易损伤，致术后排尿功能障碍。闭孔神经主要支配大腿内收肌群；阴部神经支配尿道括约肌与会阴；内脏大、小神经为胸段交感，均不主导膀胱逼尿肌收缩"},{"q":"老年患者，有长期糖尿病史，近期出现左侧瞳孔不能转向下外，经诊断是脑小血管阻塞，引起的脑神经麻痹。该症状是什么神经麻痹","o":["左动眼神经","右动眼神经","右滑车神经","左滑车神经","左展神经"],"a":3,"e":"上斜肌由滑车神经支配，作用为使瞳孔转向下外方，该神经（左侧）麻痹后瞳孔不能转向下外。动眼神经损伤致上睑下垂、瞳孔散大并斜向外下方；展神经损伤致内斜视；右侧滑车神经损伤影响右眼而非左眼"},{"q":"患者，男，30岁。婚后3年未育。夫妻俩到医院系统检查后，患者被诊断为无精子症。负责产生精子的男性生殖腺是","o":["睾丸","附睾","前列腺","精囊","尿道球腺"],"a":0,"e":"睾丸是男性生殖腺，生精小管产生精子，间质细胞分泌雄激素，无精子症当首先考虑睾丸生精功能障碍。附睾为输精管道，仅贮存并输送精子；前列腺、精囊、尿道球腺属附属腺，分泌液参与精液组成、营养精子，均不产生精子"},{"q":"患儿，男，3岁。因异物吸入呼吸道出现呼吸困难。支气管镜检查发现异物滞留于右主支气管。气管异物易进入右主支气管与其以下特征无关","o":["气管与右主支气管上缘夹角大","右主支气管管径粗","右侧嵴下角小","右主支气管走行相对直","右主支气管分支早"],"a":4,"e":"右主支气管短而粗、嵴下角小、走行较陡直，与气管方向更接近，故异物易坠入；分支早晚与异物进入无关。选项所述夹角大、管径粗、走行直均为易进入的解剖学因素，只有分支早不是相关特征"},{"q":"患者，女，45岁，中上腹饥饿性隐痛反复发作10年，伴反酸、嗳气，进食和服用抑酸剂可缓解。该患者最可能的诊断是十二指肠溃疡。十二指肠溃疡好发部位是","o":["十二指肠降部","十二指肠升部","十二指肠球部","十二指肠下曲","十二指肠水平部"],"a":2,"e":"十二指肠上部近幽门处肠壁薄、管径大、黏膜光滑无环状襞，称十二指肠球，是十二指肠溃疡与穿孔的好发部位。降部有十二指肠大乳头开口，水平部与升部位置较深且受腹膜固定，均非溃疡好发处；下曲为命名上的转折，不是独立好发区"},{"q":"患者，女。急性膀胱尿潴留，需要行导尿术。女性尿道正确的描述是","o":["约长8～10cm","女性尿道短而直","位于阴道下半的后面","尿道下端有尿道、阴道括约肌环绕，不受意识支配","尿道旁腺感染时，可导致尿路阻塞"],"a":1,"e":"女性尿道平均长3～5cm，较男性尿道短、宽而直，故导尿较容易。其长度并非8～10cm；尿道位于阴道前方而非后面；尿道括约肌受意识支配；尿道旁腺感染主要形成前庭大腺脓肿，非尿路阻塞的常见原因"},{"q":"患者，男，18岁。因颈根部刀刺伤就诊。经检查怀疑伤及肺。最有可能刺伤的肺部结构是","o":["肺尖","肺底","肺门","肺根","肺韧带"],"a":0,"e":"肺尖为肺的上端，经胸廓上口突入颈根部，达锁骨内侧三分之一段上方2～3cm，颈根部刀刺伤最易刺伤肺尖。肺底位于膈上方；肺门、肺根为支气管血管进出肺之处，位置偏后内；肺韧带为脏、壁胸膜移行处，均不在颈根部"},{"q":"患者，男，60岁。因痰多、咳嗽就诊，怀疑为下呼吸道感染。可能感染的结构是","o":["鼻腔","口腔","喉腔","气管","胸膜顶"],"a":3,"e":"气管及各级支气管属于下呼吸道，是下呼吸道感染的主要部位。鼻、咽、喉归为上呼吸道；胸膜顶为胸膜的一部分，不属于呼吸道管腔，故均非下呼吸道感染的结构"},{"q":"患者，女，52岁。下楼时，不幸滑倒膝部着地，主诉不能伸膝关节。可能受影响的肌是","o":["半腱肌","缝匠肌","股薄肌","股四头肌","股二头肌"],"a":3,"e":"股四头肌是膝关节唯一的伸肌，跨过髋关节和膝关节前方，既能屈髋又能伸膝，受损后不能伸膝关节。半腱肌、股薄肌、股二头肌均为屈膝肌；缝匠肌可屈膝并使小腿旋内，不参与伸膝"},{"q":"患者，男，55岁。主诉左上颌牙齿疼痛。牙科检查未发现他的牙齿异常。检体时发现患者左上颌有压痛，无过敏史。最可能的诊断是","o":["蝶窦炎","前筛窦炎","后筛窦炎","上颌窦炎","额窦炎"],"a":3,"e":"上颌窦底与上颌磨牙牙根仅隔薄层骨质，窦内炎症可刺激或放射引起上颌牙痛，牙齿本身无异常，故诊断上颌窦炎。额窦炎疼痛居额部；前、后筛窦炎疼痛在眶内或鼻根；蝶窦炎疼痛深在眶后或枕部"},{"q":"患者，男，31岁。因车祸，出现肩胛部压痛，肩关节活动受限。X线诊断为肩胛骨骨折。最常见的骨折是","o":["肩胛颈骨折","肩胛冈骨折","肩胛盂骨折","喙突骨折","肩胛体骨折"],"a":4,"e":"肩胛骨骨折多由直接暴力损伤引起，按部位可分为肩胛体、肩胛颈、肩胛冈、肩胛盂、喙突和肩峰骨折，其中肩胛体骨折最为常见。肩胛颈、肩胛冈、肩胛盂及喙突等部位骨折的发生率均低于体部，并非最常见类型；单纯的肩峰骨折同样少见"},{"q":"患者，男，30岁。因贝内特骨折（第一掌骨基底骨折），出现拇指运动障碍。最有可能损伤的鱼际肌是","o":["拇短展肌","拇短屈肌（浅头）","拇对掌肌","拇收肌","拇短屈肌（深头）"],"a":2,"e":"拇对掌肌起自屈肌支持带与大多角骨，止于第一掌骨，使拇指对掌；贝内特骨折累及第一掌骨基底部及大多角骨构成的腕掌关节，该肌受累最明显。拇短展肌、拇短屈肌主要作用于拇指近节指骨；拇收肌由尺神经支配、止于近节指骨，均非第一掌骨基底骨折直接累及者"},{"q":"患者，男，30岁，高尔夫球手。腿部受伤，导致足不能内翻。最有可能瘫痪的肌是","o":["胫骨后肌","腓骨长肌","腓骨短肌","第三腓骨肌","趾长伸肌"],"a":0,"e":"胫骨后肌止于足舟骨粗隆及楔骨，是使足内翻的主要肌；该肌瘫痪后足不能内翻。腓骨长、短肌与第三腓骨肌均属外侧群，主要使足外翻；趾长伸肌为前群肌、主司伸趾并协助背屈，均不能完成足内翻动作"},{"q":"患者，男，50岁。因腮腺恶性肿瘤，手术切除面神经后，咀嚼后食物滞留于口腔前庭，可能损伤的肌是","o":["咬肌","翼内肌","颞肌","颊肌","翼外肌"],"a":3,"e":"颊肌由面神经颊支支配，收缩时使颊部紧贴牙列，防止食物滞留于口腔前庭；面神经切除后该肌瘫痪，出现食物滞留。咬肌、翼内肌、颞肌、翼外肌均为三叉神经下颌神经支配的咀嚼肌，主司咀嚼运动而非保持颊部张力"},{"q":"患者，男，42岁。2年前出现视近物模糊，视远物清楚，诊断为老视。其解剖学基础是","o":["晶状体曲度变大","晶状体曲度变小","晶状体弹性减弱","角膜曲度变大","晶状体浑浊"],"a":2,"e":"老视因年龄增长使晶状体核增大变硬、弹性减退，睫状肌萎缩，调节能力下降，视近物模糊而视远清楚。晶状体曲度变大则屈光力增强，见于近视或调节状态；晶状体浑浊为白内障；角膜曲度改变非老视的解剖学基础"},{"q":"患者，女，48岁。6个月前发现右颈前一肿物，大小约3cm×3cm。甲状腺彩超：甲状腺右叶3.2cm×3.5cm，左叶1.9cm×1.9cm，峡部厚1.0cm，甲状腺实质回声不均匀，右叶可见大小约3.9cm×3.2cm不均匀回声团，边界欠清，周边及内部可见血流信号。诊断：甲状腺癌。治疗行甲状腺切除术时需要结扎哪几条动脉","o":["甲状腺上、下动脉","颈总动脉","面动脉","颈外动脉","甲状腺中动脉"],"a":0,"e":"甲状腺由甲状腺上动脉（起自颈外动脉）和甲状腺下动脉（起自甲状颈干）供血，甲状腺切除术需结扎此二动脉。颈总动脉、颈外动脉为颈部主干，结扎将影响广泛；面动脉供应面部；甲状腺中动脉并非固定存在的供应动脉，均非本题所指需结扎的血管"},{"q":"患者，男，50岁。因右侧下颌第一磨牙牙龈肿痛就医。与传导该痛觉相关的结构是","o":["孤束","内侧丘系","外侧丘系","脊髓丘系","三叉丘系"],"a":4,"e":"三叉神经传导头面部（含下颌牙及牙龈）的痛温觉，其二级纤维组成三叉丘系上行，故该痛觉与三叉丘系相关。孤束传导内脏感觉和味觉；内侧丘系传导本体感觉和精细触觉；外侧丘系为听觉通路；脊髓丘系传导躯干四肢痛温觉"},{"q":"患者，男，27岁。由于胸小肌瘫痪而无法向前和向下拉伸肩胛骨。最可能的原因是","o":["锁骨骨折","臂丛后索损伤","喙突骨折","腋神经损伤","腋窝后壁缺损"],"a":2,"e":"胸小肌起自第3～5肋，止于肩胛骨喙突，作用是拉肩胛骨向前下方；喙突骨折使该肌止点失效，故出现上述功能障碍。腋神经损伤主要累及三角肌致外展不能，臂丛后索损伤影响桡神经与腋神经，均不选择性瘫痪胸小肌；锁骨骨折亦不直接破坏胸小肌止点"},{"q":"患者，女，72岁。主因眩晕、努嘴、半身不自主运动1天就诊。诊断为间脑出血并发症手足徐动舞蹈样半身舞蹈症。出血位置可能位于","o":["背侧丘脑","底丘脑","上丘脑","下丘脑","后丘脑"],"a":1,"e":"底丘脑核属锥体外系，与苍白球有往返联系并对苍白球起抑制作用，一侧病变可致对侧半身颤搐、舞蹈样不自主运动，故本例出血位于底丘脑。背侧丘脑为感觉中继核；上丘脑参与内脏与嗅觉相关活动；下丘脑调节体温、摄食和内分泌；后丘脑为视听传导中继，均不产生舞蹈样半身动作"},{"q":"患者，女，34岁。因从高处坠落导致左侧上肢不能主动活动，手腕不能抬起，前臂后部的骨骼肌麻痹无力，手背第1、2掌骨之间的皮肤感觉消失。应当考虑最容易受损的神经是","o":["尺神经","腋神经","桡神经","肌皮神经","正中神经"],"a":2,"e":"桡神经支配前臂伸肌群与肱三头肌，在肱骨中段桡神经沟处最易受损；损伤后前臂后部伸肌麻痹致垂腕、手腕不能抬起，并伴第1、2掌骨间背侧皮肤感觉障碍。尺神经损伤以手部内在肌瘫痪为主；腋神经损伤致方肩；肌皮、正中神经损伤均不产生垂腕与该区感觉障碍"},{"q":"患者，男，27岁。车祸后昏迷不醒。检查瞳孔对光反射有助于判断病情。下列参与此反射的结构是","o":["睫状神经节","翼腭神经节","耳神经节","三叉神经节","下颌下神经节"],"a":0,"e":"瞳孔对光反射通路中，动眼神经副交感纤维在睫状神经节换元，节后纤维支配瞳孔括约肌，故睫状神经节参与该反射。翼腭神经节（面神经，司泪腺等）、耳神经节（舌咽神经，司腮腺）、下颌下神经节（面神经，司下颌下腺）、三叉神经节（头面感觉）均不参与"},{"q":"患者，女，30岁。外阴部被撞伤后疼痛难忍并出现肿块。最可能发生血肿的部位是","o":["阴阜","阴蒂","大阴唇","小阴唇","前庭大腺"],"a":2,"e":"大阴唇皮下为疏松结缔组织，富含血管，外阴部撞伤后易形成血肿并出现肿块、疼痛。阴阜皮下为脂肪组织；阴蒂、小阴唇组织较致密且体积小；前庭大腺位于阴道口两侧，损伤以腺体囊肿或脓肿为主，均非外阴血肿最常见的部位"},{"q":"患者，男，48岁。主诉复视（双物象）。医生检查发现左眼内收障碍，并左眼角膜反射缺失。损伤部位最有可能是","o":["眶下裂","视神经孔","眶上裂","圆孔","卵圆孔"],"a":2,"e":"眶上裂有动眼神经、滑车神经、展神经及眼神经通过，损伤后既累及眼球外肌（内收障碍、复视），又累及三叉神经第一支而致角膜反射消失。圆孔仅通上颌神经，卵圆孔通下颌神经，均不支配眼外肌和角膜感觉；视神经孔只通过视神经与眼动脉，损伤表现为视觉障碍而非眼肌麻痹；眶下裂通行眶下血管神经，无上述组合体征"},{"q":"患者，男，40岁。4天前右上唇处有一疖肿，刮脸时不慎刮破，并挤压之，引起面部感染，进而引起颅内感染。以下最先被感染的部位是","o":["横窦","直窦","海绵窦","上矢状窦","下矢状窦"],"a":2,"e":"面静脉在口角以上一般无静脉瓣，并经眼上、眼下静脉及面深静脉-翼静脉丛与海绵窦交通；面部疖肿挤压后细菌可逆行至海绵窦，最先引起海绵窦感染。上、下矢状窦和直窦位于颅内深部，横窦位于颅后，均不与面静脉直接交通"},{"q":"患者，女，30岁。主要症状是患侧前臂和手的疼痛麻木。提携重物可使麻木加重，肩臂抬举时减轻或消失。检查可见患侧肩下移，锁骨上方可触得有搏动而震颤的块状物，有压痛；颈肩活动正常；牵拉患侧上肢并将头颈向对侧推移时，患侧桡动脉搏动减弱或消失；手力量减弱；患侧眼部可见有霍纳综合征。X射线检查可见有颈肋过长。诊断为胸廓上口综合征。组成胸廓上口的结构是","o":["由胸骨角、第1对肋及第1胸椎椎体围成","由胸骨剑突、第1对肋及第1胸椎椎体围成","由胸骨柄上缘、第1对肋及第1胸椎椎体围成","由胸骨柄上缘、锁骨及第1胸椎椎体围成","由胸骨柄上缘、第1对肋及第7颈椎椎体围成"],"a":2,"e":"胸廓上口较小，由胸骨柄上缘、第1对肋和第1胸椎椎体围成，是胸腔与颈部的通道。胸骨角、剑突均非上口边界；锁骨不参与围成；第7颈椎椎体位置过高，均不符合胸廓上口的构成"},{"q":"患者，男，20岁。感冒1周，逐渐出现耳部不适，发闷、疼痛，初步诊断为中耳炎。上呼吸道感染可以引起中耳炎，与下列哪个解剖结构有关","o":["鼓室","咽鼓管","外耳道","乳突窦","鼻咽"],"a":1,"e":"咽鼓管连通鼻咽与中耳鼓室，咽部感染可沿此管蔓延至中耳，是上呼吸道感染并发中耳炎的解剖学基础。鼓室、乳突窦属中耳腔隙而非通道；外耳道与中耳间隔鼓膜；鼻咽仅为咽鼓管咽口所在部位"},{"q":"患者，男，55岁。因脑干肿瘤压迫动脉后出现左侧头面部痛温觉障碍，右上、下肢及躯干意识性本体感觉和精细触觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧内侧丘系、左侧脊髓丘脑束","左侧三叉神经脊束、左侧内侧丘系","右侧三叉神经脊束、右侧脊髓丘脑束","左侧内侧丘系、右侧脊髓丘脑束","左侧三叉神经脊束、右侧内侧丘系"],"a":1,"e":"左侧头面部痛温觉障碍由左侧三叉神经脊束受损所致，该束传导同侧面部痛温觉。右上、下肢及躯干意识性本体感觉障碍提示内侧丘系受损，此束在延髓已交叉，左侧损伤表现为对侧即右侧障碍，故为左侧三叉神经脊束与左侧内侧丘系。右侧三叉神经脊束损伤引起右侧面部障碍；左侧内侧丘系损伤则表现为右侧躯干四肢障碍"},{"q":"患者，女，22岁。头部受伤3小时入院。查体时发现：患者对呼唤有睁眼反应，能躲避刺痛，但叙述问题错误，眼眶青紫，球结膜下瘀斑，鼻腔有血性脑脊液流出，诊断结果为颅前窝骨折。组成颅前窝的结构不包括","o":["筛骨筛板","额骨眶部","蝶骨小翼","眶上裂","鸡冠"],"a":3,"e":"颅前窝由额骨眶部、筛骨筛板及蝶骨小翼等构成，鸡冠为筛骨结构，位于颅前窝；眶上裂为蝶骨大、小翼之间的裂隙，通颅中窝，不属于颅前窝组成。筛板损伤可致嗅神经撕脱与脑脊液鼻漏，出现眼眶青紫、球结膜下瘀斑等颅前窝骨折表现"},{"q":"患者，女，56岁。有风湿性心脏病史，一直服用药物治疗，近期出现心脏衰竭入院。入院彩超检查发现三尖瓣狭窄严重，拟行手术瓣膜置换治疗。手术过程中应注意避免损失的是","o":["Bachmann束","Wenchebach束","Thorel束","His束","Koch三角"],"a":3,"e":"房室束起自房室结前端，穿右纤维三角后沿室间隔膜部后下缘下行，紧邻三尖瓣隔侧瓣附着处，三尖瓣手术在此区操作易损伤，造成房室传导阻滞。其他三束为心房内传导束；Koch三角是定位房室结的标志区域，并非本题需避免损伤的传导束本身"},{"q":"患者，男，30岁。因急性阑尾炎行阑尾切除术，在手术时寻找阑尾最可靠的方法是","o":["在右髂窝内寻找","McBurney点的深面","在回盲部寻找","沿盲肠的结肠带向下寻找","在盲肠的末端寻找"],"a":3,"e":"结肠带为结肠纵行肌增厚形成，三条结肠带均会聚于阑尾根部，其中独立带最明显，故沿盲肠结肠带向下追踪是术中寻找阑尾最可靠的方法。阑尾根部体表投影为麦氏点，但位置变异大；仅在右髂窝或回盲部寻找并不如沿结肠带追踪可靠"},{"q":"患者，男，45岁。主诉：阵发性全腹痛，伴恶心、呕吐8小时。现病史：患者于入院当日晨7时早饭后到田间劳动，9时左右突然感到全腹剧痛，以脐周为甚，如刀割样，恶心及呕吐，突出物为所进食的稀饭，并觉全身出冷汗，即到当地医院诊治，经注射止痛针后，症状略缓解，但半小时后又发作剧痛，呈持续性，阵发性加剧，无放射性，辗转不安，不愿平卧，呕吐频繁，自觉腹部逐渐膨胀，因而用车转送入院。起病后无发热，无大便及肛门排气，小便1次，量少而赤。体格检查发现肠型，有腹膜刺激征。X线腹部透视可见小肠扩张及有多个大小不等的、呈阶梯状的积液平段。初步诊断为肠梗阻。行开腹探查术，术中见小肠有坏死现象，行小肠切除术，需结扎肠系膜上动脉。有关肠系膜上动脉的说法，下列正确的是","o":["平第12胸椎发自腹主动脉","营养全部小肠","行于肠系膜内","分布于全部结肠","经十二指肠水平部的后方下行"],"a":2,"e":"肠系膜上动脉约平第1腰椎发自腹主动脉前壁，行于小肠系膜内，发出空、回肠动脉并形成多级动脉弓。它平第12胸椎发自腹主动脉的说法错误；十二指肠由腹腔干供血，故不营养全部小肠；结肠仅右半由其供血；该动脉经十二指肠水平部前方而非后方下行"},{"q":"患者，男，45岁。因外伤后右眼出现斜视，诊断为内直肌瘫痪。其可能出现的斜视为","o":["内上斜视","外下斜视","内斜视","外斜视","外上斜视"],"a":3,"e":"内直肌由动眼神经支配，收缩时牵拉瞳孔转向内侧；该肌瘫痪后外直肌失去拮抗，眼球被拉向外侧，形成外斜视。内斜视实为外直肌麻痹、展神经受损所致；上斜肌或下直肌瘫痪分别表现为眼球外下或上内方向运动障碍，均非内直肌损伤体征"},{"q":"患者因颅内肿瘤入院，入院检查发现患者意识清楚但角膜反射消失。其颅内肿瘤可能损伤了什么神经","o":["视神经或动眼神经","视神经或三叉神经","动眼神经或三叉神经","三叉神经或面神经","动眼神经或面神经"],"a":3,"e":"角膜反射的传入通路为眼神经（三叉神经第一支）传导角膜感觉，传出通路为面神经支配眼轮匝肌闭眼，两环任一中断反射即消失。视神经司视觉、动眼神经司眼球运动与瞳孔缩小，均不参与角膜反射弧，视神经或动眼神经受损不会造成单纯角膜反射消失"},{"q":"患儿，男，12岁。半年前因摔伤后出现歪头视物，视力正常，诊断为右眼上斜肌麻痹。其受累的神经为","o":["动眼神经","滑车神经","展神经","眼神经","视神经"],"a":1,"e":"滑车神经支配上斜肌，该肌收缩使瞳孔转向下外方；滑车神经受损后上斜肌麻痹，出现歪头视物以代偿。动眼神经支配上直肌、下直肌、内直肌、下斜肌和上睑提肌；展神经支配外直肌；眼神经与视神经分别为感觉神经，均不支配上斜肌"},{"q":"患者，男，52岁，是一位搬运工。一次搬重物后，腰部疼痛，一侧下肢麻木、疼痛症状。经检查诊断为腰4～5腰椎间盘突出症。椎间盘的纤维环破裂，髓核易向","o":["后外侧脱出","后内侧脱出","前外侧脱出","前内侧脱出","向正前方脱出"],"a":0,"e":"纤维环后外侧部相对薄弱且缺乏后纵韧带中间部的加强，髓核易向后外侧脱出，突入椎管或椎间孔压迫神经根。椎体前方有前纵韧带、后方有后纵韧带阻挡，故前外侧、前内侧及正前方脱出均少见"},{"q":"患儿，女，10岁。感冒后出现声音嘶哑，咽喉部疼痛、刺痒，有异物感。逐渐发展为吸气性呼吸困难。入院诊断为急性喉炎伴喉黏膜水肿。喉黏膜水肿最有可能发生的部位是","o":["喉前庭黏膜","喉中间腔黏膜","喉室黏膜","声门下腔黏膜","喉口处黏膜"],"a":3,"e":"声门下腔位于声襞与环状软骨下缘之间，其黏膜下组织疏松，炎症时易发生水肿；婴幼儿喉腔狭小，水肿更易阻塞气道致吸气性呼吸困难。喉前庭、喉中间腔、喉室黏膜下组织较致密；喉口为喉腔上口，均非急性喉炎水肿的最常见部位"},{"q":"患者，男，42岁。间歇性发热5天。入院查体肝区有叩痛，CT见肝右叶脏面有数个液性暗区，考虑为肝脓肿。医生嘱咐该患者应避免仰卧位，是为了避免脓液在下列哪个间隙积聚","o":["网膜囊","肝肾隐窝","右结肠旁沟","右肠系膜窦","腹膜外间隙"],"a":1,"e":"肝肾隐窝位于肝右叶脏面与右肾、右肾上腺之间，仰卧位时是腹膜腔最低部位，肝脓肿脓液易向此处积聚，故嘱患者避免仰卧。网膜囊位于小网膜与胃后方；右结肠旁沟、右肠系膜窦位置相对偏高或偏下；腹膜外间隙不与腹膜腔相通，均非仰卧位最先积聚处"},{"q":"患者，女，55岁。有风湿病史，经检查发现三尖瓣狭窄比较严重，入院后决定进行更换三尖瓣治疗。在手术治疗过程中，为了防止误伤右束支，应注意保护的解剖结构是","o":["卵圆窝","Todaro腱","Koch三角","隔缘肉柱","室间隔膜部"],"a":3,"e":"右束支自房室束分叉后经室间隔膜部下缘进入隔缘肉柱（节制索）达前乳头肌，该肉柱是右心室手术的重要保护结构。卵圆窝为房间隔薄弱区；Todaro腱和Koch三角标志房室结位置；室间隔膜部本身是室间隔缺损好发处，均非右束支走行通道"},{"q":"患者，女，48岁。因肝癌需行肝左叶切除术。关于肝的分叶的描述，正确的是","o":["两个半肝，2个叶","两个半肝，3个叶","两个半肝，4个叶","两个半肝，5个叶","两个半肝，6个叶"],"a":3,"e":"按Couinaud肝段划分法，肝先分为左、右半肝，再分为5个叶和8个段，据此可行精准的肝叶或肝段切除。2、3、4、6个叶的说法均不符合Couinaud分段法，故不成立"},{"q":"患者，女，52岁。因脑干肿瘤压迫动脉后出现右侧上、下肢及躯干痛、温觉障碍，右侧上、下肢及躯干意识性本体感觉和精细触觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧内侧丘系、左侧脊髓丘脑束","右侧三叉神经脊束、左侧脊髓丘脑束","右侧内侧丘系、右侧脊髓丘脑束","左侧三叉神经脊束、右侧脊髓丘脑束","左侧三叉神经脊束、右侧内侧丘系"],"a":0,"e":"右侧躯干四肢痛温觉及意识性本体感觉、精细触觉均障碍，说明感觉传导束在交叉后受损，故为左侧脊髓丘脑束与左侧内侧丘系同时损伤。三叉神经脊束司同侧头面部痛温觉，本题病变在躯干四肢；若损伤在右侧，症状应出现在左侧"},{"q":"患者，男，67岁。因酒后不慎摔伤头部伴意识不清1小时急诊收入院。入院查体：T 36、5℃，BP 150/80mmHg，P 67次/min，R 18次/min；患者神志清楚，查体合作；双侧瞳孔等大等圆，直径2.5mm，对光反射存在；颈抵抗阴性；双肺呼吸音清；心律齐；腹软，无压痛；肝脾肋下未及，对疼痛刺激反应敏感，语言对答如流。诉右额颞部及后枕部胀痛激烈难忍，肢体活动好。CT：右侧额颞叶硬膜外血肿，后枕部血肿，约10ml，脑挫裂伤；约30分钟后患者出现呼之不应。查体：不合作，对疼痛刺激反应减弱，右侧瞳孔大于左侧，直径4mm∶2.5mm，对光反射存在，P 54次/min，R 16次/min，BP 170/70mmHg，血氧饱和度90%。关于引起血肿的脑膜中动脉的起源及入颅部位的描述，正确的是","o":["经圆孔进入颅腔","颈外动脉的直接分支","颈内动脉的分支","经卵圆孔进入颅腔","上颌动脉的分支"],"a":4,"e":"脑膜中动脉是上颌动脉的分支，经棘孔入颅，颞部骨折易损伤该动脉形成硬膜外血肿。该动脉并非颈外动脉的直接分支（上颌动脉才是）；颈内动脉不发出此支；圆孔通上颌神经、卵圆孔通下颌神经，均非其入颅通道"},{"q":"患者因急性排尿困难伴会阴部疼痛不适就诊。医生检查后诊断为：男性尿道第2个生理性狭窄结石梗阻。该狭窄位于","o":["尿道内口","尿道膜部","尿道球部","尿道外口","舟状窝"],"a":1,"e":"男性尿道有三个狭窄，依次为尿道内口、尿道膜部和尿道外口，其中膜部为第二狭窄，穿过尿生殖膈，故第二处结石梗阻定位于此。尿道球部属于膨大而非狭窄；舟状窝位于阴茎头内；尿道外口为第三狭窄且最窄，均非第二狭窄"},{"q":"患者，男，38岁。发现四肢肥大10余年。检查可见手指、脚趾肥大，下颌突出，鼻子增大。医生诊断为肢端肥大症。该病为下列哪个结构异常分泌激素促进骨的生长发育所致","o":["肾上腺皮质","肾上腺髓质","垂体前叶","垂体后叶","胸腺"],"a":2,"e":"腺垂体远侧部与结节部合称垂体前叶，分泌生长激素，促进骺软骨生长和骨发育；成年后骨骺闭合，生长激素过多致肢端肥大症，表现为手足肥大、下颌突出、鼻大。垂体后叶仅贮存释放抗利尿激素和缩宫素；肾上腺皮质、髓质及胸腺分泌的激素均不刺激骺软骨使骨增长"},{"q":"患者，男，49岁。因强直性脊柱炎引起脊柱变形（驼背）。引起形态改变的原因是","o":["颈椎后突","胸椎前突","胸椎后突","腰椎后突","腰椎前突"],"a":2,"e":"胸椎本身具有生理性后凸，强直性脊柱炎使脊柱韧带骨化、前纵韧带收缩，胸椎后凸进一步加重形成驼背。颈椎生理性前凸、腰椎生理性前突，均不形成驼背；胸椎前突和腰椎后突与胸椎正常曲度及该病改变不符"},{"q":"患者，男，19岁。感冒发热1周，耳部疼痛，发闷，听力下降。医生欲行鼓膜检查。检查该患者外耳道和鼓膜时，应将耳郭拉向","o":["后上方","前上方","后下方","前下方","后方"],"a":0,"e":"成人外耳道呈弯曲状，检查时须将耳郭向后上方牵拉才能使其变直、窥见鼓膜。婴幼儿颞骨未骨化，外耳道短直且鼓膜近水平位，应拉向后下方；前上方、前下方及单纯向后均不能充分拉直成人外耳道"},{"q":"患者，男，40岁。原因未明的胸腔积液，需作胸膜腔诊断性穿刺，作胸腔积液涂片、培养、细胞学和生化学检查以明确病因。一般常取肩胛线第7～8肋间进行，触摸到的肩胛下角平对","o":["第6肋","第7肋","第8肋","第9肋","第10肋"],"a":1,"e":"肩胛下角平对第7肋或第7肋间隙，是背部计数肋骨和确定穿刺肋间的重要骨性标志。第6、8、9、10肋均非肩胛下角的对应平面，据此定位胸膜腔穿刺肋间会产生偏差"},{"q":"患者，女。近期感觉下腹部有坠落感及月经量大而入院就诊。B超及子宫镜确诊为子宫黏膜下肌瘤。此患者行全子宫切除术时，不需要切除哪一韧带","o":["子宫阔韧带","子宫圆韧带","子宫主韧带","子宫骶韧带","骨盆漏斗韧带"],"a":4,"e":"骨盆漏斗韧带即卵巢悬韧带，自小骨盆侧缘连至卵巢输卵管端，内含卵巢动静脉，是寻找卵巢血管的标志；全子宫切除保留卵巢时无须切断该韧带。子宫阔韧带、圆韧带、主韧带和骶韧带均属维持子宫正常位置的韧带，切除全子宫时均需一并切断处理"},{"q":"患者，男，57岁。左季肋部被汽车撞伤5小时，口渴、心悸、头晕1小时入院。患者5小时前被汽车撞中左季肋部，当时疼痛剧烈，即至医院就诊。诊断为左胸肋骨骨折，卧床休息和局部固定后感觉好转，1小时前觉全腹疼痛发胀，伴头晕、心悸，口渴、烦躁。查体：体温37.0℃，脉搏110次/min，血压92/60mmHg，神清，面色苍白，心肺（-），左季肋部皮下瘀斑、压痛，腹稍胀，全腹有明显压痛，以左上腹为著，肌紧张不明显，但有明显反跳痛，移动性浊音（±），肠鸣音可闻，弱。化验：血红蛋白80g/L，白细胞90×109/L。诊断：①脾破裂，腹腔内出血；②左胸肋骨骨折。开腹探查：脾切除。问脾动脉分支分布范围不包括","o":["胃","胰","胆囊","大网膜","脾"],"a":2,"e":"脾动脉为腹腔干分支，沿途发出胃后动脉、胰支及胃网膜左动脉、短动脉等，分布于脾、胰、胃及大网膜。胆囊由胆囊动脉供血，该动脉多起自肝固有动脉右支，不在脾动脉分布范围内；其余器官均接受脾动脉分支供应"},{"q":"患者，男，65岁。表现为静止性震颤，临床诊断为帕金森病。与此病病理变化相关的是","o":["皮质-新纹状体-背侧丘脑-皮质环路","新纹状体-黑质环路","苍白球-底丘脑环路","皮质-脑桥-小脑-皮质环路","胆碱能通路"],"a":1,"e":"新纹状体-黑质环路中，黑质神经细胞产生并释放多巴胺，黑质变性使纹状体多巴胺含量降低，导致帕金森病静止性震颤。皮质-新纹状体-背侧丘脑-皮质环路与苍白球-底丘脑环路属其他锥体外系通路；皮质-脑桥-小脑-皮质环路参与运动协调；胆碱能通路非本病主要病理基础"},{"q":"患者，男，50岁。在闭眼时不能确定损伤左侧关节的位置、运动方向以及两点间距离，损伤的结构有可能是","o":["右侧薄束","右侧楔束","右侧内侧丘系","右侧脊髓胸核","小脑右半部分"],"a":2,"e":"意识性本体感觉和精细触觉传导束在延髓交叉后形成内侧丘系，交叉以上损伤表现为对侧肢体关节位置觉、运动觉及两点辨别觉障碍，故左侧关节障碍定位于右侧内侧丘系。薄束、楔束位于交叉以下的脊髓，损伤在同侧；脊髓胸核与小脑参与非意识性本体感觉或协调运动"},{"q":"患者，女，50岁。脑出血后，出现典型的“三偏”症状。临床诊断为内囊病变。其破裂出血的血管可能是","o":["脉络丛前动脉","大脑前动脉","前交通动脉","迷路动脉","豆纹动脉"],"a":4,"e":"豆纹动脉由大脑中动脉中央支发出，垂直穿前穿质供应尾状核、豆状核及内囊膝和后肢前部，行程呈S形弯曲，高血压动脉硬化时易破裂出血，故又称出血动脉，损伤后出现对侧三偏症状。脉络丛前动脉供应内囊后肢后下部等；大脑前动脉、前交通动脉及迷路动脉均非内囊主要供血来源"},{"q":"患者，女，25岁。因咳嗽、胸痛就诊。胸部平片显示胸腔积液。正常情况下，在腋中线处，胸膜腔的最低点位于","o":["第6肋","第7肋","第8肋","第10肋","第11肋"],"a":3,"e":"胸膜下界在腋中线与第10肋相交，为胸膜腔的最低点，胸腔积液首先积聚于此。锁骨中线处胸膜下界平第8肋，肩胛线处平第11肋；肺下界较胸膜下界高约两个肋，腋中线处仅平第8肋，故第6、7、11肋均非腋中线胸膜腔最低点"},{"q":"患儿，女，5岁。近2天腰痛，两腿痛。突然发热39.5℃。次日早晨不能下床，左下肢不能活动。检查：发现头、颈、两上肢和右腿无运动障碍，左下肢完全瘫痪，左腿肌张力减退，腱反射（膝和跟腱）消失。3周后，左大腿能够屈收，并能伸膝，但其他运动未见恢复。1个月后，足肌、小腿肌及大腿后面肌松弛，明显萎缩。无其他任何感觉障碍。试分析脊髓损伤的主要节段","o":["L4～S2","L1～L4","L2～S2","L1～L3","S1～S3"],"a":0,"e":"3周后大腿能屈收并伸膝，说明髂腰肌与股四头肌功能保留；足肌、小腿肌及大腿后面肌瘫痪萎缩，提示病变累及L4～S2节段。L1～L3或L1～L4范围偏高，不能解释小腿与足肌的广泛瘫痪；S1～S3范围偏低，无法涵盖伸膝保留而大腿后肌受累的平面"},{"q":"患者，男，25岁。1年前发现左颈部圆形包块，表面光滑，可活动；1年内包块缓慢长大，时有压迫感，无其他自觉症状。入院诊断为“左迷走神经鞘瘤”。若该肿瘤持续长大，患者最可能出现以下哪种症状","o":["声音嘶哑","伸舌无力","垂肩","鼻唇沟变浅","不能闭眼"],"a":0,"e":"迷走神经发出喉返神经支配声带肌，肿瘤压迫或侵犯致声带麻痹，出现声音嘶哑。伸舌无力属舌下神经损害；垂肩为副神经支配的斜方肌瘫痪；鼻唇沟变浅、不能闭眼为面神经（面肌）损伤表现，均非迷走神经支配范围"},{"q":"患者，女，50岁。在锁骨上三角内触到了肿大的左锁骨上淋巴结。该肿瘤细胞来源于下列哪个器官","o":["甲状腺","胸腺","胃","睾丸","气管"],"a":2,"e":"胃癌等胸腹盆恶性肿瘤的癌细胞栓子可经胸导管转移至左锁骨上即Virchow淋巴结，表现为胸锁乳突肌后缘与锁骨上缘夹角处无痛性肿大淋巴结。甲状腺、胸腺多经邻近淋巴结引流；睾丸淋巴上行注入腰淋巴结；气管淋巴汇入纵隔淋巴结，均不常转移至左锁骨上"},{"q":"患者，男，45岁。自诉外出时不慎迷眼，出现明显异物感，伴有畏光及流泪。下列结构中可能伤及的是","o":["结膜","虹膜","角膜","眼睑","巩膜"],"a":2,"e":"角膜富含感觉神经末梢，异物或擦伤时立即出现明显异物感、畏光和流泪。结膜、眼睑、巩膜的感觉相对迟钝，异物感不著；虹膜位于眼内，一般异物存留于结膜囊或角膜表面，不易直接伤及"},{"q":"患者，男，30岁。车祸导致近侧腕骨损伤。最有可能损伤的骨是","o":["头状骨","钩骨","大多角骨","三角骨","小多角骨"],"a":3,"e":"腕骨近侧列由桡向尺依次为手舟骨、月骨、三角骨和豌豆骨，四者构成桡腕关节的近侧关节面；三角骨属于近侧列，故近侧腕骨损伤最可能为三角骨。头状骨、钩骨、大多角骨和小多角骨均属远侧列，与远侧列腕骨相邻，不在近侧腕骨之列"},{"q":"患儿，男，4岁。因呼吸困难不能平卧1年入院。可能是以下哪个结构的肥大","o":["舌扁桃体","咽扁桃体","腭舌弓","咽鼓管扁桃体","腭咽弓"],"a":1,"e":"咽扁桃体位于鼻咽部上壁后部，幼儿时期较发达，6～7岁开始萎缩；异常增大可阻塞鼻咽腔，致呼吸困难、张口呼吸。舌扁桃体在舌根、咽鼓管扁桃体在咽鼓管咽口周围、腭扁桃体在口咽，均非幼儿鼻咽部阻塞的主因；腭舌弓、腭咽弓为黏膜皱襞"},{"q":"患者，女，45岁。因车祸导致左侧股骨髁上骨折，表现为小腿后群肌麻痹，足不能用足尖站立，足底皮肤感觉障碍。最容易受损的神经是","o":["股神经","胫神经","腓总神经","腓浅神经","坐骨神经"],"a":1,"e":"胫神经支配小腿后群肌并分布于足底皮肤，股骨髁上骨折易伤及腘窝处胫神经，致足不能跖屈、不能足尖站立及足底感觉障碍。腓总神经于腓骨颈损伤致足下垂、马蹄内翻足及足背感觉障碍；腓浅神经仅支配小腿外侧群；坐骨神经为总干，股神经支配股四头肌主伸膝，均不合本例"},{"q":"患者，女，50岁。伸舌时舌尖偏向右侧，为下面哪块肌肉瘫痪","o":["左侧颏舌肌","左侧舌骨舌肌","右侧颏舌肌","右侧舌骨舌肌","左侧茎突舌肌"],"a":2,"e":"颏舌肌单侧收缩使舌尖伸向对侧，一侧瘫痪时伸舌则偏向瘫痪侧，故舌尖偏右为右侧颏舌肌瘫痪。舌骨舌肌、茎突舌肌主要牵舌向后或后上，不主导伸舌方向；左侧颏舌肌瘫痪时舌尖应偏向左侧"},{"q":"患者，女，39岁。手术中发现胸导管上段损伤。可能出现的是下述哪种情况","o":["下肢水肿","右侧乳糜胸","上肢水肿","眼睑水肿","左侧乳糜胸"],"a":4,"e":"胸导管上段位于左侧纵隔，注入左静脉角，手术损伤后乳糜液溢入左侧胸膜腔形成左侧乳糜胸。胸导管下段才偏向右侧，损伤引起右侧乳糜胸；上、下肢水肿及眼睑水肿与淋巴或静脉回流受阻有关，并非胸导管上段损伤的直接后果"},{"q":"患者，男，56岁。表现为舌下神经交叉性偏瘫的症状，临床影像学资料表明，出现血管栓塞，可能发生栓塞的动脉是","o":["豆纹动脉","椎动脉延髓支","基底动脉分支","小脑上动脉分支","大脑后动脉分支"],"a":1,"e":"舌下神经交叉性偏瘫即延髓内侧综合征，由椎动脉延髓支阻塞引起，损伤同侧舌下神经根致伸舌偏向患侧、对侧锥体束致对侧肢体瘫、内侧丘系致对侧深感觉障碍。豆纹动脉为大脑中动脉分支；基底动脉及其分支、小脑上动脉、大脑后动脉均供应脑干以外或不同区域，不产生此组合体征"},{"q":"患者，女，27岁。停经6周，突发左下腹痛2小时，伴有里急后重。诊断考虑输卵管妊娠伴急性破裂。此时如果B超检查会发现积液会积聚在","o":["阴道后穹隆","阴道侧穹隆","膀胱子宫陷凹","直肠子宫陷凹","阴道前穹隆"],"a":3,"e":"直肠子宫陷凹又称Douglas腔，是站立或坐位时女性腹膜腔最低部位，输卵管妊娠破裂出血积聚于此，可经阴道后穹穿刺引流。膀胱子宫陷凹较浅，不易积聚大量积液；阴道后穹隆为穿刺部位而非积液腔隙；阴道前、侧穹隆与腹膜腔最低处无关"},{"q":"患者，男，30岁。右下腹持续疼痛，伴发热1天。查体见全腹紧张，右下腹压痛明显，且有反跳痛，肠鸣音弱，初步诊断为腹部器官病变伴发急性腹膜炎。请问，可能发生病变的器官是","o":["膀胱","输尿管结石","阑尾","肾","直肠"],"a":2,"e":"阑尾根部位于右髂窝，炎症初期疼痛常始于脐周后转移并局限于右下腹，伴反跳痛提示壁层腹膜受累。膀胱、输尿管、肾为泌尿器官，疼痛位于腰部或耻骨上并伴泌尿症状；直肠病变多表现为下腹坠胀和排便改变，均非转移性右下腹痛"},{"q":"患者，男，24岁。背部被刺伤，导致脊髓侧索被切断。可造成切断部位的功能障碍包括","o":["同侧随意运动及深、浅部感觉丧失","同侧随意运动丧失及对侧痛、温度觉障碍","同侧腱反射消失，触觉和压觉丧失","同侧痛、温度觉全部丧失","对侧随意运动丧失"],"a":1,"e":"脊髓侧索内含同侧皮质脊髓束和已交叉的脊髓丘脑束，横断后损伤平面以下同侧随意运动丧失，并出现对侧痛温觉障碍，即布朗-塞卡综合征表现。同侧深感觉丧失见于后索损伤；痛温觉在同侧全部丧失不符合交叉特点；对侧随意运动丧失提示锥体束在交叉以上受损"},{"q":"患者，女，49岁。因脑干肿瘤压迫动脉后出现左侧眼球外直肌麻痹，双眼左侧凝视麻痹，左侧面肌麻痹，眩晕，眼球震颤，左侧头面部痛温觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧展神经、左侧面神经、左侧前庭蜗神经、左侧三叉神经脊束","右侧展神经、右侧面神经、右侧前庭蜗神经、右侧三叉神经脊束","右侧展神经、左侧面神经、左侧前庭蜗神经、左侧脊髓丘脑束","左侧展神经、左侧面神经、左侧前庭蜗神经、左侧脊髓丘脑束","右侧展神经、右侧面神经、右侧前庭蜗神经、右侧脊髓丘脑束"],"a":0,"e":"左侧眼球外直肌麻痹、双眼左侧凝视麻痹为左侧展神经（核）受损；同侧面肌麻痹为左侧面神经核受损；眩晕、眼震为左侧前庭神经核受损；左侧头面部痛温觉障碍为左侧三叉神经脊束受损。脊髓丘脑束司对侧躯干四肢痛温觉；右侧结构损伤症状应在右侧"},{"q":"患者，男，70岁。轻微外力跌倒时，腕关节处于背伸及前臂旋前位、手掌着地，暴力集中于桡骨远端松质骨处而引起骨折。检查发现骨折远端向背侧及桡侧移位，可诊断为","o":["桡骨远端伸直型骨折（Colles骨折）","桡骨远端屈曲型骨折（Smith骨折）","桡骨干骨折","桡骨头骨折","桡骨颈骨折"],"a":0,"e":"跌倒时腕关节背伸、前臂旋前手掌着地，暴力集中于桡骨远端松质骨，骨折远端向背侧及桡侧移位，为伸直型Colles骨折。屈曲型骨折远端向掌侧移位；桡骨干、桡骨头及桡骨颈骨折的受伤机制与移位方向均与本例不符"},{"q":"患者，男，38岁。因头部外伤后出现左眼瞳孔不能转向内方。受累的眼外肌是","o":["外直肌","内直肌","下斜肌","上斜肌","上直肌"],"a":1,"e":"内直肌收缩使瞳孔转向内侧，由动眼神经支配；该肌受损后瞳孔不能转向内方。外直肌由展神经支配、使瞳孔转向外侧；上斜肌由滑车神经支配、使瞳孔转向下外；下斜肌使瞳孔转向上外；上直肌使瞳孔转向上内，均不能使瞳孔内转"},{"q":"患者，女，28岁。颅内压增高，被诊断为小脑幕切迹疝。最易压迫的神经","o":["动眼神经","展神经","滑车神经","眼神经","视神经"],"a":0,"e":"小脑幕切迹疝时海马旁回和钩被挤入小脑幕切迹，直接压迫大脑脚和动眼神经，并牵拉大脑后动脉，导致同侧瞳孔散大、对光反射消失等动眼神经麻痹体征。展神经、滑车神经行程远离切迹；视神经在鞍上前部；眼神经为三叉神经分支，均非最先受压者"},{"q":"患者，男，35岁。因心律失常入院。经24小时动态心电图检查，诊断为室上性心动过速。这种疾病最有可能是哪个解剖结构异常造成的","o":["窦房结","房室束","房室结","右束支","左束支"],"a":2,"e":"房室交界区（含房室结）是心房至心室兴奋传导的必经之路，也是最重要的次级起搏点，许多室上性心动过速起源于此。窦房结为正常起搏点，其异常多表现为窦性心律失常；房室束及左、右束支病变主要导致传导阻滞"},{"q":"患者，男，68岁。近期劳累后感觉胸前区和左臂内侧皮肤疼痛。根据牵涉性痛的特点，应当首先考虑下列哪一器官可能出现病变","o":["胆囊","肝","胃","左肺","心"],"a":4,"e":"心绞痛时常在胸前区及左上臂内侧皮肤产生牵涉性痛，因心脏与该区感觉神经进入同一脊髓节段。肝胆疾患牵涉痛多在右肩部；胃痛多位于上腹部；肺本身痛觉不敏感，左肺病变非此典型牵涉痛的原因"},{"q":"患者以过度嗜睡、猝倒、睡眠瘫痪及入眠期幻觉等症状入院，诊断为发作性嗜睡。引起该疾病的原因可能是","o":["下丘脑外侧区的网状激活系统受损","结节漏斗核受损","下丘脑腹后内侧核受损","鞍区受损","丘脑核受损"],"a":0,"e":"发作性嗜睡与觉醒-睡眠周期调节障碍有关，下丘脑外侧区网状激活系统受损使大脑皮质觉醒维持不足，出现过度嗜睡、猝倒等表现。结节漏斗核参与垂体门脉激素调节；腹后内侧核为味觉与三叉感觉中继；鞍区病变多影响垂体，均不主导觉醒"},{"q":"患儿，男，16岁。查体：环指掌指关节不能屈和内收。最有可能瘫痪的肌是","o":["指深屈肌","指伸肌","蚓状肌","骨间侧背肌","骨间掌侧肌"],"a":4,"e":"骨间掌侧肌起自第2、4、5掌骨，作用为内收第2、4、5指并屈掌指关节，环指（第4指）不能屈和内收提示该肌瘫痪。骨间背侧肌作用为外展手指；蚓状肌屈掌指关节但无内收作用；指深屈肌屈指远节；指伸肌伸指"},{"q":"某患者左侧舌前2/3味觉障碍，左侧舌下腺、左下颌下腺分泌障碍，左眼不能闭合，左侧额纹消失，左侧鼻唇沟消失，口角偏向右侧。该患者病变可能在","o":["右面神经与脑干相连处","左侧舌神经","左侧面神经","右侧皮质核束","右侧大脑皮质中央前回下1/3"],"a":2,"e":"面神经管内损伤使同侧表情肌瘫痪，额纹消失、眼不能闭合、鼻唇沟变浅、口角歪向健侧，鼓索受累致舌前2/3味觉障碍及下颌下腺、舌下腺分泌障碍，口角偏向右侧说明病灶在左侧面神经。右侧皮质核束或中央前回下1/3损伤属核上瘫，只累及下半面肌，额纹存在、眼可闭合；舌神经仅传导舌一般感觉，不合本例"},{"q":"患者，女，42岁。被诊断患有颈椎椎管狭窄，行两个椎骨的椎板切除术。下列哪一个韧带最有可能被切除","o":["前纵韧带","齿状韧带","黄韧带","项韧带","十字交叉韧带"],"a":2,"e":"黄韧带连结相邻椎弓板、位于椎管内并协助围成椎管，颈椎椎板切除术中需切除该韧带以进入椎管减压。前纵韧带位于椎体前方；齿状韧带连于脊髓与硬脊膜之间；项韧带为项部棘上韧带的延续；十字交叉韧带位于枕寰部"},{"q":"一男性患者，因脑血管意外收治入院，检查发现左侧大脑中动脉出血。以下症状不会出现的是","o":["对侧鼻唇沟消失","口角偏向同侧","对侧额纹消失","对侧舌肌瘫痪","右侧面肌（眼裂）以下出现瘫痪"],"a":2,"e":"额肌受双侧皮质核束支配，中枢性面瘫时额纹存在，故左侧大脑中动脉出血不会出现对侧额纹消失。对侧鼻唇沟消失、口角偏向同侧（健侧）、眼裂以下面瘫及对侧舌肌瘫痪均为核上瘫的典型表现"},{"q":"患者因左下颌第三磨牙阻生，需拔除此牙，此牙的牙式是","o":["L7","L8","LⅥ","LⅦ","LⅧ"],"a":1,"e":"恒牙用阿拉伯数字1～8表示，第三磨牙为智牙，编号8；左下颌以L表示，故牙式为L8。L7代表第二磨牙；罗马数字Ⅰ～Ⅴ仅用于乳牙牙式记录，且乳牙无第6、7、8的编号，故其他选项均不符"},{"q":"患者，男，20岁。第1次乘坐飞机，飞机升空中感觉耳部发闷、疼痛，听觉下降。乘务员嘱其做咀嚼运动后好转。与鼓膜两侧气压平衡无关的结构是","o":["鼓室","咽鼓管","鼻咽","外耳道","乳突窦"],"a":4,"e":"鼓室经咽鼓管通鼻咽，咽鼓管咽口开于鼻咽侧壁，吞咽时开放使鼓室与外界气压平衡，鼓膜、鼓室、鼻咽均参与此过程。乳突窦位于鼓室后壁后方、连通乳突小房，属含气小腔通道，不参与鼓室与鼻咽的气压调节；飞机上升时做咀嚼动作正是为了让咽鼓管开放"},{"q":"患者，女，50岁。脊柱骨折，脊髓T10节段受损。患者骨折的椎骨是","o":["T7","T8","T9","T10","T11"],"a":0,"e":"成人下胸髓节段约平对同序数椎骨的上3块椎骨，故T10脊髓节段平对T7椎体，骨折椎骨为T7。T8、T9、T10椎骨位置偏低，对应的脊髓节段偏高；T11椎骨对应的节段更低，均与T10节段的体表定位不符"},{"q":"患者，女，40岁。反复发作的旋转性眩晕、波动性听力下降、耳鸣和耳闷胀感。经检查初步诊断为梅尼埃病，即膜迷路积水。迷路内的液体主要来自","o":["前庭膜","鼓膜","血管纹","壶腹嵴","螺旋膜"],"a":2,"e":"内淋巴的产生与蜗管外侧壁血管纹的分泌和滤过密切相关，血管纹功能障碍致内淋巴生成或吸收失衡、膜迷路积水，形成梅尼埃病。鼓膜为中耳结构不产生内淋巴；前庭膜为分隔膜；壶腹嵴、螺旋膜为感受器所在，均非内淋巴的主要来源"},{"q":"患者夜晚长期失眠并伴有白日过度嗜睡，被诊断为昼夜节律调节障碍。可能是什么结构受损引起的","o":["室旁核","漏斗核","背内侧核","视交叉上核","腹内侧核"],"a":3,"e":"视交叉上核位于下丘脑视上区，接受视网膜传入，经下丘脑下行通路、颈上神经节至松果体，调控褪黑素分泌以维持昼夜节律；受损后出现睡眠-觉醒节律紊乱。室旁核、漏斗核多与内分泌相关；背内侧核和腹内侧核分别参与联络与摄食调节，均非昼夜节律中枢"},{"q":"患者，女，65岁。确诊为乳腺癌。请分析在手术根治术时必须清除的淋巴结是","o":["肘淋巴结","胸骨旁淋巴结","肋间淋巴结","胸肌淋巴结","膈上淋巴结"],"a":3,"e":"乳房外侧部和中央部的淋巴管注入胸肌淋巴结，该群沿胸外侧血管排列，是乳腺癌淋巴转移的首站，根治术必须清除。肘淋巴结收纳上肢浅淋巴；胸骨旁淋巴结主要引流乳房内侧部；肋间淋巴结、膈上淋巴结非乳房淋巴的主要引流群"},{"q":"患者，男，40岁。遇车祸，出现两侧黑眼征，并有鼻出血、脑脊液鼻漏及嗅觉减退或丧失症状，诊断为颅前窝骨折。组成颅前窝的骨包括","o":["额骨眶部、筛骨筛板和蝶骨大翼","额骨眶部、筛骨筛板和蝶骨小翼","额骨眶部、筛骨筛板和蝶骨体","鼻骨、筛骨筛板和蝶骨大翼","额骨鼻部、筛骨筛板和蝶骨大翼"],"a":1,"e":"颅前窝由额骨眶部、筛骨筛板和蝶骨小翼构成，筛板筛孔通鼻腔，骨折可致脑脊液鼻漏和嗅觉丧失。蝶骨大翼和蝶骨体参与颅中窝；鼻骨、额骨鼻部不构成颅前窝底，含这些结构的选项均不成立"},{"q":"患者，女，28岁。腰骶部疼痛，后出现下肢力弱、会阴部感觉障碍、尿潴留，怀疑马尾综合征。请问有关马尾的描述正确的是","o":["腰、骶、尾神经根围绕终丝而成","骶、尾神经根围绕终丝而形成","腰、骶神经根围绕终丝而形成","骶神经根围绕终丝而形成","位于椎间孔内"],"a":0,"e":"脊髓圆锥下方，腰、骶、尾神经根在椎管内围绕终丝聚集成束形成马尾，故其组成应含腰、骶、尾三部分。马尾位于椎管内而非椎间孔内；仅含骶尾或腰骶神经根的表述均不完整"},{"q":"患者鞍区手术后高热不退，已排除感染因素，高热可能是手术中损伤了","o":["视上核","下丘脑前部","下丘脑后部","室旁核","乳头体核"],"a":1,"e":"下丘脑前区含热敏神经元，对体温升高敏感，启动排汗及表皮血管扩张等散热机制，损毁后散热障碍导致高热，鞍区手术可伤及此区。下丘脑后区损毁致变温症，体温随环境改变；视上核、室旁核合成抗利尿激素与缩宫素，损伤致尿崩；乳头体核与记忆有关，均不致术后高热"},{"q":"患者，女，35岁。需实施腰部局麻手术。麻醉药物应注入","o":["硬膜下隙","硬膜外隙","蛛网膜外隙","蛛网膜下隙","终池"],"a":1,"e":"硬脊膜与椎管内面骨膜之间的硬膜外隙含疏松结缔组织、脂肪、静脉丛和脊神经根，是腰部硬膜外麻醉的注药部位。蛛网膜下隙位于蛛网膜与软脊膜之间（含脑脊液，为腰穿部位）；终池为其下端；硬膜下隙为潜在间隙，均非局麻药注入处"},{"q":"患儿，男，3岁。生性活泼。1个月前因感冒滴注某种抗生素，后来发现对外界呼喊其名字时无反应。怀疑为神经性耳聋。进一步检查时应重点考虑检查","o":["外耳道","鼓膜","听小骨链","螺旋器","鼓室"],"a":3,"e":"螺旋器（Corti器）位于蜗管内，是听觉感受器，耳毒性抗生素易损伤螺旋器导致感音神经性耳聋。外耳道、鼓膜、听小骨链和鼓室属声音传导结构，损伤引起传导性耳聋，而非神经性耳聋的检查重点"},{"q":"患者，男，22岁。因上腹部疼痛1天，加重2小时入院。查体：腹肌高度紧张，全腹压痛明显，上腹为重，肠鸣音减弱。超声检查：仰卧位于上腹腹壁下可见宽约1cm的强回声带，可随体位移动，十二指肠蠕动减弱，左、右髂窝均可见少量不规则无回声区；胰腺因气体遮盖显示不清；肝、胆、脾、双肾未见异常。超声诊断：①上腹腹壁下强回声带；②腹腔积液，考虑为胃穿孔。X线胸片示膈下少量游离气体。治疗行胃大部分切除术时需要结扎的胃右动脉来源于哪条动脉","o":["腹腔干","肝总动脉","脾动脉","胃网膜右动脉","肠系膜上动脉"],"a":1,"e":"胃右动脉多起自肝固有动脉，可视为肝总动脉系统的分支，胃大部切除结扎该动脉时需在此追溯。腹腔干直接分支为胃左动脉、肝总动脉和脾动脉；胃右动脉并非腹腔干直接分支；胃网膜右动脉来自胃十二指肠动脉；肠系膜上动脉供应小肠"},{"q":"患者，男，40岁。车祸后，锁骨内侧端前方出现疼痛、肿胀、有压痛，首先考虑胸锁关节脱位。X线片确诊为胸锁关节脱位。胸锁关节的组成包括","o":["由锁骨的胸骨端与胸骨的锁切迹及第1肋软骨的上面构成","由锁骨的肩峰端与胸骨的锁切迹及第1肋软骨的上面构成","由锁骨的肩峰端与胸骨的颈静脉切迹及第1肋构成","由锁骨的胸骨端与胸骨角及第1肋构成","由锁骨的肩峰端与胸骨柄构成"],"a":0,"e":"胸锁关节由锁骨胸骨端与胸骨锁切迹及第1肋软骨上面共同构成，属多轴关节，关节囊坚韧。锁骨肩峰端参与肩锁关节而非胸锁关节；颈静脉切迹、胸骨角均非该关节的关节面，故含肩峰端或上述结构的选项均不成立"},{"q":"患者，男，45岁。某影像学诊断为因颅内占位性病变，致颅内压增高，导致小脑幕切迹疝。有关小脑幕切迹疝描述正确的是","o":["脑疝的定义是颅内压增高而引起小脑结构移位","仅有小脑幕后外侧缘形成小脑幕切迹","小脑幕后外侧缘形成小脑幕切迹","小脑幕前内缘游离形成小脑幕切迹","压迫了中脑的大脑脚和滑车神经"],"a":3,"e":"小脑幕后外侧缘附于枕骨横窦沟和颞骨岩部上缘，前内侧缘游离形成小脑幕切迹，切迹上方海马旁回、钩可疝入压迫中脑大脑脚和动眼神经。脑疝是脑组织整体移位，并非仅小脑结构移位；压迫的是动眼神经而非滑车神经"},{"q":"患者，女，25岁。右下腹痛2小时入院，考虑卵巢囊肿破裂，需要腹腔穿刺以鉴别诊断。下列哪个部位穿刺可能穿出积液","o":["膀胱子宫陷凹","右侧膀胱上窝","右侧腹股沟内侧窝","盲肠后窝","直肠子宫陷凹"],"a":4,"e":"直肠子宫陷凹位于直肠与子宫之间，是站立或坐位时腹膜腔的最低部位，盆腔积液易积聚于此，可经阴道后穹穿刺抽出。膀胱子宫陷凹位置较高；右侧膀胱上窝、腹股沟内侧窝及盲肠后窝均非女性腹膜腔最低点，不易穿出积液"},{"q":"患者，女，29岁。从摩托车上摔下，致颅脑损伤。入院治疗期间出现呼吸急速、咳嗽、心慌、循环衰竭而死亡。分析死亡原因，以下描述正确的是","o":["颅内压降低","中脑呼吸、心跳中枢受损","小脑扁桃体疝","海绵窦血栓","小脑幕切迹疝"],"a":2,"e":"颅内压增高时小脑扁桃体被挤入枕骨大孔形成小脑扁桃体疝，压迫延髓内的呼吸中枢和心血管运动中枢，导致呼吸循环衰竭死亡。呼吸、心跳中枢位于延髓而非中脑；颅内压应升高而非降低；海绵窦血栓、小脑幕切迹疝不直接压迫延髓生命中枢"},{"q":"某产妇剖宫产后不久出现发热，初步判断为产后腹膜腔感染积液。需做腹膜腔穿刺以明确诊断，穿刺的最佳部位是","o":["直肠前壁","腹前壁","阴道穹前部","阴道穹后部","阴道穹两侧"],"a":3,"e":"阴道穹后部最深，与直肠子宫陷凹仅隔阴道壁和一层腹膜；直立时腹膜腔积液积聚于该陷凹，经后穹穿刺可直接抽吸。阴道穹前部邻膀胱子宫陷凹且较浅；腹前壁穿刺非积液最低处；直肠前壁与阴道穹两侧均非产后腹膜腔穿刺的首选路径"},{"q":"患者，男，20岁。持续高热和腹泻8天，大便每天5～6次，偶尔有黏液，右下腹隐痛。经检查发现肝脏右肋下2cm，脾脏左肋下1cm，躯干背侧隐约可见3颗比米粒小，压之退色的淡红色皮疹。诊断为肠伤寒。伤寒杆菌易侵犯","o":["结肠","空肠","回肠","盲肠","十二指肠"],"a":2,"e":"回肠下部对肠系膜缘肠壁内有集合淋巴滤泡（Peyer斑），是肠伤寒的病变部位，可并发肠穿孔或出血。空肠、十二指肠、结肠、盲肠无此特征性的集合淋巴滤泡分布，故不是伤寒杆菌的主要侵犯部位"},{"q":"患者，男，60岁。年轻时患过乙型肝炎，近几年常伴有消化不良，食欲缺乏，消瘦无力。B超显示肝内多发结节并伴有腹水。临床上诊断为肝硬化伴有门脉高压。在进行肝门静脉血液分流手术时的连接静脉为","o":["脾静脉与左肾静脉","肝门静脉与左肾静脉","肠系膜上静脉与肠系膜下静脉","肝门静脉与上腔静脉","直肠上静脉与左结肠静脉"],"a":0,"e":"门静脉高压分流术将脾静脉与左肾静脉吻合，使门静脉系血液经脾静脉转入左肾静脉及下腔静脉系，从而降低门静脉压力。肝门静脉系内部属支间吻合如肠系膜上、下静脉间或直肠上静脉与左结肠静脉间吻合，不能起到减压作用；肝门静脉与上腔静脉间也无此常规分流术式"},{"q":"一患者，因脑部损伤入院治疗。经检查发现该患者左侧下肢不能活动，肌张力增加，但感觉正常。患者损伤的部位为","o":["中央前回上部","中央前回下部","中央前回中部","右侧中央旁小叶前部","中央旁小叶后部"],"a":3,"e":"中央旁小叶前部为大脑半球内侧面管理下肢运动的皮质区，其锥体束在延髓交叉后支配对侧下肢；右侧中央旁小叶前部受损导致左侧下肢痉挛性瘫痪且与感觉无关。中央前回上、中部主要管理上肢与躯干运动；中央旁小叶后部为下肢感觉区，受损应有感觉障碍，均不符合"},{"q":"患者，男，45岁。因“阵发性头痛，呛咳，耳鸣及走路不稳半年”入院。CT检查示“左脑桥小脑角占位性病变”。经手术治疗，术后病理诊断：舌咽神经鞘瘤。关于舌咽神经的叙述，正确的是","o":["连于脑桥","与舌下神经和副神经同穿颈静脉孔","其咽支分布于咽壁，传导咽壁的感觉","为纯感觉性神经","内脏感觉纤维起自舌咽神经上节"],"a":2,"e":"舌咽神经的咽支与迷走、交感神经咽支共同构成咽丛，分布于咽壁各层并传导咽壁感觉，参与咽反射。舌咽神经连于延髓（非脑桥）；与迷走、副神经同穿颈静脉孔；为混合性神经；一般内脏感觉纤维起自下神经节而非上神经节"},{"q":"患者，男，18岁。因车祸入院。主诉在车碰撞中，他弯曲的膝部撞至汽车仪表板上。查体显示组成膝关节的胫骨不稳定，胫骨在股骨下方可向后自由移动。最有可能损伤的结构是","o":["髌韧带","胫侧副韧带","腓侧副韧带","后交叉韧带","前交叉韧带"],"a":3,"e":"后交叉韧带起自胫骨髁间隆起后方、斜向前上附着于股骨内侧髁，屈膝时最紧张，作用是防止胫骨向后移位；屈膝位撞击仪表板使胫骨后移，提示该韧带损伤。前交叉韧带防止胫骨前移；髌韧带与侧副韧带主要限制前后以外的移位，均不能解释胫骨后移"},{"q":"患儿，男，10岁。歪头视物半年。测双眼视力正常。临床诊断为左眼上斜肌麻痹。可能出现下列何种症状","o":["左眼瞳孔偏向外上方","左眼瞳孔偏向内上方","左眼瞳孔偏向外下方","左眼瞳孔偏向内下方","左眼瞳孔偏向外侧"],"a":1,"e":"上斜肌由滑车神经支配，作用为使瞳孔转向下外方；麻痹后失去向下外的牵拉，眼球相对偏向上内，故出现左眼瞳孔偏向内上方。外直肌（展神经）麻痹致内斜视；下斜肌使瞳孔转向上外，其麻痹表现与上斜肌不同"},{"q":"患儿，男，9岁。因外伤导致左侧肘关节肿胀。X线检查肱骨内上髁附近有明显的骨折线，患者手部尺侧皮肤感觉消失，拇指不能内收，其他四指不能内收。最可能受损的神经是","o":["桡神经","尺神经","腋神经","正中神经","肌皮神经"],"a":1,"e":"尺神经在肱骨内上髁后方的尺神经沟内位置最浅，内上髁骨折易损伤；其支配小鱼际肌、骨间肌及拇收肌，受损后屈腕力减弱、小鱼际与骨间肌萎缩、拇指不能内收、各指不能靠拢，并伴尺侧皮肤感觉障碍。桡神经损伤表现为垂腕；腋神经损伤致方肩；正中神经、肌皮神经损伤均不出现上述手部内在肌瘫痪"},{"q":"患者，男，45岁。因背部和下肢严重疼痛入院。X线检查显示椎管狭窄综合征。下列哪种情况最有可能出现在MRI检查中","o":["棘上韧带增厚","棘间韧带增厚","前纵韧带增厚","后纵韧带增厚","项韧带增厚"],"a":3,"e":"椎管狭窄综合征以椎管前后径变小、脊髓或神经根受压为特征。后纵韧带位于椎体后面并构成椎管前壁，其增厚或骨化可直接突入椎管，故MRI最可能见后纵韧带增厚。前纵韧带位于椎体前方，不参与椎管构成；棘上、棘间及项韧带均位于椎管后方，增厚不造成椎管前后径狭窄"},{"q":"患儿，男，8岁。以呼吸困难，吸气时喉鸣就诊。初步诊断为急性喉阻塞，需在喉部穿刺建立临时通气道。穿刺部位应该是","o":["甲状舌骨膜","方形膜","前庭襞","环甲正中韧带","环状软骨气管韧带"],"a":3,"e":"环甲正中韧带为弹性圆锥前部增厚的部分，位置表浅，急性喉阻塞时在此穿刺可迅速建立临时通气道。甲状舌骨膜、方形膜、前庭襞均非紧急穿刺部位；环状软骨气管韧带位置偏低且不利于快速建立气道"},{"q":"患者，女，39岁。腹痛，发热入院，经诊断为急性腹膜炎。请问患者休息时应采取的体位是","o":["平卧位","半卧位","俯卧位","侧卧位","坐位"],"a":1,"e":"膈下区腹膜吸收能力强，急性腹膜炎患者取半卧位可使炎性渗出物顺重力流至下腹部，减缓毒素吸收并限制炎症扩散。平卧位、俯卧位、侧卧位均不能使渗液有效流向盆腔；坐位不利于患者休息且非标准体位"},{"q":"患者，女，70岁。摔倒后无法自主伸小腿。该患者受损的肌是","o":["半腱肌","缝匠肌","股薄肌","股二头肌","股四头肌"],"a":4,"e":"股四头肌为伸膝肌，由股神经支配，起自髂前下棘与股骨体，经髌韧带止于胫骨粗隆，收缩时伸小腿；其瘫痪致不能自主伸小腿。半腱肌、股二头肌为屈膝肌；缝匠肌、股薄肌主要屈髋屈膝并内收大腿，均不能完成伸膝动作"},{"q":"患者，男，62岁。于2周前无明显诱因出现间歇无痛性肉眼血尿。B超：膀胱内实质性占位病变。初步诊断为膀胱癌。行手术切除膀胱时需结扎的膀胱上动脉起自","o":["髂外动脉","髂内动脉","阴部内动脉","闭孔动脉","脐动脉"],"a":4,"e":"膀胱上动脉起自脐动脉未闭的近侧段，分布于膀胱上、中部，膀胱切除结扎时须据此寻找。髂外动脉主要延续为股动脉；阴部内动脉分布于会阴；闭孔动脉经闭孔出盆腔；髂内动脉为脐动脉的母体，但膀胱上动脉直接起自脐动脉，均非本题所问的直接起源"},{"q":"某患者近月来，逐渐出现左侧上、下肢及躯干意识性本体感觉和精细触觉障碍；右侧除外直肌和上斜肌外的所有眼球外肌麻痹，瞳孔散大；左侧上、下肢意向性震颤，共济失调。可能的病变部位及其受损的结构","o":["在左侧中脑上丘高度腹侧部，受损结构有锥体束、内侧丘系、动眼神经根、黑质和小脑上脚","在右侧中脑上丘高度腹侧部，受损结构有锥体束、内侧丘系、动眼神经根、黑质和小脑上脚","在左侧中脑上丘高度被盖内侧部，受损结构动眼神经根、内侧丘系、小脑丘脑纤维和红核","在右侧中脑上丘高度被盖内侧部，受损结构动眼神经根、内侧丘系、小脑丘脑纤维和红核","在右侧中脑下丘高度顶盖背侧部，受损结构滑车神经根、内侧丘系、小脑丘脑纤维和红核"],"a":3,"e":"右侧动眼神经根损伤致同侧除外直肌、上斜肌外的眼球外肌麻痹及瞳孔散大，病灶必在右侧。内侧丘系已交叉，右侧损伤表现为对侧即左侧意识性本体感觉障碍；小脑丘脑纤维与红核损伤致对侧肢体意向性震颤、共济失调，故病变在右侧中脑上丘被盖内侧部。左侧被盖腹侧部损伤为 Weber 综合征，主要累及锥体束；中脑下丘顶盖背侧损伤累及滑车神经，均与本例不符"},{"q":"患者，女，50岁。查体时叩击髌韧带，观察膝跳反射。与该反射感觉传导相关的结构是","o":["孤束","内侧纵束","薄束","楔束","脊髓丘脑束"],"a":2,"e":"膝跳反射的本体感觉传入纤维进入脊髓后索，下肢（第5胸节以下）者形成薄束并止于薄束核，其侧支参与牵张反射。楔束传导第4胸节以上（上肢）的本体感觉；孤束司内脏感觉；内侧纵束联络眼外肌核；脊髓丘脑束传导痛温觉"},{"q":"患者，男，65岁。偶发血尿1个月来诊，需要排除膀胱肿瘤。膀胱肿瘤的好发部位是","o":["膀胱尖","膀胱底","膀胱体","膀胱颈","膀胱三角"],"a":4,"e":"膀胱三角位于两输尿管口与尿道内口之间，黏膜平滑无皱襞，是膀胱肿瘤、结核和炎症的好发部位，膀胱镜检查应重点观察。膀胱尖、体、底及颈部黏膜有皱襞或属其他区域，肿瘤发生率远低于三角区，均非膀胱肿瘤的好发部位"},{"q":"患儿，男，15岁。常规查体时发现无法区分红色和绿色，诊断为红绿色盲。该病发生的解剖学基础是","o":["视锥细胞异常","视杆细胞异常","双极细胞异常","节细胞异常","色素上皮细胞异常"],"a":0,"e":"视锥细胞主要分布于视网膜中央部，感受强光和颜色刺激，含三种不同感光色素，其异常导致红绿色盲。视杆细胞司弱光视觉，异常表现为夜盲；双极细胞和节细胞为传导神经元，色素上皮细胞起支持与吞噬作用，均非色觉感受的直接结构"},{"q":"患者，女，49岁。确诊为宫颈癌。术中需要清除的淋巴结是","o":["腹股沟浅淋巴结","闭孔淋巴结","髂总淋巴结","腰淋巴结","腹股沟深淋巴结"],"a":1,"e":"子宫颈的淋巴管沿子宫血管注入髂内、外淋巴结，并经子宫主韧带注入沿闭孔血管排列的闭孔淋巴结，宫颈癌根治须清除该组。腹股沟浅、深淋巴结主要收纳下肢与会阴淋巴；髂总淋巴结、腰淋巴结位置较高，均非宫颈癌首先清除的淋巴结"},{"q":"患者，男，28岁。经临床诊断，为双眼视野颞侧半偏盲，损伤部位可能是","o":["一侧视神经","一侧视束","一侧视交叉外侧部","视交叉中部","一侧外侧膝状体"],"a":3,"e":"视交叉中部含来自两眼视网膜鼻侧半的交叉纤维，受损后双眼颞侧半视野偏盲。一侧视神经损伤致单眼全盲；一侧视束或外侧膝状体损伤致双眼对侧同向性偏盲；一侧视交叉外侧部损伤致患眼鼻侧偏盲"},{"q":"患者，女，28岁。乳腺管发生感染，形成乳房脓肿。如行手术切开引流，应尽量选取","o":["横向切口","纵向切口","梭形切口","放射状切口","环形切口"],"a":3,"e":"乳腺叶和输乳管以乳头为中心呈放射状排列，乳房脓肿切开宜作放射状切口，以免切断输乳管形成乳瘘。横向、纵向、梭形切口均与输乳管走行交叉；环形切口仅用于乳房后间隙脓肿的乳房下缘弧形引流"},{"q":"患者因颅内感染，同时伴有瞳孔散大，对光反射和调节反应消失、上睑下垂、眼球固定于外展位。诊断为海绵窦感染，该感染可能累及","o":["视神经","迷走神经","动眼神经","三叉神经","交感神经"],"a":2,"e":"动眼神经行经海绵窦外侧壁，含支配大部分眼外肌的运动纤维及副交感纤维，受损后出现上睑下垂、瞳孔散大、对光及调节反射消失、眼球固定于外展位。视神经不入海绵窦；迷走神经不经此；眼神经司感觉；交感神经损伤仅致瞳孔缩小（Horner），无眼肌麻痹"},{"q":"患者，女，50岁。缝衣服时不慎针扎小指，与传导该痛觉相关的第3级神经元所在的区域是","o":["腹外侧核","腹后外侧核","腹后内侧核","腹前核","背内侧核"],"a":1,"e":"小指痛觉经脊髓丘脑束上传，止于背侧丘脑腹后外侧核并换第三级神经元，再投射至中央后回。腹后内侧核接受三叉丘系与味觉纤维，管理头面部感觉；腹外侧核、腹前核参与运动调节；背内侧核与联络、情感有关，均非躯干四肢痛觉第三级神经元所在"},{"q":"患者，男，55岁。主诉左侧腹部包块，消化不良。腹部CT显示肿物压迫肠系膜下静脉。推测最可能引起扩张的静脉是","o":["中结肠静脉","右结肠静脉","胰十二指肠下静脉","回结肠静脉","左结肠静脉"],"a":4,"e":"左结肠静脉与乙状结肠静脉、直肠上静脉一同汇入肠系膜下静脉，该静脉受压时左结肠静脉回流受阻而扩张。中结肠静脉、右结肠静脉、回结肠静脉及胰十二指肠下静脉均汇入肠系膜上静脉系统，与肠系膜下静脉无关"},{"q":"孕妇，超过预产期2周，仍未分娩，胎盘检查3级成熟。产科医生建议行静脉滴注，加强子宫平滑肌收缩。能促进宫缩的激素是","o":["生长激素","催乳素","黑色细胞刺激素","抗利尿激素","催产素"],"a":4,"e":"催产素由下丘脑视上核、室旁核合成，经神经垂体释放，促进子宫平滑肌收缩和乳腺排乳，可用于加强宫缩引产。生长激素促生长；催乳素促进乳腺泌乳而非收缩子宫；黑色细胞刺激素作用于黑色素细胞；抗利尿激素促进水重吸收，均不直接引起宫缩"},{"q":"患者，男，50岁。早晨起床时突然出现短暂的天旋地转的感觉，站立不稳，不能行走。经检查初步诊断为耳石症。该症状是脱落的耳石刺激以下哪一结构引起的","o":["壶腹嵴","椭圆囊斑","球囊斑","螺旋器","corti器"],"a":0,"e":"耳石症为椭圆囊斑耳石脱落进入半规管，随头位变动刺激壶腹嵴这一感受旋转变速运动的位置觉感受器，引起短暂旋转性眩晕。椭圆囊斑、球囊斑为感受直线变速与静态平衡的耳石器官，是耳石来源而非被刺激结构；螺旋器即Corti器为听觉感受器，与前庭性眩晕无关"},{"q":"患者董某因右侧阴囊部肿胀不适就诊，经检查被诊断为附睾结核。下列关于附睾位置描述正确的是","o":["位于睾丸的上端和前缘","位于睾丸的下端和前缘","位于睾丸的上端和后缘","位于睾丸的下端和后缘","位于睾丸的内侧面"],"a":2,"e":"附睾紧贴睾丸上端和后缘，呈新月形，由睾丸输出小管和附睾管盘曲而成，可分头、体、尾三部。睾丸前缘与上端并非附睾附着处，下端及内侧面亦无附睾贴附；这些方位的描述均与附睾的实际毗邻不符"},{"q":"患者，男，20岁。外伤后自觉腰背痛。X线诊断为第12胸椎压缩性骨折。第12胸椎的形态结构特征是","o":["椎体横断面呈椭圆形","肋凹不典型","棘突短而分叉","上关节突关节面朝向前","横突有横突孔"],"a":1,"e":"第11、12胸椎各有一个全肋凹、横突无肋凹，肋凹不典型，是与典型胸椎的区别。椎体横断面呈椭圆形、横突孔及棘突短而分叉为颈椎特征；上关节突关节面朝向前为腰椎特征"},{"q":"患者，男，70岁。患有肺气肿。查体胸廓呈“圆桶状”，故称为“桶状胸”。“桶状胸”一般是由于肺内气体含量过多所致。正常的胸廓的形态结构特征是","o":["前后径较左右径短","前后径较左右径长","下窄上宽","成人胸廓近似圆形","分为二口二壁"],"a":0,"e":"正常成人胸廓前后径小于左右径，上窄下宽，横断面近似椭圆形；肺气肿时肺过度充气、胸廓前后径增大呈桶状。前后径大于左右径为桶状胸特征；成人胸廓并非圆形；胸廓分为上、下二口及前、后、侧壁，二口二壁的说法不符合其形态"},{"q":"患者，男，35岁。近日由于车祸入院，经检查后确诊为脑干损伤，主要为内侧丘系损伤。下面关于内侧丘系的叙述，错误的是","o":["内侧丘系的纤维来源于对侧薄束核和楔束核","内侧丘系传导对侧躯干四肢的意识性本体感觉和精细触觉","内侧丘系传导对侧躯干四肢的浅感觉和粗触觉","在延髓，内侧丘系位于锥体背侧","内侧丘系向上经脑干至间脑终止于同侧的背侧丘脑腹后外侧核"],"a":2,"e":"内侧丘系传导对侧躯干四肢的意识性本体感觉和精细触觉，浅感觉和粗触觉由脊髓丘脑束传导，故该叙述错误。内侧丘系纤维来自对侧薄束核、楔束核并在延髓位于锥体背侧，上行终于丘脑腹后外侧核，这些表述均正确"},{"q":"患者，男，19岁，足球运动员。在比赛中脚着地时，膝部的外侧被撞击，自己不能走路，被送进医院。MRI检查显示胫侧副韧带撕裂。因与韧带附着紧密，下列哪个结构最有可能伴有受伤","o":["半腱肌肌腱","内侧半月板","前交叉韧带","外侧半月板","后交叉韧带"],"a":1,"e":"胫侧副韧带与关节囊及内侧半月板外缘紧密相连，膝外侧受暴力使韧带撕裂时常一并损伤内侧半月板。外侧半月板不与胫侧副韧带相连；前、后交叉韧带位于关节内，损伤机制不同；半腱肌肌腱为屈膝肌腱，不参与此联合损伤"},{"q":"患者，男，40岁。右上腹胀痛2个月。肝下缘在右肋弓下3cm。HBsAg阳性。B超检查见肝右叶有一直径5cm的占位病变。AFP检查结果为1200ng/ml。该患者诊断为肝癌的可能性比较大。正常时关于肝的下缘位置的描述正确的是","o":["肝的下界右侧与右肋弓一致","肝的下界右侧在右肋弓下方1cm","肝的下界右侧在右肋弓下方2cm","肝的下界在剑突下不能触及","肝的下界左侧在左肋弓下2cm"],"a":0,"e":"肝下界与肝前缘一致，右侧与右肋弓一致，故正常时在右肋弓下不能触及肝；中部超出剑突下约3cm。右侧在肋弓下1～2cm仅在3岁以下幼儿可见，7岁以后触及应视为肝大；左侧被肋弓掩盖、不能在左肋弓下2cm触及，均不符合正常成人"},{"q":"患者，男，35岁。因上腹部间歇性隐痛、进食后饱胀2个月就诊。经胃镜检查并活检诊断为胃癌。关于胃的叙述，错误的是","o":["胃癌多发生于胃底","角切迹是胃小弯的最低处","大部分位于左季肋区","贲门位于第11胸椎体左侧","幽门与十二指肠相通"],"a":0,"e":"胃溃疡和胃癌多发生于幽门窦近胃小弯处，而非胃底，故该叙述错误。角切迹为胃小弯最低处；胃大部分位于左季肋区；贲门约平第11胸椎体左侧；幽门与十二指肠相接，这些表述均正确"},{"q":"患者，女，55岁。蛛网膜下腔出血，出现一侧眼睑下垂时，其动脉瘤的部位可能在","o":["大脑中动脉","前交通动脉","后交通动脉","基底动脉","眼动脉"],"a":2,"e":"后交通动脉连接颈内动脉与大脑后动脉，其动脉瘤常压迫邻近的动眼神经，导致一侧眼睑下垂、瞳孔散大，是蛛网膜下腔出血伴单侧眼睑下垂的常见原因。前交通动脉动脉瘤多位于大脑前动脉连接处；大脑中动脉、基底动脉及眼动脉病变均不典型表现为动眼神经麻痹"},{"q":"患者，女，38岁。因“经量增多2年余”而入院。体格检查：右侧甲状腺可扪及一结节性肿块。妇科检查：宫颈糜烂，宫体中位，孕2个半月大小，形态不规则，无压痛。超声检查示子宫右前壁突起中低回声79mm×77mm×75mm，左后壁肌层中低回声，直径8mm，右卵巢大小28mm×24mm×19mm，内无回声。诊断：子宫肌瘤。问手术涉及到的子宫动脉的走行及分布","o":["在子宫颈外侧约2cm处从输尿管前方跨越","分布于子宫、卵巢和外阴","在子宫颈外侧约2cm处从输尿管后方跨越","沿子宫体侧缘直线上升至子宫底","主要在子宫阔韧带内走行"],"a":0,"e":"子宫动脉行经子宫阔韧带底部，在子宫颈外侧约2cm处跨过输尿管前方并与之交叉，再沿子宫侧缘迂曲上升至子宫底，故该处为手术关键。输尿管是从子宫动脉后下方绕过而非相反；子宫动脉主要分布子宫、阴道及输卵管、卵巢，外阴由阴部内动脉供应；其走行迂曲而非直线上升"},{"q":"患者，男，31岁。呕吐咖啡色胃内物、黑便2天。经检查诊断为上消化道出血。上消化道是指","o":["胃以上的部分","食管以上的部分","十二指肠以上的部分","空肠以上的部分","回肠以上的部分"],"a":2,"e":"临床上通常把从口腔到十二指肠的消化管称为上消化道，空肠以下的部分称下消化道，故上消化道出血指屈氏韧带以上、即十二指肠及以上部位的出血。胃以上或食管以上的划分把胃和十二指肠排除在外，范围过窄；空肠、回肠及以下均属下消化道，不在上消化道范畴"},{"q":"患者，男，21岁，坠落外伤后右侧腰部及全腹部疼痛，无意识丧失，右侧腰部无明显隆起；肾区可疑叩痛，结合其他检查，诊断为外伤性肾蒂离断。肾蒂中的结构不包括","o":["肾动脉","肾静脉","输尿管","肾盂","神经"],"a":2,"e":"肾蒂为出入肾门的结构总称，包括肾动脉、肾静脉、肾盂、神经和淋巴管等；输尿管由肾盂移行而成，走行于腹膜后并不穿经肾门，不属于肾蒂。肾动、静脉与肾盂均为肾蒂主要成分，神经亦伴行其中，故只有输尿管不在其列"},{"q":"患者，男，56岁，因进行性声音嘶哑、食水呛咳10天，右肩臂抬举无力4天就诊。查体：右腭弓低垂，右软腭不能抬举，悬雍垂左偏，右咽反射消失，幕布征阳性。喉镜检查示右声带麻痹。右胸锁乳突肌和斜方肌松弛，轻度萎缩，向左转颈及右侧耸肩力弱。舌肌无萎缩。初步诊断“颈静脉孔综合征”。该患者受损的神经最可能是","o":["舌下神经、舌咽神经和副神经","舌下神经、三叉神经和副神经","舌咽神经、迷走神经和副神经","舌咽神经、三叉神经和副神经","仅有迷走神经"],"a":2,"e":"颈静脉孔内有舌咽、迷走和副神经共同穿出：舌咽神经支配咽肌与咽反射，迷走神经支配喉肌，副神经支配胸锁乳突肌和斜方肌，三者同时受损正好解释呛咳、声嘶、软腭低垂及耸肩转颈无力。舌下神经经舌下神经管出颅，且患者舌肌无萎缩，可排除；三叉神经管理咀嚼与面部感觉，不由此孔出颅"},{"q":"患者，男，68岁。感觉肚脐附近的感觉由麻木逐渐过渡至感觉消失。应当首先考虑是什么神经受损伤","o":["第2对胸神经","第4对胸神经","第6对胸神经","第8对胸神经","第10对胸神经"],"a":4,"e":"胸神经前支在躯干呈节段性分布，第10胸神经平脐，脐周感觉麻木至消失首先考虑第10对胸神经受损。第6胸神经分布于剑突平面，第8胸神经约平肋弓，第4胸神经平乳头，第2胸神经平胸骨角，均不对应脐部"},{"q":"患者，男，35岁，摔跤运动员。运动时受伤，造成右肩和近侧臂部疼痛难忍，被紧急送往急诊科。在查体期间，患者用他的另一只手抓住受伤侧肘部，无法移动受伤的肢体。影像显示右肩关节脱位。最有可能的表现是","o":["肱骨头向外侧移位","肱骨头向后下移位","肱骨头向前下移位","肱骨头向上后移位","肱骨头向内侧移位"],"a":2,"e":"肩关节囊前下方最薄弱，且缺乏韧带与肌腱加强，故肱骨头最易向前下方脱位，表现为方肩及弹性固定，患肢常内收内旋。向后下或向上后脱位均少见；向外侧或内侧移位不符合肩关节脱位的常见方向，也难以用上述体位解释"},{"q":"患者，男。排尿困难3年，诊断为慢性膀胱尿潴留。尿道外口狭窄闭塞。进行耻骨上膀胱造瘘的解剖学基础是","o":["膀胱是腹膜间位器官","正常成年人的膀胱体位于耻骨联合上方","老年人的膀胱位置在耻骨联合上方","膀胱尖的位置在耻骨联合上方","膀胱的大小和形态随尿液的充盈不断发生变化，充盈至一定程度，膀胱与腹前壁间的腹膜返折线可以上移至耻骨联合上水平"],"a":4,"e":"膀胱空虚时全部位于盆腔内，充盈时其腹膜返折线上移至耻骨联合上方，此时在耻骨联合上方穿刺可不经腹膜、避免污染腹膜腔，是耻骨上膀胱造瘘的基础。膀胱为腹膜间位器官本身并非直接依据；仅言膀胱体、膀胱尖位置升高未说明腹膜返折上移这一关键"},{"q":"患者，女，65岁。有原发性高血压、冠心病史。因胸闷、气短入院。超声检查左室侧壁后壁大面积梗死，拟进行导管术支架治疗。应该治疗以下哪个动脉","o":["对角支","前室间支","旋支","后室间支","右房支"],"a":2,"e":"旋支沿左侧冠状沟走行，主要分布于左心房、左心室侧壁及后壁的一部分，侧壁、后壁梗死应处理旋支。前室间支供应前壁和室间隔前2/3；对角支供应部分前壁；后室间支供应室间隔后1/3；右房支供应右心房"},{"q":"患者，女，25岁。需产前检查。女性骨盆是胎儿自阴道娩出时必经的骨性产道，其中骨盆内测量对角径的重要标志是","o":["耻骨联合","骶岬","髂骨翼","坐骨棘","尾骨尖"],"a":1,"e":"对角径（对角结合径）为骶岬上缘中点至耻骨联合下缘的距离，骶岬是骨盆内测量的重要标志。坐骨棘是坐骨棘间径（中骨盆横径）的标志；耻骨联合、髂骨翼、尾骨尖均非对角径的测量标志"},{"q":"患者，女，45岁。因诊断乳腺癌需要行乳腺癌根治术。术中清扫腋静脉附近的淋巴结时，应注意保护的神经是","o":["胸长神经","肌皮神经","正中神经","腋神经","胸背神经"],"a":4,"e":"胸背神经发自臂丛后束，沿肩胛骨外侧缘伴肩胛下血管、淋巴结下行分布于背阔肌，乳腺癌根治清扫腋静脉附近淋巴结时易被伤及。胸长神经沿胸侧壁支配前锯肌；肌皮神经、正中神经、腋神经均不在该清扫区域的主要走行路径上"},{"q":"患者，男，40岁。1年前因头部外伤诊断为滑车神经损伤，患者可能瘫痪的眼球外肌为","o":["上直肌","上斜肌","上睑提肌","外直肌","下斜肌"],"a":1,"e":"滑车神经起自中脑滑车神经核，唯一支配上斜肌，使瞳孔转向下外方；该神经损伤后上斜肌瘫痪，眼球不能外下视。上直肌、下斜肌、上睑提肌均由动眼神经支配；外直肌由展神经支配，这些肌肉瘫痪与滑车神经损伤无关"},{"q":"患者，男，45岁。背部被刺伤，半年后检查发现，右侧下肢痉挛性瘫痪、右侧躯干剑突平面以下和右下肢意识性本体感觉丧失，左侧躯干肋弓以下和右下肢痛温觉丧失。试分析脊髓损伤的部位是哪里","o":["T6左侧半","T6右侧半","T8左侧半","T8右侧半","T10右侧半"],"a":1,"e":"布朗-塞卡综合征表现为损伤平面以下同侧痉挛性瘫痪及深感觉丧失、对侧痛温觉丧失。本例同侧体征在右侧且上界达剑突平面，剑突平对第6胸椎，故定位于T6右侧半。T8平面约在肋弓；损伤在左侧则瘫痪与深感觉障碍应出现在左侧，均与本例不符"},{"q":"患者，女，57岁。体检时发现左侧肩胛骨内侧翘起，尤其在前推重物时明显。应当首先考虑受损的神经是","o":["胸背神经","胸外侧神经","肩胛下神经","胸长神经","胸内侧神经"],"a":3,"e":"胸长神经沿胸侧壁前锯肌表面下行并支配该肌，前锯肌拉肩胛骨向前并使其紧贴胸廓；该神经受损后前锯肌瘫痪，肩胛骨内侧缘翘起，前推重物时更为明显。胸背神经支配背阔肌，胸内、外侧神经支配胸大、小肌，肩胛下神经支配肩胛下肌，均不支配前锯肌"},{"q":"患者，男，19岁。乘坐电梯参观摩天大厦，当电梯从地面迅速上升时感觉耳部不适，升的越高不适越明显，甚至出现耳内臌胀、疼痛感。这种不适最可能是因为","o":["鼓膜内陷刺激了痛觉神经","鼓膜外凸刺激了痛觉神经","鼓膜内陷刺激了前庭蜗神经","鼓膜外凸刺激了前庭蜗神经","鼓膜受到损伤"],"a":1,"e":"电梯上升时外界气压骤降，鼓室内压相对升高，鼓膜被推向外侧而外凸，牵拉刺激鼓膜的感觉神经末梢产生胀痛。鼓膜内陷见于外界气压升高（如下潜或飞机下降）时；前庭蜗神经司听觉与平衡、不传导鼓膜痛觉；单纯气压变化一般不致鼓膜破裂损伤"},{"q":"患者，男，24岁。因街上斗殴被送往医院。影像学检查显示眶下壁骨折。最可能影响的结构是","o":["前群筛窦","后群筛窦","蝶窦","额窦","上颌窦"],"a":4,"e":"眶下壁主要由上颌骨构成，其下方即上颌窦，上颌窦眶面构成眶下壁，故眶下壁骨折最易波及上颌窦。额窦位于眶上壁上方；筛窦构成眶内侧壁；蝶窦位于眶尖之后，均不直接构成眶下壁"},{"q":"患者因交通事故入院，入院后发现患者左侧瞳孔移向内侧且外展困难，经头颅CT发现患者蝶骨骨折。骨折可能损伤了","o":["动眼神经","滑车神经","眼神经","展神经","眶下神经"],"a":3,"e":"展神经支配外直肌，使瞳孔转向外侧，展神经损伤后外直肌瘫痪，内直肌作用占优，瞳孔移向内侧且外展困难；展神经穿海绵窦、经眶上裂入眶，蝶骨骨折易伤及。动眼神经损伤致上睑下垂、瞳孔散大及眼球内斜；滑车神经支配上斜肌使瞳孔转向下外；眼神经为感觉神经，均不致外展障碍"},{"q":"患者，男，30岁。因脊髓空洞症导致双上肢内侧皮肤感觉障碍。可能受损的结构是","o":["孤束","内侧丘系","外侧丘系","三叉丘系","脊髓丘脑束"],"a":1,"e":"内侧丘系由对侧薄束核、楔束核纤维交叉后组成，传导躯干四肢意识性本体感觉和精细触觉，受损出现相应感觉障碍。孤束传导内脏感觉和味觉；外侧丘系为听觉通路；三叉丘系司头面部感觉；脊髓丘脑束传导痛温觉，均非本题感觉障碍类型"},{"q":"患儿，男，10岁。运动时跌到，肘关节呈伸直位并手部撑地，将内上髁撕脱。X线诊断为肱骨内上髁骨折。根据损伤程度分4级，其中第Ⅳ级可伴有神经损伤是因为","o":["内上髁前面的尺神经沟，有尺神经通过","内上髁后面的尺神经沟，有尺神经通过","内上髁后面的腋神经沟，有腋神经通过","内上髁后面的桡神经沟，有桡神经通过","内上髁前面的桡神经沟，有桡神经通过"],"a":1,"e":"肱骨内上髁后方有尺神经沟，尺神经由此经过，骨折显著移位时易损伤尺神经，故Ⅳ级骨折可伴神经损伤。桡神经沟位于肱骨体后面而非内上髁；腋神经绕肱骨外科颈；内上髁前面并无上述神经通过"},{"q":"患者，男，73岁。受惊吓后导致暂时性大便失禁。下列哪一神经受损伤后可能会导致大便失禁","o":["内脏大神经","内脏小神经","腰内脏神经","盆内脏神经","迷走神经"],"a":2,"e":"腰内脏神经为交感神经，经腹主动脉丛和肠系膜下丛分布至结肠左曲以下的消化管及盆腔脏器（含直肠），受损可影响直肠括约肌和肠壁功能而致大便失禁。内脏大、小神经主要支配结肠左曲以上的腹腔脏器；迷走神经分布亦至结肠左曲以上；盆内脏神经属骶段副交感"},{"q":"患者，女，30岁。妇科就诊，经直肠检查，在直肠中部前壁可扪及的结构是","o":["耻骨联合","膀胱","子宫颈","子宫体","阴道"],"a":2,"e":"子宫颈位于阴道上端、直肠子宫陷凹前方，经直肠指检在直肠中部前壁可触及，是妇科检查的常用手段。子宫体位置较高且前倾，一般不能经直肠触及；膀胱、阴道、耻骨联合均不在直肠前壁可触及范围"},{"q":"患者，男，54岁。近日感觉异常来医院就医。经检查为脑干肿瘤，肿瘤位于薄束核与楔束核之间，并已经侵犯两个核。下面关于薄束核和楔束核的叙述，错误的是","o":["传导四肢的本体感觉和精细触觉","在感觉传导通路上属于第二级神经元","发出的纤维组成内侧丘系交叉","发出的纤维经对侧内侧丘系上升","终止于背侧丘脑的腹后内侧核"],"a":4,"e":"薄束核与楔束核接受躯干四肢本体感觉和精细触觉的二级纤维，其轴突交叉组成内侧丘系交叉，经对侧内侧丘系上行，终止于背侧丘脑腹后外侧核。终止于腹后内侧核的是三叉丘系与味觉纤维；其余关于传导内容、神经元级别和交叉的描述均正确"},{"q":"患者，男，49岁。由于血尿而就诊。为明确诊断，医生为其行膀胱镜检查。下镜时医生将其阴茎向前上方提拉，关于这一操作，错误的解释是","o":["会使尿道海绵体部位置发生变化","主要影响前尿道的方位","可使耻骨前弯消失","可使耻骨下弯消失","可减轻下镜阻力，减少对尿道的损伤"],"a":3,"e":"男性尿道耻骨下弯位于耻骨联合下方，位置固定，上提阴茎不能使其消失，故该解释错误。耻骨前弯位于耻骨联合前下方，上提阴茎可使之变直消失，从而改变尿道海绵体部即前尿道的方位，减轻下镜阻力并减少损伤"},{"q":"患者，男，21岁。双下肢水肿半年余，反复全身水肿3个月，感冒后水肿加重。尿常规检查尿蛋白呈强阳性，疑有肾实质损害。构成肾实质的结构是","o":["肾皮质和肾髓质","肾皮质和肾柱","肾皮质和肾窦","肾大盏和肾小盏","肾锥体"],"a":0,"e":"肾实质在冠状切面上分为肾皮质和肾髓质：皮质位于浅层，由肾小体和肾小管组成；髓质位于深部，由15～20个肾锥体构成。肾柱为皮质嵌入髓质之间的部分，属于皮质；肾窦为容纳血管、肾盂等的腔隙；肾大、小盏属排尿管道，均不构成肾实质"},{"q":"患者，女，25岁。因头部外伤入院。查见右眼眼球下内方斜视，双眼视力正常。可能瘫痪的眼球外肌是","o":["内直肌","上睑提肌","下斜肌","下直肌","上斜肌"],"a":2,"e":"下斜肌由动眼神经支配，收缩使瞳孔转向上外方；该肌瘫痪后其拮抗肌占优，眼球偏向下内方，出现下内方斜视。内直肌、下直肌麻痹分别表现为外斜视与上内方运动障碍；上斜肌由滑车神经支配，麻痹致眼球不能外下；上睑提肌麻痹则为上睑下垂"},{"q":"患者，男，54岁。因便血就诊。经临床检查诊断为直肠癌，行直肠癌切除术，术后阴茎勃起障碍。应当考虑下列哪一神经受损伤","o":["腰内脏神经","盆内脏神经","内脏大神经","迷走神经","内脏小神经"],"a":1,"e":"盆内脏神经为骶髓S2～S4副交感纤维，经盆丛支配阴茎海绵体血管，使血管舒张、海绵体充血而完成勃起；直肠癌手术清扫盆腔内组织时易损伤该神经，导致术后勃起障碍。腰内脏神经、内脏大、小神经均为交感成分，迷走神经不支配盆腔生殖器官"},{"q":"患者，女，25岁。外伤患者，6个月后说话没有恢复，但能听懂、看懂文字，右手及右臂痉挛性瘫痪，肌张力增高，伸舌偏向右边，无舌肌萎缩，右面下部肌肉瘫痪，整个身体感觉正常。损伤何部","o":["左侧内囊膝部","左侧中央前回下半部","平面神经核平面右侧前份","左侧大脑脚腹侧","左侧中央前回中下部及额下回后部"],"a":4,"e":"患者能听懂、看懂文字但不能说话，为运动性失语，提示左侧额下回后部（Broca区）受损；右侧痉挛性瘫及面舌瘫提示左侧皮质脊髓束和皮质核束受累，故病变在左侧中央前回中下部及额下回后部。内囊膝部损伤无失语；中央前回下半部仅含运动区；大脑脚腹侧损伤还累及动眼神经"},{"q":"患者，男，21岁。因发热、盗汗伴腹胀半个月入院。查体见体形消瘦，贫血，中量腹水。现需行腹腔穿刺以明确腹水的性质，穿刺的最佳位置是","o":["脐下2cm稍外侧","脐与耻骨联合连线中点","脐与髂前上棘连线的中点","脐与髂前上棘连线的中外1/3交点的稍外方","脐水平与过腹股沟韧带中点的垂线交点"],"a":3,"e":"腹腔穿刺常取脐与髂前上棘连线的中、外1/3交点稍外侧，该处血管较少、操作安全，常选左下腹以避开阑尾。脐下2cm稍外侧、脐与耻骨联合连线中点、脐与髂前上棘连线中点均非标准穿刺点；右侧麦氏点主要是阑尾根部的体表投影"},{"q":"患者，女，18岁。拟诊白血病，需进行骨髓穿刺来检查骨髓象。穿刺部位应选择","o":["髂骨","股骨","胸骨","肋骨","椎骨"],"a":0,"e":"髂骨（髂前上棘或髂后上棘处）终身含红骨髓且位置表浅、易于定位，是临床骨髓穿刺的常用部位。胸骨、肋骨、椎骨虽有红骨髓但非首选；成人股骨骨髓腔多为黄骨髓，红骨髓主要局限于骺部"},{"q":"患者，男，20岁。右胸部外伤后就诊。检查发现右侧第4肋骨骨折，右肺呼吸音消失。患者的右肺下界可能","o":["高于左侧肺下界","低于左侧肺下界","与左侧肺下界一样","与受伤前一致","低于受伤前"],"a":0,"e":"第4肋骨骨折伴呼吸音消失提示气胸或胸腔积液使右肺受压回缩，肺下界因而上移，高于左侧。低于左侧肺下界或与受伤前一致均与肺受压萎陷不符；肺下界降低见于肺气肿，而非本例的急性胸腔病变"},{"q":"患者，女，24岁。主诉外伤后伸和外旋大腿能力减弱。损伤的肌是","o":["闭孔外肌","缝匠肌","臀大肌","阔筋膜张肌","半腱肌"],"a":2,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束与股骨臀肌粗隆，收缩时使髋关节伸和旋外；该肌损伤后伸、外旋大腿能力减弱。闭孔外肌主要使大腿旋外但作用弱；缝匠肌屈髋屈膝；阔筋膜张肌屈髋外展；半腱肌屈膝伸髋，均不主司大腿伸与外旋"},{"q":"患者，55岁。嗜酒多年，近年来记忆力不断下降，行动及对事物的反应迟缓，有时会走路不稳，会出现幻听、幻视。可能是下列哪个结构受损","o":["大脑","小脑","延髓","丘脑","脊髓"],"a":1,"e":"小脑参与运动协调，其受损导致走路不稳、动作反应迟缓及共济失调，皮质-脑桥-小脑-皮质环路受损亦使运动不能协调，故本例以小脑受损解释。幻听幻视虽可涉及大脑，但本例突出表现为走路不稳与反应迟缓，属小脑性协调障碍。延髓为生命中枢，损伤危及呼吸循环；丘脑司感觉中继，脊髓损伤以截瘫、传导束型感觉障碍为主，均非走路不稳主因"},{"q":"患者，男，40岁。因车祸出现肌肩袖撕裂。肌肩袖不包括","o":["冈上肌","肩胛下肌","大圆肌","小圆肌","冈下肌"],"a":2,"e":"肩袖（肌腱袖）由冈上肌、冈下肌、小圆肌和肩胛下肌的肌腱编入关节囊构成，大圆肌止于肱骨小结节嵴，不参与肩袖。其余四肌分别止于肱骨大结节或小结节并紧贴关节囊，是维持肩关节稳定的重要结构"},{"q":"患儿，男，15岁。近视800度加150度散光，自述近段时间经常感觉眼中有黑影飘过。受累的结构是","o":["角膜","晶状体","房水","视网膜","玻璃体"],"a":4,"e":"玻璃体为无色透明胶状物，填充于晶状体与视网膜之间，其混浊时患者自觉眼前有黑影飘动，即飞蚊症。角膜、房水、晶状体为屈光间质，混浊多表现为视力下降或视野缺损而非飘动黑影；视网膜病变常表现为视力下降、变形或脱离，均非本题典型主诉"},{"q":"患者，女，58岁。劳累后出现心悸气短，近1个月有所加重入院。入院行冠脉造影检查发现后室间支狭窄度85%，拟行支架治疗。关于后室间支正确的是","o":["沿后室间沟下行至心尖","发出房室结动脉","分布于右心房","分布于左心室侧、后壁","分布于室间隔后1/3"],"a":4,"e":"后室间支沿后室间沟下行，发出室间隔后支供应室间隔后1/3，是其主要分布区。该支多止于后室间沟下1/3而非心尖；房室结动脉多起自右冠状动脉；右心房由右冠状动脉供血；左心室侧壁、后壁主要由旋支供血"},{"q":"患者，男，65岁。突然意识丧失，入院急救。意识恢复后不能说话，右上、下肢不能运动。数日后可以说话，但舌活动不灵活。查体发现：右侧上、下肢痉挛性瘫痪，腱反射亢进，腹壁反射消失，病理反射阳性；伸舌时舌尖偏向左侧，左侧舌肌萎缩；右侧半躯干和右侧上、下肢振动觉和两点辨别性触觉消失，但面部除外；全身痛、温觉正常。可能的病变部位及其受损的结构是","o":["在左侧半延髓锥体交叉高度腹内侧部，受损结构有锥体束和内侧丘系","在左侧半延髓橄榄中部高度腹内侧部，受损结构有锥体束、内侧丘系和舌下神经根","在右侧半延髓橄榄中部高度腹内侧部，受损结构有锥体束、内侧丘系和舌下神经根","在左侧半脑桥下部高度腹侧部，受损结构有锥体束、内侧丘系和三叉神经根","在右侧半脑桥下部高度腹侧部，受损结构有锥体束、内侧丘系和三叉神经根"],"a":1,"e":"右侧偏瘫提示左侧锥体束受损；伸舌偏左伴左侧舌肌萎缩为左侧舌下神经根损伤；右侧躯干四肢振动觉、两点辨别觉障碍为左侧内侧丘系受损，故病变在左侧延髓橄榄中部腹内侧部。锥体交叉高度不累及舌下神经根；右侧延髓损伤症状应在左侧；脑桥下部累及三叉神经根"},{"q":"患者，男，34岁。左下腹间歇性绞痛，诊断为输尿管结石。其结石可能嵌顿的位置是","o":["肾实质内","肾小盏","肾大盏","肾盂","输尿管跨髂血管处"],"a":4,"e":"输尿管全长有三处生理性狭窄：肾盂输尿管移行处、跨髂血管处和壁内部，其中跨小骨盆上口髂血管处为第二狭窄，管径仅0.2～0.3cm，结石易在此嵌顿。肾实质、肾小盏、肾大盏不属于输尿管；肾盂属于第一狭窄所在部位，均非跨髂血管处"},{"q":"患者，男，40岁。患胃溃疡数年。饮酒后诱发胃后壁穿孔，胃内容物流出造成胃后壁及相临结构大片粘连。此时不易累及的器官是","o":["左肾上腺","脾","十二指肠降部","胰","横结肠"],"a":2,"e":"胃后壁隔网膜囊与胰、左肾上腺、脾及横结肠相邻，穿孔后胃内容物流出易累及上述器官。十二指肠降部位于右侧、属腹膜外位器官，与胃后壁无直接毗邻，故不易受累；胰腺、脾、左肾上腺与横结肠均在胃后壁邻近区域，属于易累及范围"},{"q":"患者，女，30岁，因大张口进食，表现为不能闭口，前牙开𬌗，下颌中线偏向健侧，后牙早接触。检查X线可见双侧髁突突出于关节结节前下方，可诊断为颞下颌关节","o":["后脱位","上方脱位","内侧脱","前脱位","外侧脱"],"a":3,"e":"颞下颌关节囊前份薄弱，大张口时下颌头随关节盘滑至关节结节下方，若张口过大且关节囊松弛，下颌头可滑至关节结节前方不能回纳，形成前脱位，影像见髁突位于关节结节前下方。后脱位、上方脱位及内、外侧脱位均非大张口机制下的常见脱位方向"},{"q":"患者，男，20岁。攀岩时落下肩部着地，造成肱骨小结节骨折。最有可能损伤的结构是","o":["冈上肌","冈下肌","肩胛下肌","小圆肌","喙肱韧带"],"a":2,"e":"肩胛下肌起自肩胛下窝，止于肱骨小结节，是肱骨小结节骨折最易损伤的结构。冈上肌、冈下肌、小圆肌均止于肱骨大结节；喙肱韧带起自喙突、止于肱骨大结节附近，均不附着于小结节"},{"q":"患者，男，65岁。因咳嗽、痰中带血就诊入院。诊断为左肺上叶肿瘤。拟通过肺的营养血管实行介入治疗。可能采用的血管是","o":["肺动脉","肺静脉","支气管动脉","支气管静脉","胸主动脉"],"a":2,"e":"支气管动脉是肺的营养血管，左侧多起自胸主动脉和主动脉弓，伴随支气管入肺并分布于支气管壁，支气管动脉介入栓塞已成为治疗肺肿瘤的方法。肺动脉、肺静脉参与气体交换的血液通路而非营养血管；支气管静脉为回流血管；胸主动脉本身不是直接进入肺内的营养血管"},{"q":"患者以眶后部疼痛与胀感、视物模糊1个月，视力明显降低2天入院，经颅脑CT检查发现眶区占位性病变。患者出现上述症状，可能是什么神经受损引起","o":["动眼神经","滑车神经","展神经","视神经","眼神经"],"a":3,"e":"眶区占位压迫视神经，导致视物模糊、视力下降及眶后胀痛，视神经传导视觉冲动由视网膜节细胞轴突构成。动眼、滑车、展神经仅支配眼球运动；眼神经为三叉神经第一支、传导眼眶及面部感觉，病变主要引起感觉障碍或眼肌麻痹而非视力下降"},{"q":"患者，女，46岁。乳腺癌。乳房皮肤增厚且表面呈“橘皮样”变，是因为病变累及","o":["皮肤","输乳管","输乳管窦","淋巴管","乳腺小叶"],"a":3,"e":"乳腺癌累及浅淋巴管时，淋巴回流受阻致皮肤淋巴水肿，毛囊汗腺处相对凹陷，呈现橘皮样改变。乳房悬韧带缩短牵拉皮肤内陷形成酒窝征，而非橘皮样变；输乳管、输乳管窦为导管结构，乳腺小叶为腺体单位，均不直接造成淋巴水肿性橘皮样外观"},{"q":"患者，女，20岁。清晨洗脸照镜时，发现口角歪向左侧，右眼不能紧闭，即来就医。查体可见：右侧额纹消失，右眼不能闭，鼓腮、吹哨时右颊部漏气，右侧口角流口水，右侧鼻唇沟消失，口角偏向左侧。其原因可能是","o":["左侧动眼神经核上瘫","右侧动眼神经核下瘫","左侧面神经核上瘫","右侧面神经核下瘫","右侧展神经核下瘫"],"a":3,"e":"右侧额纹消失、右眼不能闭合、右侧鼻唇沟消失、口角偏向左侧，说明右侧全部面肌瘫痪，属右侧面神经核下瘫，累及额肌、眼轮匝肌与口周围肌。面神经核上瘫即皮质核束或皮质病变只累及下半面肌，额纹存在、眼可闭合；动眼神经、展神经支配眼球外肌，不引起面肌瘫痪"},{"q":"患者因口裂以下皮肤感觉障碍就诊。经颅内CT检查发现其脑干有占位性病变。其感觉障碍可能是由于病变累及什么神经引起的","o":["眼神经","上颌神经","下颌神经","面神经","舌咽神经"],"a":2,"e":"下颌神经感觉纤维管理颞部、耳前及口裂以下的皮肤，口裂以下感觉障碍提示下颌神经受累，脑干占位可压迫其根部。眼神经分布于眼裂以上，上颌神经分布于眼裂与口裂之间；面神经主司面肌运动，舌咽神经主要传导舌后1/3与咽部感觉，均不管理口裂以下皮肤"},{"q":"患者，男，60岁。诊断为眶内肿瘤。其肿瘤压迫眼眶内结构，其中会引起面部感觉障碍的结构是","o":["视神经","动眼神经","眼神经","滑车神经","展神经"],"a":2,"e":"眼神经为三叉神经第一支，仅含躯体感觉纤维，经眶上裂入眶，分布于眼球、泪器、结膜及额顶、上睑、鼻背皮肤，受压即出现面部感觉障碍。视神经司视觉；动眼、滑车、展神经均为运动神经，损伤表现为眼球运动障碍或上睑下垂，无面部感觉障碍"},{"q":"患儿，男，6岁。患儿家长约6个月前无意中发现患儿左腹股沟区有1个包块，不痛，扪之质软，平卧或晨起时自行消失，哭闹、咳嗽及用力时出现，并增至乒乓球大小，但无腹痛、呕吐、发热，未作特殊处理，今来院要求住院手术治疗。临床上区分腹股沟斜疝和直疝的标志是","o":["股深动脉","腹壁下动脉","股动脉","面动脉","腹壁浅动脉"],"a":1,"e":"腹壁下动脉是腹股沟三角的外侧界，斜疝经腹股沟管突出位于该动脉外侧，直疝经三角突出位于其内侧，故为二者区分标志。股动脉、股深动脉、腹壁浅动脉及面动脉均不参与腹股沟区的这种分界关系"},{"q":"患者近1年来刷牙时时常牙龈出血，有口臭，近1个月来右下磨牙处有脓溢出，要求诊治。诊断为牙周炎。牙周炎发生在哪些结构","o":["牙冠、牙质、牙颈","牙质、牙本质、牙髓","牙槽骨、牙釉质","牙周膜、牙槽骨、牙龈","牙髓、牙周膜"],"a":3,"e":"牙周组织包括牙周膜、牙槽骨和牙龈三部分，对牙起保护、固定和支持作用，牙周炎即发生于此，表现为牙龈出血、溢脓与牙松动。牙冠、牙颈为牙体外形；牙质、牙髓位于牙体内部；牙釉质覆盖牙冠表面，均不属于牙周组织范畴"},{"q":"患者，女，38岁，已婚。因故实施输卵管结扎手术，结扎部位常选择在","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":1,"e":"输卵管峡短而直、管壁较厚，为输卵管结扎术的常用部位。壶腹部粗大弯曲，是受精和异位妊娠好发处；子宫部位于子宫壁内；漏斗部及伞部为输卵管末端，均非常规结扎部位"},{"q":"患者，男。诊断为包茎，需手术治疗。手术时，主管医生特别提醒实习医生要注意保护包皮系带。关于包皮系带的描述正确的是","o":["由阴茎海绵体背侧中线的筋膜皱襞形成","由尿道海绵体腹侧中线的筋膜皱襞形成","由阴茎头腹侧中线处的皮肤皱襞形成","由尿道球腹侧中线处的皮肤皱襞形成","阴囊的浅筋膜形成"],"a":2,"e":"包皮系带是包皮与阴茎头腹侧中线处相连的皮肤皱襞，环切时损伤可影响勃起。阴茎海绵体背侧中线、尿道海绵体腹侧中线及尿道球腹侧形成筋膜或皮肤皱襞的说法不确；该系带为皮肤皱襞而非阴囊浅筋膜所形成"},{"q":"患者，男，18岁。因颈部外伤后出现呼吸、发声功能异常就诊。初步诊断为外伤后喉狭窄。喉软骨中唯一成完整圆环支撑呼吸道的软骨是","o":["甲状软骨","环状软骨","会厌软骨","杓状软骨","喉结"],"a":1,"e":"环状软骨是喉软骨中唯一完整的软骨环，位于甲状软骨下方，支撑呼吸道保持其畅通，损伤后易致喉狭窄。甲状软骨为最大喉软骨、构成前壁与侧壁但后缘开放；会厌软骨为树叶状；杓状软骨成对；喉结为甲状软骨前角突起，均非完整圆环"},{"q":"患者，女，46岁。诊断喉癌，手术欲切除的淋巴结是","o":["下颌下淋巴结","腮腺淋巴结","颏下淋巴结","颈外侧浅淋巴结","气管旁淋巴结"],"a":4,"e":"气管旁淋巴结位于气管与食管之间的侧沟内、沿喉返神经排列，引流喉、甲状腺、气管和食管的淋巴，喉癌根治时须清除该组淋巴结。下颌下、颏下及腮腺淋巴结主要引流口腔面部；颈外侧浅淋巴结引流颈浅部，均非喉的淋巴引流首站"},{"q":"患者，女，40岁。因上颌牙折而就医，需拔牙。牙医操作时，易将断根入上颌窦内的牙齿是","o":["上颌中切牙","上颌第一前磨牙","上颌第一恒磨牙","上颌第三恒磨牙","上颌尖牙"],"a":2,"e":"上颌窦底壁与上颌第二前磨牙及第一、第二磨牙牙根仅隔一层薄骨质，牙根甚至可突入窦内，拔牙时易将上颌第一恒磨牙断根推入上颌窦。上颌中切牙、尖牙及第一前磨牙根与上颌窦底相距较远；第三恒磨牙位置靠后，均非断根入窦的常见牙"},{"q":"患者，男，26岁。因肠穿孔手术治疗后，出现肠梗阻症状，考虑可能有肠袢粘连。其发生原因主要是","o":["腹膜的分泌功能","腹膜的吸收功能","腹膜的支持功能","腹膜的防御功能","腹膜的修复功能"],"a":4,"e":"腹膜分泌的浆液含纤维蛋白，有较强修复和再生能力，手术操作粗暴或腹膜暴露过久时，纤维蛋白机化可造成肠袢纤维性粘连，导致肠梗阻。腹膜的分泌、吸收、支持、防御功能虽重要，但均非术后粘连形成的主要机制"},{"q":"患者，女，35岁。近期出现乏力。入院检查发现有房间隔缺损。房间隔缺损最易发生于哪个部位","o":["卵圆窝","Todaro腱","Koch三角","隔缘肉柱","主动脉隆凸"],"a":0,"e":"卵圆窝为胚胎卵圆孔闭合遗迹，是房间隔最薄弱处，为房间隔缺损最好发部位，也是右房至左房穿刺的常用处。Todaro腱与Koch三角为房室结区域的标志；隔缘肉柱位于右心室，内含右束支；主动脉隆凸是心导管术的标志而非缺损好发处"},{"q":"患者，男，40岁。诊断为梗阻性黄疸。需要进行肝内胆管造影，应经哪个部位进行肝穿刺","o":["右肝下间隙","右肝下前间隙","右肝上前间隙","膈下腹膜外间隙","左肝上前间隙"],"a":3,"e":"膈下腹膜外间隙位于肝冠状韧带裸区与膈之间、主要在右肝后方，为腹膜外结构，是肝穿刺行肝内胆管造影的进针部位。右肝上、下间隙及左肝上前间隙均属腹膜腔间隙，穿刺可经腹膜腔，有污染或出血风险，均非本题所选进针途径"},{"q":"患者，女，18岁。大学入学查体，耳科检查鼓膜时发现鼓膜外侧面正常朝向应该是","o":["向前下外倾斜","向后下外倾斜","向前上外倾斜","向后上外倾斜","向前内下倾斜"],"a":0,"e":"成人鼓膜向外、向前、向下倾斜，与外耳道底成一定角度，检查时需向后上方牵拉耳郭以对齐外耳道。婴幼儿鼓膜近水平位；向后下外、前上外、后上外、前内下等朝向均不符合成人鼓膜的正常倾斜方向"},{"q":"患者因头痛、恶心呕吐、视力障碍入院，经诊断为脑积水并伴有视神经盘水肿。颅内高压引起视神经盘水肿的原因是","o":["硬脑膜下隙延伸至视神经周围","脊髓蛛网膜下隙延伸至视神经周围","脑蛛网膜下隙延伸至视神经周围","脊髓硬膜外隙延伸至视神经周围","脊髓硬膜下隙延伸至视神经周围"],"a":2,"e":"眼在胚胎发生中由脑向前突出，脑的三层被膜延续包裹视神经，脑蛛网膜下隙随之延伸至视神经周围。颅内压升高时压力经此隙传至视神经，导致视神经盘水肿。硬脑膜下隙与硬膜外隙不含脑脊液，不能传导颅内压；脊髓蛛网膜下隙位于椎管下部，与视神经周围不相延续"},{"q":"患者，女，34岁。车祸后被送往急诊科。影像学检查显示颈椎挥鞭样损伤（反方向猛扭）导致颈椎过伸。此情况下，哪个韧带最有可能受伤","o":["棘上韧带","黄韧带","后纵韧带","前纵韧带","横突间韧带"],"a":3,"e":"前纵韧带位于椎体前面，上自枕骨大孔前缘、下达第1或第2骶椎，限制脊柱过度后伸；颈椎过伸挥鞭样损伤时该韧带受牵拉而撕裂。后纵韧带在椎体后面限制前屈；黄韧带、棘上韧带和横突间韧带主要限制脊柱前屈或侧屈，均非过伸时首要受伤结构"},{"q":"患者，女，68岁。因右眼突然剧烈疼痛、眼红畏光、视物不清，伴有恶心感。诊断为继发性闭角型青光眼。其病因为","o":["房水回流受阻","房水产生过少","房水产生过多","泪液分泌过多","视网膜中央动脉阻塞"],"a":0,"e":"房水回流受阻（如闭角型青光眼前房角狭窄、小梁网阻塞）使眼压升高，导致青光眼，出现眼痛、畏光、视力下降。房水生成过少或过多非闭角型青光眼的主要机制；泪液分泌过多致溢泪；视网膜中央动脉阻塞致视网膜缺血而非眼压升高"},{"q":"患者因脑出血入院，经诊断为腹后内侧核出血。该患者可能出现哪种症状","o":["同侧半躯干四肢深感觉丧失","对侧半躯干四肢深感觉丧失","对侧头面部浅感觉丧失","对侧头面部深感觉丧失","同侧头面部深感觉丧失"],"a":2,"e":"腹后内侧核接受三叉丘系传导的头面部痛温觉和触压觉，其损伤导致对侧头面部浅感觉丧失。躯干四肢深感觉由腹后外侧核中继，故半躯干四肢深感觉障碍与该核无关；头面部深感觉并非腹后内侧核的主要传导内容，同侧体征亦不符合感觉交叉规律"},{"q":"患者因颅内出血入院，经检查发现患者除颅内高压的症状外还伴有左侧瞳孔不能移向下外。该症状可能是什么神经受损引起的","o":["左动眼神经","左滑车神经","左展神经","右动眼神经","右滑车神经"],"a":1,"e":"上斜肌由滑车神经支配，作用为使瞳孔转向下外方，该神经受损则瞳孔不能移向下外。动眼神经损伤致上睑下垂、瞳孔散大并斜向外下方；展神经损伤致眼球内斜视（不能外展），均与单纯的向下外运动障碍不符"},{"q":"患者，男，35岁。突然发生剧烈头痛、恶心、呕吐和脑膜刺激征，怀疑蛛网膜下腔出血。需要抽取脑脊液进行诊断，腰椎穿刺抽取脑脊液应在","o":["骶管裂孔处","第5腰椎与第1骶椎棘突间隙","第3腰椎与第4腰椎棘突间隙","第1腰椎与第2腰椎棘突间隙","第12胸椎与第1腰椎棘突间隙"],"a":2,"e":"成人第1腰椎以下已无脊髓，第3、4腰椎棘突间穿刺不会损伤脊髓，是腰穿抽取脑脊液的常用部位。第1、2腰椎间或第12胸椎与第1腰椎间仍可能伤及脊髓圆锥；骶管裂孔用于骶管麻醉；第5腰椎与第1骶椎间非首选"},{"q":"患儿，女，5岁。因挖鼻出现一侧鼻出血。最有可能出血的部位是","o":["鼻腔外侧壁上鼻甲处","鼻腔外侧壁中鼻甲处","鼻腔外侧壁下鼻甲处","鼻腔顶","鼻腔内侧壁前下部"],"a":4,"e":"鼻中隔前下部血管丰富、位置浅表，是鼻出血的最好发部位，约90%的鼻出血源于此，称易出血区；挖鼻易损伤该处。鼻腔外侧壁上、中、下鼻甲处及鼻腔顶均非主要出血区，外侧壁出血远较鼻中隔前下部少见"},{"q":"患者，男，50岁。右手环指被玻璃切割伤，手术中发现屈指浅、深肌腱均断裂。患者的主要表现是","o":["近侧指间关节不能屈曲","远侧指间关节不能屈曲","掌指间关节不能屈曲","两个指间关节不能屈曲","两个指间关节不能屈曲和掌指关节均不能屈曲"],"a":3,"e":"指浅屈肌止于中节指骨、屈近侧指间关节，指深屈肌止于远节指骨、屈远侧指间关节，两者同时断裂则两个指间关节均不能屈曲。掌指关节的屈曲主要依赖骨间肌和蚓状肌，指浅、深屈肌腱断裂并不使其完全丧失屈曲，故掌指关节不能屈曲的说法不成立"},{"q":"患者，女，30岁。因咽喉部异物感就诊。医生建议做喉镜检查。正常情况下，喉镜检查时如何确定声门裂的位置","o":["位于两侧前庭襞之间","位于两侧声襞之间","位于杓状软骨之间","位于两侧喉室之间","位于方形膜和弹性圆锥之间"],"a":1,"e":"声门裂位于两侧声襞与杓状软骨底、声带突之间，较前庭裂长而窄，是喉腔最狭窄处，喉镜下易于辨认。两侧前庭襞之间为前庭裂，较宽；杓状软骨之间不构成声门裂；喉室是声襞与前庭襞间的隐窝；方形膜、弹性圆锥为喉的膜性支架，均非声门裂位置"},{"q":"患者，男，45岁。左下腹隐痛4个月，近2个月来乏力、消瘦，常有低热。查体：结膜苍白，左下腹部5cm×3cm肿块。化验：血红蛋白95g/L。检查诊断为结肠癌。结肠癌最容易发生的部位在","o":["升结肠","降结肠","横结肠","结肠右曲","乙状结肠"],"a":4,"e":"乙状结肠是结肠癌及憩室的好发部位，其肠腔为结肠最狭窄处，系膜活动度大。升结肠、降结肠、横结肠及结肠右曲虽可发生肿瘤，但并非结肠癌最易发生部位；本例左下腹肿块、乏力消瘦及排便改变也符合乙状结肠病变"},{"q":"患儿，男，3岁。因发热入院。既往患儿多次发生肺炎，发病同时伴随心悸、气短等。心脏彩超检查发现患儿室间隔膜部发生缺损。关于室间隔膜部正确的说法是","o":["室间隔缺损多发生于室间部","分隔右心室流出道与左心室流入道","后上部分隔右心室与左心房","占室间隔的1/2","借二尖瓣前瓣分为两部"],"a":0,"e":"室间隔膜部由右纤维三角向前延伸而成，可分为房室部与室间部，室间隔缺损多发生在室间部。膜部后上方的房室部实为分隔右心房与左心室，并非右心室与左心房；该部仅占室间隔一小部分；其两部以三尖瓣隔侧瓣附着为界，与二尖瓣前瓣无关"},{"q":"一个年轻的女患者足内侧缘皮肤被大头针刺伤肿胀，请问肿大的淋巴结是","o":["腹股沟浅淋巴结上群","腘淋巴结","腹股沟深淋巴结","腹股沟浅淋巴结下群","髂外淋巴结"],"a":3,"e":"足内侧缘的浅淋巴随大隐静脉回流，注入腹股沟浅淋巴结下群，故该组淋巴结肿大。腘淋巴结收纳足外侧缘和小腿后外侧的浅淋巴；腹股沟浅淋巴结上群引流腹壁、臀部、会阴；髂外淋巴结和腹股沟深淋巴结收纳更深部的淋巴"},{"q":"肛门、会阴部手术时，患者取左侧卧位，弯腰低头曲背，两手抱膝。医生采用骶管麻醉技术，将麻醉药物注入骶管。骶管麻醉的体表标志是","o":["骶岬","骶粗隆","骶角","尾骨尖","骶后孔"],"a":2,"e":"骶管裂孔两侧向下突出的骶角为骶管麻醉的体表标志，沿骶中嵴向下可扪及裂孔及其两侧的骶角。骶岬为骶骨上缘前突，是骨盆入口标志；骶后孔为骶神经后支通过处；尾骨尖位于骶骨下端，均不作骶管麻醉定位"},{"q":"小李由于不育而就诊，医生检查后发现其为先天性输精管缺失患者。下列关于输精管的描述错误的是","o":["起于附睾尾","末端变细与精囊排泄管汇合形成射精管","睾丸部位于睾丸前缘","精索部为男性节育手术理想位置","腹股沟部位于腹股沟管内"],"a":2,"e":"输精管睾丸部起自附睾尾，沿睾丸后缘及附睾内侧上行至睾丸上端，位于前缘的说法错误。输精管末端与精囊排泄管汇合成射精管；精索部位置表浅，是输精管结扎的理想部位；腹股沟部全程位于腹股沟管内，三项描述均正确"},{"q":"患者，男，20岁。在跑步和爬山时，不能屈和内旋小腿。最有可能受损的肌是","o":["股二头肌","缝匠肌","股直肌","股中间肌","阔筋膜张肌"],"a":1,"e":"缝匠肌起自髂前上棘、止于胫骨上端内侧面，作用为屈髋、屈膝，并在屈膝时使小腿旋内，故不能屈和内旋小腿提示该肌受损。股二头肌屈膝并使小腿旋外；股直肌、股中间肌为伸膝肌；阔筋膜张肌主司外展、屈髋"},{"q":"患者，男，31岁。手掌因大钉子的穿透伤导致腱鞘炎。检查发现腱鞘尺骨囊感染。这种感染最有可能导致坏死的肌腱是","o":["尺侧腕屈肌的肌腱","拇长屈肌腱","指深屈肌腱","桡侧腕屈肌腱","掌长肌腱"],"a":2,"e":"手掌屈肌总腱鞘（尺侧囊）包绕指浅、指深屈肌腱，感染易沿腱鞘蔓延致指深屈肌腱坏死。尺侧腕屈肌腱、桡侧腕屈肌腱及掌长肌腱均有独立腱鞘或位于前臂，不受尺侧囊累及；拇长屈肌腱由桡侧囊单独包绕"},{"q":"患者，男，40岁。突发右上腹阵发性绞痛，伴恶心、呕吐。右上腹出现压痛和肌紧张，墨菲征阳性，诊断为急性胆囊炎。请问在体格检查时于何处可经腹前壁触及胆囊底","o":["右腹直肌内侧缘与右肋弓交点处","左腹直肌外侧缘与左肋弓交点处","右锁骨中线与右肋弓交点处","脐与髂前上棘连线的中、外1/3交点处","剑突下靠右侧1～2cm"],"a":2,"e":"胆囊底体表投影在右腹直肌外侧缘或右锁骨中线与右肋弓交点处，发炎时该处压痛明显。右腹直肌内侧缘定位错误；脐与髂前上棘中外1/3交点为阑尾根部（麦氏点）；剑突下1～2cm为肝或胃的投影区"},{"q":"患者，男，69岁。因舌右侧颜色异常及运动不便就诊。检查发现患者伸舌无力且舌尖偏向右侧。患者3年前曾因右扁桃体恶性肿瘤行根治性颈清扫术。患者最可能损伤了","o":["三叉神经","面神经","舌咽神经","舌神经","舌下神经"],"a":4,"e":"舌下神经支配舌内肌和大部分舌外肌，损伤后同侧舌肌瘫痪萎缩，伸舌时舌尖偏向患侧；本例伸舌无力且舌尖偏右，提示右侧舌下神经受损，颈清扫术易伤及。三叉神经主司咀嚼与面部感觉；面神经支配表情肌；舌咽神经支配咽肌与舌后1／3感觉；舌神经为下颌神经分支、司舌前2／3一般感觉，均不引起伸舌偏斜"},{"q":"患儿，2岁。因先天性斜颈入院需手术矫正。在颈部手术暴露胸锁乳突肌时，注意勿伤到的静脉是","o":["颈内静脉","颈外静脉","锁骨下静脉","面静脉","颈前静脉"],"a":1,"e":"颈外静脉由下颌后静脉后支等汇合而成，沿胸锁乳突肌表面下行，暴露该肌时位置最浅、最易损伤。颈内静脉位于该肌深面的颈动脉鞘内；锁骨下静脉在锁骨上方；面静脉、颈前静脉走行于颈部浅层其他位置，不沿此肌表面"},{"q":"患者，男，68岁。因进行性吞咽困难就诊。经食管镜检查，发现距中切牙约25cm处有一肿块，进行活检，诊断为食管癌。请问该患者的肿块位于食管哪个部位","o":["食管颈部","食管第1个狭窄","食管第2个狭窄","食管第3个狭窄","食管腹部"],"a":2,"e":"食管第2狭窄位于左主支气管后方交叉处，平第4、5胸椎之间，距中切牙约25cm，是食管癌好发部位之一，本例肿块位置与此吻合。第1狭窄距中切牙约15cm；第3狭窄平第10胸椎、距中切牙约40cm；颈部与腹部不属于以25cm为标志的狭窄区"},{"q":"患者，女，45岁。因咳嗽半个月余，突发剧烈胸痛伴呼吸困难4小时前来就诊。患者半个月前因受凉感冒后出现咳嗽伴少许白色黏痰，自服感冒、镇咳药无明显好转。曾就诊于社区医院，行X线胸片检查未发现明显异常，左肺纹理增粗。给予抗感染治疗，咳嗽较前稍有减轻，4小时前无明显诱因突觉胸痛，呼吸费力，遂卧床休息片刻不见好转，且有加重趋势，由家人急送来医院。夜间急诊行胸部X线检查仍发现左肺纹理增粗。余未见异常。无异物史。一般情况可，遂留院观察。给予吸氧，病情无明显好转，2小时前胸痛及呼吸困难程度进行性加剧，再次行胸部X线检查发现左侧全肺不张，余未见异常，遂收入院。次日，肺CT检查结果示左肺不张，余无异常。行纤维支气管镜检查于主支气管隆突偏左处发现一新生物，占满整个左主支气管腔，至此诊断明确，左中心型肺癌。同时取活检数块，送病理，结果证实为小细胞未分化癌。问：手术治疗过程中需涉及到的胸主动脉，下列关于其说法错误的是","o":["平胸骨角高度续于主动脉弓","穿主动脉裂孔续为腹主动脉","下端位于下腔静脉的左侧","胸主动脉的脏支较为粗大","胸主动脉属后纵隔器官"],"a":3,"e":"胸主动脉位于后纵隔，在第4胸椎左侧续主动脉弓、第12胸椎高度穿主动脉裂孔移行腹主动脉，下端居下腔静脉左侧，其壁支较粗大而脏支细小。称脏支粗大的说法错误；平胸骨角高度续于主动脉弓、穿裂孔续腹主动脉及属后纵隔器官的描述均正确"},{"q":"患者，女。停经3个月以上，基础体温单相。妇科检查子宫偏小，阴道脱落细胞涂片、宫颈黏液检查显示体内雌激素作用水平偏低，子宫内膜呈增生反应。血卵泡刺激素（FSH）、黄体生成素（LH）水平偏低或LH/FSH比值＜3，血催乳素（PRL）正常水平。可能是什么结构病变引起的","o":["下丘脑-垂体-肾上腺轴系","下丘脑-垂体-甲状腺轴系","下丘脑-垂体-性腺轴系","下丘脑脊髓束","背侧纵束"],"a":2,"e":"闭经、雌激素低落伴FSH、LH水平偏低，提示病变在下丘脑-垂体-性腺轴系，属低促性腺激素性性腺功能减退。下丘脑-垂体-甲状腺轴系异常表现为TSH、T3、T4改变；肾上腺轴异常影响ACTH与皮质醇；下丘脑脊髓束、背侧纵束非内分泌调节轴"},{"q":"患儿，男，16岁。右上磨牙疼痛2周后，出现头痛、鼻腔分泌物增多、鼻塞等表现。最有可能累及的结构是","o":["额窦","上颌窦","筛窦前群","筛窦中群","筛窦后群"],"a":1,"e":"上颌窦底壁与上颌第二前磨牙及第一、二磨牙牙根相邻，仅隔一层薄骨甚至牙根突入窦内，故上磨牙病变易累及上颌窦，引发头痛、鼻塞及脓性分泌物，且窦口高于窦底致引流不畅。额窦、筛窦前中后群与磨牙无此邻接关系，不易因牙病蔓延"},{"q":"患者，男，28岁。因视觉异常入院。瞳孔对光反射检查，无论光照哪一侧瞳孔，患侧的瞳孔直接及间接对光反射都消失，但健侧的瞳孔对光反射都存在。损伤了","o":["健侧的动眼神经","健侧的视神经","视交叉","患侧的动眼神经","患侧的视神经"],"a":3,"e":"患侧动眼神经受损时传出通路中断，无论光照哪一侧眼，患侧瞳孔直接及间接对光反射均消失，而健侧传出完整、反射存在。患侧视神经损伤表现为光照患眼时双眼均无反应、光照健眼时双眼均有反应；视交叉损伤多为双颞侧偏盲伴相应反射改变，均与本例不符"},{"q":"患者，男，72岁。翼点处受外力而骨折，诊断为“硬膜下血肿”。损伤的血管是","o":["颞板障静脉","脑膜中动脉前支","脑膜中动脉后支","大脑中动脉","颞深动脉"],"a":1,"e":"翼点为额、顶、颞、蝶四骨会合处，骨板薄弱且其内面有脑膜中动脉前支经过的骨沟，此处骨折易撕裂该动脉，血液积聚于硬膜与颅骨之间形成硬膜外血肿。脑膜中动脉后支行于翼点后方；大脑中动脉位于颅内；颞板障静脉和颞深动脉出血量与翼点骨折的典型表现不符"},{"q":"患者，男，20岁。鼻部外伤后出现嗅觉功能异常。有可能受损的部位是","o":["上鼻甲","中鼻甲","下鼻甲","鼻中隔下部","鼻前庭"],"a":0,"e":"嗅区位于上鼻甲及其相对的鼻中隔上部和鼻腔顶部，富含嗅细胞，鼻外伤累及上鼻甲区可损伤嗅细胞致嗅觉异常。中鼻甲、下鼻甲及鼻中隔下部、鼻前庭均属呼吸区，黏膜含鼻腺而无嗅细胞，受损一般不引起嗅觉障碍"},{"q":"患者因面部针刺样疼痛就诊，经检查发现其疼痛部位位于眼裂以上，每次疼痛持续数秒，且可由眨眼激发。诊断为三叉神经痛。请问具体是三叉神经哪一支分支引起的","o":["眼神经","上颌神经","下颌神经","面神经","舌咽神经"],"a":0,"e":"三叉神经眼神经分布于眼裂以上的额部及上睑皮肤，该区发作性剧痛、眨眼激发符合眼神经痛。上颌神经支配眼裂与口裂之间区域，下颌神经支配口裂以下，二者疼痛部位均不在眼裂以上；面神经主司面肌运动，舌咽神经主理舌后及咽部感觉，均非三叉神经分支"},{"q":"患者，男，66岁。因滑倒导致左侧肩部疼痛，肿胀，左肩主动活动功能受限。X线检查显示左侧肱骨外科颈附近有明显的骨折线，最容易受损伤的神经是","o":["腋神经","肌皮神经","正中神经","尺神经","桡神经"],"a":0,"e":"腋神经与旋肱后动脉伴行穿四边孔后绕肱骨外科颈至三角肌深面，肱骨外科颈骨折最易损伤该神经，致三角肌瘫痪、臂不能外展及肩部感觉障碍，日久呈方肩。肌皮神经穿喙肱肌；正中神经、尺神经与桡神经走行均不紧贴外科颈，故非该处骨折最易受损者"},{"q":"患者，男，62岁。腹泻，便血。经结肠镜检查诊断为大肠息肉和憩室。大肠息肉和憩室好发于","o":["升结肠","横结肠","降结肠","乙状结肠","盲肠"],"a":3,"e":"乙状结肠肠腔最窄、系膜活动度大，是结肠憩室和肿瘤的好发部位。升结肠、横结肠、降结肠及盲肠的管径和固定程度不同，憩室发生率明显低于乙状结肠，故均非题中所述的好发部位"},{"q":"患者，男，65岁。因跌倒并手、肘着地后，右肩出现局部肿胀、疼痛、压痛，肩关节活动功能障碍，上臂上段瘀斑。X线可见肱骨解剖颈下2～3cm处的骨折。提示是","o":["肱骨大结节骨折","肱骨小结节骨折","肱骨解剖颈骨折","肱骨外科颈骨折","肱骨头骨折"],"a":3,"e":"肱骨上端与体交界处稍细，称肱骨外科颈，位于解剖颈下2～3cm，是骨折好发部位。解剖颈更靠近肱骨头；大、小结节为肌腱附着的骨性突起；肱骨头为近端球形部分，均非该骨折部位"},{"q":"患者，男，23岁。跌倒时上肢外展外旋，手掌或肘部着地，外力沿肱骨纵轴冲击，肩关节囊的下壁相对最为薄弱，肱骨头自肩胛下肌和大圆肌之间薄弱部撕脱关节囊，向前下脱出，最易形成肩关节","o":["喙突下脱位","后脱位","锁骨下脱位","肩胛冈下脱位","肩峰下脱位"],"a":0,"e":"肩关节囊下壁最薄弱，肱骨头常从下份滑出形成前下方脱位，以喙突下脱位最常见。肩峰下脱位、锁骨下脱位属前脱位的其他类型但较少见；后脱位少见；肩胛冈下脱位并非标准分型"},{"q":"患儿，女，15岁。左侧手掌因为刀伤后导致拇指不能内收。可能损伤的神经是","o":["桡神经","尺神经","正中神经","肌皮神经","腋神经"],"a":1,"e":"拇收肌由尺神经支配，掌深支损伤后拇指不能内收。正中神经支配拇短展肌、拇对掌肌，主司外展和对掌；桡神经支配伸腕伸指肌，肌皮神经支配屈肘肌群，腋神经支配三角肌，均不支配拇收肌"},{"q":"患者，女，56岁。无明显诱因出现左侧瞳孔变大，且左眼视力下降，尤其看近物模糊。检查左侧瞳孔对光反射障碍。首先考虑下列哪种结构受损","o":["三叉神经的分支眼神经","动眼神经核","滑车神经","动眼神经的交感纤维","动眼神经的副交感纤维"],"a":4,"e":"动眼神经副交感纤维经睫状神经节换元后支配瞳孔括约肌和睫状肌，参与对光反射与调节；受损后瞳孔散大、对光反射障碍、睫状肌麻痹致看近物模糊。交感纤维支配瞳孔开大肌，损伤表现为瞳孔缩小；动眼神经核损伤尚伴眼外肌麻痹；滑车神经只支配上斜肌；眼神经为感觉神经，均不符"},{"q":"患者，男，57岁。摔倒时肘关节处于伸直位，手掌着地。检体发现肘部肿胀和有压痛。X线诊断为尺骨鹰嘴骨折。鹰嘴的形态特征是","o":["肱骨滑车后上方的突起","尺骨滑车切迹后上方的突起","桡骨滑车切迹后上方的突起","尺骨滑车切迹前下方的突起","肱骨滑车前下方的突起"],"a":1,"e":"鹰嘴为尺骨滑车切迹后上方的突起，与肱骨滑车构成肱尺关节，是肘后部骨性标志。滑车切迹前下方的突起为冠突；鹰嘴属尺骨而非肱骨或桡骨；肱骨滑车后上方的凹陷为鹰嘴窝，容纳鹰嘴而非突起"},{"q":"患者，男，65岁。患者自诉于13小时前无明显诱因出现腹部疼痛，呈阵发性胀痛，无放射性及刀割样疼痛，伴恶心、呕吐3次，为非喷射性呕吐，呕吐物为胃内容物及胃液，每次量约50ml，无咖啡样物，无畏寒、发热，无腹泻，无尿痛、解肉眼血尿。发病后在家口服草药治疗，具体不详，但患者腹痛、腹胀无缓解，于今为求进一步治疗而来我院就诊，门诊医师行腹部正位片检查后，拟肠梗阻收入我科。发病以来患者精神一般，食欲、睡眠欠佳，小便正常，解1次黄色成形便，量约20g，无黏液脓血便。行手术腹腔探查术，术中发现部分小肠坏死，需切除。需结扎的空、回肠动脉来源于","o":["肠系膜下动脉","腹腔干","脾动脉","肠系膜上动脉","胃网膜左动脉"],"a":3,"e":"空、回肠动脉起自肠系膜上动脉，该动脉还发出胰十二指肠下动脉、回结肠动脉、右结肠动脉和中结肠动脉。肠系膜下动脉分布结肠左曲以下；腹腔干及其脾动脉分支、胃网膜左动脉均供应胃、脾等上腹部器官，不营养空回肠"},{"q":"患者，男，40岁。中上腹饥饿性隐痛反复发作10年，伴反酸，嗳气，进食和服用抑酸剂可缓解。该患者最可能的疾病是消化性溃疡，好发部位是胃的","o":["贲门部","贲门切迹","幽门部","胃底","胃体"],"a":2,"e":"胃溃疡和胃癌多发生于幽门窦近胃小弯处，幽门部（胃窦）是消化性溃疡的好发部位。贲门部、胃底、胃体均非典型好发区；贲门切迹为贲门与食管交界处的角状凹陷，与溃疡好发无关"},{"q":"患者，男，68岁。因咳嗽，痰中带血就诊。有25年吸烟史。经检查后初步诊断为肺癌，伴有胸腔积液。胸腔积液最先积聚的部位是","o":["肺门","斜裂","肺下缘","肋膈隐窝","肋纵隔隐窝"],"a":3,"e":"肋膈隐窝由肋胸膜与膈胸膜返折形成，是胸膜隐窝中位置最低、容量最大者，深吸气时肺缘也不能达其内，胸腔积液因此首先积存于此。肋纵隔隐窝位于心包两侧、位置较高；肺门与肺下缘无胸膜隐窝结构"},{"q":"患者，男，55岁。自己无意间发现颈前部单个肿块，表面光滑，边界清楚，无压痛，可随吞咽上下移动。入院经B超等检查，诊断为“甲状腺腺瘤”。行甲状腺次全切除术，术后出现声嘶及发声无力。该患者出现上述症状最可能的原因是","o":["术中损伤声韧带","术中损伤喉上神经外支","术中损伤喉上神经内支","术中损伤单侧喉返神经","术中损伤单侧舌咽神经"],"a":3,"e":"喉返神经在甲状腺下极附近与甲状腺下动脉关系密切，手术结扎该动脉时易损伤单侧喉返神经，导致声带麻痹、声音嘶哑。喉上神经外支损伤致音调降低（环甲肌瘫）；内支损伤致饮水呛咳；舌咽神经不支配声带"},{"q":"患儿，女，12岁。因受凉，自诉咳嗽，咽疼，耳部发闷。对耳部不适这一现象的解释不正确的是","o":["鼓膜两侧空气压力失去平衡","鼓室暂时成密闭的室腔，与外界不交通","咽鼓管炎症、水肿，导致咽鼓管闭塞","外耳道堵塞","咽鼓管咽口平时处于关闭状态"],"a":3,"e":"上呼吸道感染时咽鼓管咽口周围黏膜炎症、水肿可使咽鼓管闭塞，鼓室暂成密闭腔，鼓膜两侧气压失衡，产生耳闷，故外耳道堵塞不是该现象的解释。咽口平时关闭、咽鼓管炎症水肿及气压失衡均为正确机制"},{"q":"患者，男，35岁。慢性中耳炎患者。最近出现阵发性或激发性眩晕，偶伴恶心、呕吐等症状，多在身体姿势改变时发作。该患者病变最可能累及了","o":["颅内","迷路","颈内静脉","鼓膜","乳突窦"],"a":1,"e":"迷路（内耳）含前庭和半规管等位觉感受器，慢性中耳炎炎症侵犯迷路时可出现体位改变相关的阵发性眩晕和眼震。颅内病变、颈内静脉、鼓膜、乳突窦疾病均不直接刺激位觉感受器，非此类眩晕的责任结构"},{"q":"患者，女，47岁。手术中损伤椎动脉后出现左侧上下肢瘫痪，右侧眼外直肌麻痹。请问该患者可能损伤了以下哪个结构","o":["右侧锥体束和右侧动眼神经","右侧锥体束和左侧展神经","左侧锥体束和右侧展神经","右侧锥体束和右侧展神经","左侧锥体束和左侧展神经"],"a":3,"e":"左侧上下肢瘫痪提示右侧锥体束受损（延髓交叉后支配对侧肢体）；右眼外直肌麻痹即不能外展，由右侧展神经支配，故损伤为右侧锥体束和右侧展神经。动眼神经损伤表现为上睑下垂、瞳孔散大；左侧锥体束损伤症状应在右侧"},{"q":"松果体瘤患者出现大量排尿，尿比重在1.005以下，尿在4000ml/d以上，可能是因为肿瘤侵犯了","o":["下丘脑脊髓束","乳头被盖束","乳头丘脑束","前脑内侧束","视上核或视上核垂体束"],"a":4,"e":"抗利尿激素由下丘脑视上核、室旁核合成，经视上垂体束运输至神经垂体贮存释放；松果体瘤侵犯视上核或该束可使ADH缺乏，出现低比重、大量尿崩。乳头被盖束、乳头丘脑束、前脑内侧束属边缘系统联系；下丘脑脊髓束为自主神经下行通路，均不合成ADH"},{"q":"患儿，3岁。急性中耳炎后出现乳突部皮肤肿胀、潮红，有明显压痛，诊断为乳突炎。中耳炎症经何处蔓延至乳突","o":["乳突窦","乳突小房","听小骨链","蜗窗","咽鼓管"],"a":0,"e":"乳突窦位于鼓室上隐窝后方，向前开口于鼓室后壁、向后连通乳突小房，是鼓室炎症蔓延至乳突的必经通道。乳突小房是炎症累及的部位而非通道；咽鼓管通向鼻咽；听小骨链、蜗窗与乳突炎症蔓延无关"},{"q":"患者因颅内血肿入院，经影像学检查判断血肿位于颅前窝，患者有可能出现什么症状","o":["视觉受损","眼球外展受限","对光反射消失","嗅觉障碍","面部浅感觉障碍"],"a":3,"e":"颅前窝底的筛板有嗅丝通过，血肿或骨折累及筛板时撕脱嗅丝和脑膜，出现嗅觉障碍甚至脑脊液鼻漏。视神经经视神经管、属颅中窝相关结构；外展受限与展神经有关；对光反射障碍涉及视神经或动眼神经；面部浅感觉由三叉神经管理，均非颅前窝血肿的典型表现"},{"q":"患儿，男，5岁。因异物进入呼吸道需紧急进行支气管镜检查。进行支气管镜检查时，看到下列哪个结构，可判断已经到达气管末端","o":["第4胸椎","胸骨角","气管隆嵴","气管衩","气管软骨"],"a":2,"e":"气管隆嵴为气管杈内面矢状位向上凸出的半月状嵴，略偏左，是支气管镜检查判断气管分叉即到达气管末端的重要标志。胸骨角为体表标志，平第4胸椎下缘；气管杈为分叉部位而非镜下最具标志性的嵴；气管软骨为C形环，均不构成判断气管末端的镜下标志"},{"q":"患者，男，76岁。中风后右半身不能动2周，既往有高血压史。查体：左眼瞳孔开大，并转向外下方，瞳孔直接对光反射消失，上睑下垂；右侧上、下肢呈痉挛性瘫痪，腱反射亢进，病理反射阳性，并伴有睑裂以下面瘫；伸舌时舌尖偏向右侧，肌不萎缩。其原因可能是","o":["左侧半中脑上丘高度大脑脚底受损","右侧半中脑上丘高度大脑脚底受损","左侧半中脑下丘高度大脑脚底受损","右侧半中脑下丘高度大脑脚底受损","左侧半中脑下丘高度被盖部受损"],"a":2,"e":"左眼瞳孔散大、转向外下方、上睑下垂及对光反射消失为左侧动眼神经损伤；右侧偏瘫、右侧核上性面瘫和伸舌偏右提示左侧锥体束及皮质核束受累，病变在左侧中脑下丘高度大脑脚底（Weber综合征）。中脑被盖或上丘高度损伤的组合体征不同；右侧大脑脚底受损则偏瘫在左侧"},{"q":"患儿，男，8岁。自诉黄昏或较暗光线下看不清东西，并暗适应障碍。诊断为视网膜色素变性（夜盲症）。这是由何种细胞功能不良引起的","o":["色素上皮细胞","节细胞","视锥细胞","视杆细胞","双极细胞"],"a":3,"e":"视杆细胞主要分布于视网膜周边部，感受弱光，在暗处及夜间视物中起主要作用，其功能不良导致夜盲和暗适应障碍。视锥细胞感受强光和颜色；色素上皮细胞、双极细胞、节细胞不直接承担暗视觉感受功能"},{"q":"患者，男，53岁。手术中损伤椎动脉后出现右侧头面部痛温觉障碍。请问该患者可能损伤了","o":["左侧薄束","左侧锥体束","左侧三叉神经脊束","右侧三叉神经脊束","右侧锥体束"],"a":3,"e":"三叉神经脊束传导同侧头面部痛温觉，右侧面部痛温觉障碍提示右侧三叉神经脊束受损，椎动脉阻塞致延髓外侧综合征时可累及此束。左侧三叉神经脊束损伤表现为左侧面部障碍；锥体束司运动，薄束传导下半身意识性本体感觉，均与面部痛温觉无关"},{"q":"患者因瞳孔缩小、眼睑下垂、眼球内陷、患侧额部无汗就诊。经检查判断为Honer综合征。其上睑下垂的症状需与哪个脑神经损伤相鉴别","o":["面神经","动眼神经","滑车神经","眼神经","展神经"],"a":1,"e":"Horner综合征的上睑下垂源于颈交感麻痹致Müller肌（睑板肌）瘫痪，而动眼神经支配上睑提肌，其损伤同样出现上睑下垂并伴瞳孔散大、眼球外下斜，故须鉴别。滑车神经支配上斜肌、展神经支配外直肌，损伤仅致眼球运动障碍；眼神经为感觉神经，均不引起提睑障碍"},{"q":"患者，女，58岁。腹痛，高热寒战，黄疸。经检查诊断为胆管结石。不属于肝外胆道的结构是","o":["肝管","肝总管","胆小管","胆囊","胆总管"],"a":2,"e":"胆小管位于肝内，是相邻肝细胞间的毛细胆管，属肝内胆道，不属肝外胆道。肝外胆道系统包括胆囊和输胆管道，即肝左管、肝右管、肝总管与胆总管，故肝管、肝总管、胆囊、胆总管均在其内"},{"q":"患者，男，60岁。手术后肛门失禁，可能损伤了肛门外括约肌的哪部分","o":["浅部","皮下部","深部","浅部和深部","皮下部和浅部"],"a":3,"e":"肛门外括约肌浅部和深部是控制排便的重要肌束，与直肠下份纵行肌、肛门内括约肌及肛提肌共同构成肛直肠环，损伤后致大便失禁。皮下部位于肛管下端及白线下方，切断后一般不引起大便失禁，故单独皮下部损伤不是本例原因"},{"q":"患者，男，40岁，建筑工人。被一个混凝土块砸在腿上，随后不能跖屈踝关节和足内翻。最有可能受损的肌是","o":["趾长伸肌","胫骨前肌","胫骨后肌","腓骨长肌","腓骨短肌"],"a":2,"e":"胫骨后肌位于小腿后群深层，止于足舟骨粗隆及楔骨，作用是使足内翻并协助跖屈；该肌受损后足不能内翻且跖屈力量减弱。胫骨前肌与趾长伸肌为前群肌、主司背屈；腓骨长、短肌属外侧群，使足外翻并协助跖屈，均不能完成内翻"},{"q":"患者，男。自述车祸后出现右眼眼球向内斜视。可能受累的神经是","o":["动眼神经","视神经","滑车神经","展神经","眼神经"],"a":3,"e":"展神经支配外直肌，损伤后外展麻痹，内直肌相对牵拉使眼球内斜视。动眼神经损伤致上睑下垂、瞳孔散大及眼球外斜；滑车神经损伤使眼不能转向外下方；视神经损害表现为视力障碍；眼神经司眼部感觉，均不产生单纯内斜视"},{"q":"患者，男，30岁。因中耳炎入院。经检查发现患者舌前2/3味觉传导障碍。其炎症可能损伤了什么结构","o":["舌下神经","鼓索","舌咽神经","岩小神经","岩大神经"],"a":1,"e":"鼓索为面神经出茎乳孔前的分支，返回鼓室后加入舌神经，其味觉纤维分布舌前2/3味蕾，中耳炎累及鼓索可致该区味觉障碍。舌下神经支配舌肌运动；舌咽神经传导舌后1/3味觉与一般感觉；岩大神经支配泪腺分泌；岩小神经支配腮腺分泌，均不传导舌前2/3味觉"},{"q":"患者，女，38岁。颈部发现一包块，并伴有声音嘶哑。经医生诊断为甲状腺囊肿。在甲状腺切除手术中，误伤了甲状旁腺，可导致以下哪些症状","o":["仅钙代谢失常","手足搐搦症","仅磷代谢失常","血钙浓度升高","血磷浓度降低"],"a":1,"e":"甲状旁腺分泌甲状旁腺激素，促进骨钙动员和肾小管重吸收钙，误伤后血钙下降、神经肌肉兴奋性增高，出现手足搐搦。血钙应降低而非升高，血磷应升高而非降低；单纯钙或磷代谢失常的说法均不全面，不能概括其典型表现"},{"q":"患者，女，32岁。在足球比赛中受伤，后被送入医院。在骨科诊所接受坐姿检查，医生双手握住右胫骨，可以在股骨下端将右胫骨移向后方，左胫骨不能以这种方式移动。右膝最有可能受伤的结构是","o":["前交叉韧带","腓侧副韧带","胫侧副韧带","内侧半月板","后交叉韧带"],"a":4,"e":"后交叉韧带在屈膝时最紧张，可防止胫骨相对股骨向后移位；检查能将右胫骨向后推动，说明该韧带断裂。前交叉韧带防止胫骨前移；胫、腓侧副韧带限制膝关节侧方异常活动；内侧半月板损伤主要表现为关节间隙压痛与交锁，均不能解释胫骨后移"},{"q":"患者，女，50岁。因中枢性眩晕和眼球震颤就医。可能与以下哪个神经核相关","o":["楔束核","薄束核","前庭神经核","蜗神经核","孤束核"],"a":2,"e":"前庭神经核接受前庭神经传入，与眼外肌核、小脑及脊髓联系，受损后出现眩晕和眼球震颤。薄束核、楔束核为本体感觉中继核；蜗神经核司听觉；孤束核司内脏感觉和味觉，均不引起眩晕眼震"},{"q":"某高血压患者，昏迷数小时后清醒。查体发现：右侧上、下肢呈痉挛性瘫痪，腱反射亢进，病理反射阳性；伸舌时舌尖偏向左侧，左侧半舌肌萎缩不明显；右侧躯干及上、下肢振动觉和精细触觉消失，但全身痛、温觉正常。试分析可能损伤的部位及结构是","o":["左侧中脑腹侧部，受损结构有左侧锥体束、右侧内侧丘系","左侧脑桥腹侧部，受损结构有左侧锥体束、右侧内侧丘系","右侧脑桥腹侧部，受损结构有右侧锥体束、左侧内侧丘系，左侧三叉神经核","左侧延髓腹侧部，受损结构有左侧锥体束、左侧内侧丘系，左侧舌下神经核","右侧延髓腹侧部，受损结构有右侧锥体束、右侧内侧丘系，右侧舌下神经核"],"a":3,"e":"伸舌舌尖偏向左侧提示左侧舌下神经核或根受损；右侧痉挛性瘫痪提示左侧锥体束在延髓交叉前受损；右侧本体感觉与精细触觉消失提示左侧内侧丘系受损，三征合为左侧延髓腹侧部的舌下神经交叉性偏瘫。脑桥、中脑病变不涉及舌下神经核，延髓右侧半损伤则偏瘫与舌瘫应同在右侧"},{"q":"患者，女，32岁。因刀伤导致左侧下肢行走困难，膝跳反射消失，大腿前面和小腿内侧面皮肤感觉消失。应该考虑受损伤的神经是","o":["闭孔神经","股神经","坐骨神经","胫神经","腓总神经"],"a":1,"e":"股神经支配股四头肌，并发出隐神经分布大腿前面和小腿内侧皮肤，受损后出现屈髋无力、不能伸膝、膝跳反射消失及相应区域感觉障碍。闭孔神经主司内收肌群；坐骨神经及其胫神经、腓总神经分支支配小腿和足肌，不影响伸膝与膝跳反射"},{"q":"患者，男，23岁。于入院前2个月余出现腹泻，平均每天10余次。1个月前无明显诱因出现暗红色血便。结肠镜检查：距肛门8cm直肠狭窄，可见溃疡型肿物。活检病理诊断：直肠癌。直肠癌不容易侵及以下哪个器官","o":["前列腺","膀胱","睾丸","精囊","输尿管"],"a":2,"e":"睾丸位于阴囊内，与直肠之间隔着盆腔结构，直肠癌不易直接侵犯。前列腺、膀胱、精囊位于直肠前方，输尿管盆部行经直肠前外侧，均与直肠毗邻，肿瘤进展时可被侵犯"},{"q":"患者，男，66岁。双眼对光反射消失。其受损部位最可能在","o":["两侧视区","两侧视辐射","顶盖前区","两侧外侧膝状体","双侧动眼神经核"],"a":2,"e":"顶盖前区接受视束发来的对光反射传入纤维，并投射至双侧动眼神经副核；双眼对光反射消失而视力存在，定位于顶盖前区。两侧视区或视辐射损伤主要致皮质盲；两侧外侧膝状体为视觉中继；双侧动眼神经核损伤多伴明显眼外肌麻痹，非单纯对光反射消失"},{"q":"患者，男，78岁。无明显诱因近期感觉双下肢皮肤干燥，汗腺分泌障碍。下列哪一结构受损可能导致此类症状","o":["颈神经节","胸神经节","腰神经节","奇神经节","星状神经节"],"a":2,"e":"腰神经节（腰交感干）发出灰交通支随腰神经分布至下肢的血管、汗腺和竖毛肌，受损后出现双下肢皮肤干燥、汗腺分泌障碍。颈、胸神经节及星状神经节支配头颈、上肢或躯干上部；奇神经节主要支配会阴部"},{"q":"患者，男，58岁。无痛性血尿半年，被诊断为肾肿瘤。需行肾部分切除术，手术时需缝合的结构是","o":["纤维囊","肾前筋膜","肾后筋膜","脂肪囊","腹膜脏层"],"a":0,"e":"纤维囊（纤维膜）紧贴肾实质表面，肾破裂或部分切除时需缝合此膜以止血和闭合创面。脂肪囊为肾外周脂肪层，肾前、后筋膜为肾筋膜，均不需缝合；腹膜脏层不构成肾的被膜，亦非缝合对象"},{"q":"患者，男，62岁，因肺癌行一侧全肺切除术，术中不需要切断的结构是","o":["肺动脉","肺静脉","主支气管","支气管动脉","段支气管"],"a":4,"e":"全肺切除需在肺门处切断肺动脉、肺静脉、主支气管及伴行的支气管动脉，即可完整移出一侧肺。段支气管位于肺叶内、属于支气管树的三级分支，随肺组织一并切除，无须在肺门单独切断；其余结构均需在肺门处理"},{"q":"患者，女，28岁。异位妊娠并发输卵管破裂出血。行阴道后穹窿穿刺确诊，穿刺到达的部位是","o":["直肠","输卵管","直肠子宫陷凹","膀胱子宫陷凹","直肠膀胱陷凹"],"a":2,"e":"阴道后穹最深，穿刺针经此仅隔阴道壁和一层腹膜即进入直肠子宫陷凹，可抽出积血确诊异位妊娠破裂。膀胱子宫陷凹居前且浅；直肠膀胱陷凹见于男性；输卵管、直肠均非后穹穿刺针尖所达的部位"},{"q":"患者，男，55岁。主诉夜间呕血100ml左右，食欲缺乏，消瘦。曾有乙型肝炎病史。B超显示肝缩小，肝内回声增粗，脾大。此患者呕血是由于哪条静脉破裂所致","o":["气管静脉","食管静脉","左胃静脉","右胃静脉","肠系膜上静脉"],"a":1,"e":"肝硬化致肝门静脉高压时，门静脉系的胃左静脉与上腔静脉系的奇静脉之间经食管静脉丛建立侧支循环；食管静脉丛曲张破裂即引起呕血与黑便。气管静脉、肠系膜上静脉不参与此交通；左、右胃静脉并非本题所述破裂出血的典型血管"},{"q":"患者，男，37岁。行颈后三角区淋巴结活检术后出现平静时下颏转向右侧，向左侧转头无力，右侧肩下垂且不能耸肩。出现该症状最可能的原因为","o":["左侧迷走神经损伤","右侧迷走神经损伤","左侧副神经损伤","右侧副神经损伤","右侧面神经损伤"],"a":3,"e":"副神经脊髓根支配胸锁乳突肌和斜方肌：右侧副神经损伤后右侧胸锁乳突肌瘫痪，头不能向左侧屈、面转向右侧，左转无力，右侧斜方肌瘫痪致右肩下垂、不能耸肩。迷走神经支配咽喉肌和内脏，面神经支配表情肌，均不支配此二肌；左侧副神经损伤则体征在左侧"},{"q":"患者，女，68岁。轻微跌倒后患髋疼痛，不能站立、行走，髋后部肿胀、压痛、患肢外旋畸形。X线诊断为股骨颈骨折。骨折部位是","o":["股骨上端的半球形膨大处","股骨头下外侧的缩细部分","大、小转子之间的前面","大、小转子之间的后面","股骨内上髁上方的小突起"],"a":1,"e":"股骨头下外侧的狭细部分为股骨颈，老年骨质疏松者轻微跌倒易发生股骨颈骨折，表现为髋痛、不能站立及患肢外旋畸形。股骨上端半球形膨大是股骨头本身；大、小转子之间为转子间区；内上髁上方小突起属股骨下端结构，均非股骨颈"},{"q":"患者，男，34岁。2个月前无明显诱因出现反复鼻出血，每次量不多，可自止，近3～4天，吸鼻有涕中带血。经鼻咽纤维喉镜检查发现鼻咽部有肿物，经内镜下肿物活检诊断为鼻咽癌。鼻咽癌容易发生于哪个部位","o":["咽鼓管圆枕","咽鼓管咽口","扁桃体上窝","咽隐窝","鼻咽部上壁"],"a":3,"e":"咽隐窝位于咽鼓管咽口后上方，是鼻咽癌最好发部位，早期常有涕中带血、鼻出血及鼻咽部肿物。咽鼓管圆枕与咽鼓管咽口属咽鼓管结构；扁桃体上窝及鼻咽部上壁均非鼻咽癌最典型的好发部位"},{"q":"患者，女，56岁。自感乏力，有口渴感，消瘦。空腹血糖值14.5mmol/L，诊断为糖尿病。其发生可能由哪种激素分泌不足引起","o":["胰高血糖素","胰岛素","肾上腺素","糖皮质激素","褪黑素"],"a":1,"e":"胰岛素由胰岛β细胞分泌，促进组织摄取利用葡萄糖、抑制糖异生，是唯一降低血糖的激素；分泌不足致血糖升高、尿糖，出现多饮多尿多食和消瘦。胰高血糖素、肾上腺素、糖皮质激素均升高血糖；褪黑素调节昼夜节律，与血糖无直接关系"},{"q":"患者，女，67岁。多饮、多食、消瘦10余年。门诊查空腹血糖12.5mmol/L，尿糖（++++）。半个月前突然出现视物模糊，其可能的病变部位在","o":["角膜","晶状体","玻璃体","房水","睫状体"],"a":1,"e":"长期糖尿病患者血糖升高，晶状体内渗透压改变、蛋白糖基化致晶状体混浊（糖尿病性白内障），是视物模糊的常见原因。角膜、房水、玻璃体、睫状体病变虽也可影响视力，但非糖尿病视物模糊的典型解剖学基础"},{"q":"患者，男，50岁。乳突平面附近区域皮肤麻木感，进而感觉慢慢消失。可能受损伤的神经是","o":["第2胸神经","第4胸神经","第6胸神经","第8胸神经","第10胸神经"],"a":1,"e":"胸神经前支在躯干呈节段性分布，第4胸神经平乳头平面，该处皮肤感觉障碍提示其受损。第2胸神经平胸骨角，第6胸神经平剑突，第8胸神经平肋弓，第10胸神经平脐，各有明确体表标志，与题中平面不符"},{"q":"患者，男，75岁。下颌下淋巴结肿大，来自于下述哪个器官","o":["甲状腺","舌","喉","眼","外耳"],"a":1,"e":"下颌下淋巴结位于下颌下腺附近，引流面部和口腔器官（如舌、牙、口底）的淋巴，舌的病变常致其肿大。甲状腺、喉的淋巴多汇入气管旁或颈外侧深淋巴结；眼、外耳的淋巴分别汇入耳前、腮腺或耳后、颈浅淋巴结"},{"q":"患儿，女，3岁。咳嗽，嗓子疼，发热1周。今诉说耳朵疼。经检查发现鼓膜红、肿，外凸。初步诊断为中耳炎。中耳炎的主要感染途径是","o":["外耳道","外耳门","内耳道","咽鼓管","面神经管"],"a":3,"e":"咽鼓管连通鼻咽与鼓室，咽部感染时细菌可经此管波及中耳；小儿咽鼓管短、宽且近水平位，故发病率远高于成人。外耳道与外耳门同鼓室之间有鼓膜相隔，并非感染通道；内耳道通内耳，面神经管走行面神经，均与中耳感染途径无关"},{"q":"一男性患者因昏迷入院治疗，以下哪项症状可以帮助医生作出患者“右侧内囊出血”的诊断","o":["右侧偏身感觉丧失","右侧躯干感觉丧失","左侧偏身感觉丧失","左侧躯干感觉丧失","右侧偏盲"],"a":2,"e":"内囊后肢有丘脑中央辐射、皮质脊髓束和视辐射通过，右侧内囊出血损伤丘脑中央辐射，出现对侧即左侧偏身感觉丧失，并常伴对侧偏瘫与同向性偏盲。右侧偏身感觉丧失提示病灶在左侧；仅躯干感觉丧失或右侧偏盲均不符合内囊病变的对侧、偏身、三偏特点"},{"q":"患者，女，18岁。拟诊白血病。需进行骨髓穿刺来检查骨髓象，穿刺抽取红骨髓。适合穿刺抽取的骨骼为","o":["股骨","髂骨","肱骨","椎骨","肩胛骨"],"a":1,"e":"髂骨、椎骨、胸骨、肋骨及肱骨、股骨骺内终身保留红骨髓，临床常选髂前上棘或髂后上棘行骨髓穿刺，位置表浅且安全。股骨、肱骨骨干成年后多为黄骨髓；肩胛骨红骨髓不丰富且位置不便，均非骨髓穿刺的常规选择"},{"q":"患者因丘脑肿瘤引起的丘脑综合征入院，经头颅CT显示肿瘤位于背侧丘脑腹后外侧核。患者可能出现的症状是","o":["变温症","同侧半躯干四肢浅感觉传导障碍","对侧半躯干四肢浅感觉传导障碍","同侧半躯干四肢深感觉传导障碍","对侧半躯干四肢深感觉传导障碍"],"a":4,"e":"背侧丘脑腹后外侧核是躯干四肢意识性本体感觉传导的中继核，内侧丘系交叉后终止于此，损伤后表现为对侧半躯干四肢深感觉传导障碍，包括位置觉、精细触觉与两点辨别觉。浅感觉亦经此核中继，但本例考点为内侧丘系深感觉；同侧半躯干四肢感觉障碍错误，因通路已交叉；变温症为下丘脑后部损伤表现"},{"q":"患儿，男，17岁。因左眼眶骨折入院。经检查发现其左侧眼球向外下方活动受限。可能损伤了什么神经","o":["动眼神经","滑车神经","展神经","眼神经","鼻睫神经"],"a":1,"e":"滑车神经支配上斜肌，该肌收缩使瞳孔转向下外方；滑车神经受损后上斜肌瘫痪，眼球向外下方活动受限。动眼神经损伤多表现为上睑下垂、瞳孔散大及向内、上等方向运动障碍；展神经麻痹致内斜视；眼神经与鼻睫神经为感觉神经，不支配眼肌运动"},{"q":"患者，女。近视600度，昨日不慎头部受撞击后，右眼出现视野缺损，临床诊断为右眼视网膜脱落。其解剖学基础是","o":["视网膜双极细胞层与节细胞层之间存在潜在间隙","视网膜双极细胞层与感光细胞层之间存在潜在间隙","视网膜色素上皮层与神经层之间存在潜在间隙","视网膜与脉络膜之间存在潜在间隙","视网膜与玻璃体之间存在潜在间隙"],"a":2,"e":"视网膜视部由外层色素上皮层和内层神经层构成，两层间存在潜在间隙，玻璃体支撑减弱时神经层与色素上皮分离，形成视网膜脱离。双极细胞层与节细胞层、双极细胞层与感光细胞层同属神经层，其间无此潜在间隙；视网膜与脉络膜或玻璃体之间并非脱离的解剖学界面"},{"q":"患者，56岁。出现椎动脉延髓支阻塞，出现对侧上、下肢瘫痪。该患者可能损伤了","o":["锥体束","皮质核束","丘脑腹后外侧核","红核","舌下神经核"],"a":0,"e":"延髓锥体束尚未交叉，椎动脉延髓支阻塞致单侧锥体束损伤，出现对侧上、下肢瘫痪。皮质核束支配脑神经运动核，损伤表现为对侧面肌、舌肌核上瘫；丘脑腹后外侧核为感觉中继站；红核与舌下神经核损伤分别致共济失调和同侧舌瘫，均非偏瘫主因"},{"q":"患者，男，54岁。因胃溃疡穿孔，行胃大部切除术。术后3天，发热。胸部、腹部X线检查发现右膈抬高，活动度差，膈下未见游离气体。此患者可能并发","o":["右下肺炎","急性化脓性胆囊炎","右膈下脓肿","肝脓肿","十二指肠残端瘘"],"a":2,"e":"胃大部切除术后胃内容物可积聚于右肝下间隙等膈下间隙，继发感染形成膈下脓肿，表现为发热、右膈抬高及活动度差，膈下无游离气体可排除胃肠穿孔。右下肺炎、急性胆囊炎、肝脓肿及十二指肠残端瘘虽可有发热，但均不以右膈抬高伴膈下积液为主要影像特征"},{"q":"患者，男，20岁，学生。主诉：右下颌骨膨隆1年余。现病史：1年前患者无意中发现右面部略隆起，因无症状未治疗，此后面部膨隆逐渐明显，因学习较忙而未就诊；2个月前感觉右下后牙有不适感；近1个月出现右下后牙疼痛，为阵发性，咀嚼时加重，偶有下唇麻木感。检查：面部不对称，右下颌区膨隆，范围约5cm×4cm×3cm，该区域皮肤未见异常；口内右下颌牙颊侧隆起，移行沟消失，表面黏膜无红肿。触诊有不适感，并有乒乓球感，无压痛。X线所见：相应于右下尖牙至下颌角区的下颌骨体部有圆形、多房状密度减低区，其边缘有密度增高的白色线条。范围已达下颌骨下缘。诊断：右下颌骨肉瘤。问：关于手术时需涉及的面动脉，叙述错误的是","o":["该动脉发自颈外动脉","该动脉主要供应下颌下腺、面部和腭扁桃体等","其体表投影为：在下颌骨下缘至咬肌后缘处作一连线，然后将连线连至内眦","其压迫止血部位为：在下颌骨下缘至咬肌前缘处，将面动脉压向下颌骨","压迫该动脉，其止血范围为面颊部"],"a":2,"e":"面动脉体表投影应在下颌骨下缘与咬肌前缘处作连线再连至内眦，题干写为咬肌后缘，故该叙述错误。面动脉发自颈外动脉，供应下颌下腺、面部及腭扁桃体；压迫止血在咬肌前缘下颌骨下缘处，止血范围为面颊部"},{"q":"患者，男，45岁。骑电车不小心摔倒，右脚踝局部肿胀、疼痛。X线诊断为单纯外踝撕脱骨折。外踝位于","o":["胫骨下端内下的突起","胫骨下端外下的突起","腓骨下端的膨大","腓骨头下方缩窄的部分","腓骨上端的膨大"],"a":2,"e":"外踝为腓骨下端向下的膨大，位置比内踝更低且略偏后，可在体表扪及，参与构成踝关节外侧壁并限制距骨过度外移。胫骨下端内下的突起才是内踝；胫骨下端外下并无此命名结构；腓骨头为腓骨上端膨大，腓骨颈为其下方缩窄部，均非外踝"},{"q":"患者，男，26岁。不幸遭遇车祸导致骨盆骨折，医生检查后怀疑尿道受损。男性骨盆骨折时最常见的尿道损伤部位是","o":["尿道海绵体部","尿道球部","尿道前列腺部","尿道膜部","前尿道"],"a":3,"e":"尿道膜部穿过尿生殖膈，位置固定，骨盆骨折移位时易被撕裂，是男性骨盆骨折最常见的尿道损伤部位。尿道球部损伤多见于会阴骑跨伤；尿道海绵体部（前尿道）和前列腺部损伤机制不同，均与骨盆骨折关系较小"},{"q":"患者，老年女性。因乳腺癌行乳腺癌根治术，清扫腋窝淋巴结。术后一侧肩胛骨内侧缘翘起，不能紧贴胸廓。应当考虑受损伤的神经是","o":["胸背神经","腋神经","肌皮神经","腓总神经","胸长神经"],"a":4,"e":"胸长神经支配前锯肌，乳腺癌根治清扫腋窝淋巴结时易损伤，致前锯肌瘫痪、肩胛骨内侧缘不能紧贴胸廓而翘起。胸背神经支配背阔肌；腋神经支配三角肌，损伤致方肩；肌皮神经支配前臂屈肌群；腓总神经为下肢神经，均不支配前锯肌"},{"q":"患者，女，53岁。因脑干肿瘤压迫动脉后出现右侧头面部痛温觉障碍，左侧上、下肢及躯干痛、温觉障碍等。请问该患者可能损伤了哪些结构","o":["左侧内侧丘系、左侧脊髓丘脑束","右侧三叉神经脊束、左侧脊髓丘脑束","右侧三叉神经脊束、右侧脊髓丘脑束","左侧内侧丘系、右侧脊髓丘脑束","左侧三叉神经脊束、右侧内侧丘系"],"a":2,"e":"右侧头面部痛温觉障碍由右侧三叉神经脊束受损所致，该束传导同侧面部痛温觉；左侧躯干四肢痛温觉障碍提示右侧脊髓丘脑束受损，此束在脊髓交叉后上行，右侧损伤表现为对侧即左侧障碍。左侧三叉神经脊束损伤表现为左侧面部障碍；脊髓丘脑束若左侧损伤则出现右侧躯干四肢痛温觉障碍，均与本例不符"},{"q":"患者患带状疱疹后先出现三叉神经痛，继而发现患者眼裂和口裂之间皮肤感觉障碍。可能是由三叉神经哪一支分支麻痹引起的","o":["眼神经","上颌神经","下颌神经","面神经","舌咽神经"],"a":1,"e":"上颌神经为三叉神经第二支，穿眶下孔后分布于下睑、鼻翼、上唇及睑裂与口裂之间的皮肤，故该区感觉障碍提示上颌神经麻痹。眼神经分布于眼裂以上；下颌神经分布于口裂以下并支配咀嚼肌；面神经与舌咽神经不传导此区皮肤感觉"},{"q":"患者，男，26岁。在工地打工意外受伤。医生检查后发现受伤部位在右侧精索，该损伤不可能累及的结构是","o":["输精管","睾丸动脉","蔓状静脉丛","输精管血管","精囊"],"a":4,"e":"精索内含输精管、睾丸动脉、蔓状静脉丛及输精管血管等结构，损伤精索不可能累及位于盆腔膀胱底后方的精囊。其余四项均为精索的固有内容物或伴行结构，随精索自腹股沟管进入阴囊"},{"q":"患者，男，23岁。面部口唇上方青春痘挤压后3天，头痛发热。血常规检查可见白细胞计数增高，怀疑有颅内感染。细菌进入颅内最可能经过的静脉","o":["面深静脉","颞浅静脉","上颌静脉","面静脉","颈内静脉"],"a":3,"e":"口唇上方属于面静脉收集区，该静脉在口角以上缺乏静脉瓣，并经眼静脉、翼静脉丛与海绵窦相通，挤压青春痘后细菌沿面静脉逆行入颅。面深静脉、颞浅静脉、上颌静脉仅为局部回流支；颈内静脉为颅内静脉回流出口，均非细菌由面部入颅的主要通道"},{"q":"患者，男，58岁。因甲状腺肿瘤行甲状腺次全切除术，术后患者感觉头面部汗腺分泌障碍，上睑下垂。应当考虑下列哪一结构受损伤","o":["颈交感干","内脏大神经","内脏小神经","动眼神经","眼神经"],"a":0,"e":"头面部汗腺分泌障碍伴上睑下垂（Horner综合征），源于颈交感干受损，甲状腺手术中可能伤及该结构。内脏大、小神经为腹腔交感神经，支配腹腔脏器；动眼神经损伤有上睑下垂和瞳孔散大但无汗腺障碍；眼神经仅为感觉神经"},{"q":"患儿，女，12岁。因双眼视远物不清，伴眼部胀痛及头晕就诊。查左眼视力0.7，右眼视力0.9。应用阿托品后远视力可恢复正常，诊断为假性近视。该患者功能异常的结构是","o":["角膜","房水","晶状体","玻璃体","睫状肌"],"a":4,"e":"假性近视因睫状肌持续痉挛、睫状小带松弛、晶状体曲度增大致屈光力过强，物像落在视网膜前；阿托品阻断睫状肌痉挛后远视力恢复。角膜、房水、玻璃体为屈光间质，其屈光度不因阿托品而改变；晶状体本身形态需经睫状肌调节，故功能异常的结构是睫状肌"},{"q":"患者，男，26岁。颌面外伤，张口受限。诊断为颧弓骨折。组成颧弓的骨是","o":["颞骨的乳突和颧骨的颞突","颞骨的颧突和颧骨的颞突","下颌骨的冠突和颧骨的颞突","上颌骨的颧突和颧骨的颞突","颞骨的乳突和颞骨的颧突"],"a":1,"e":"颧弓由颞骨的颧突与颧骨的颞突相接构成，是面部重要的骨性标志。颞骨乳突位于耳后；下颌骨冠突为下颌支的突起；上颌骨颧突参与眶下缘和颧上颌复合体，均不参与颧弓构成"},{"q":"患者，男，23岁。检查发现：患者颈5～胸1的脊髓白质前连合受损。患者会出现何种表现","o":["双上肢所有感觉缺失或减退","一侧上肢所有感觉缺失或减退","病变平面以下躯体痛、温觉减退，而深感觉和触觉保留","病变平面以下躯体所有感觉缺失或减退","双上肢痛温觉缺失或减退而深感觉和触觉保留"],"a":4,"e":"C5～T1节段的白质前连合内有脊髓丘脑束交叉纤维，受损后阻断双侧上肢痛温觉传导，出现双上肢痛温觉缺失而深感觉与触觉保留，因后索未受损。一侧上肢感觉障碍提示半侧损伤；病变平面以下躯干痛温觉障碍多为胸段以上横贯性损害；所有感觉缺失则提示脊髓完全横断"},{"q":"患者，男，50岁。长距离跑步，导致股四头肌功能受阻，表现为不能","o":["抬大腿","伸膝","仰卧起坐","内收大腿","外旋大腿"],"a":1,"e":"股四头肌跨髋、膝两关节，是伸膝的唯一主力，其功能障碍表现为不能伸膝，坐位时尤为明显。抬大腿主要由髂腰肌等屈髋肌完成；仰卧起坐依靠腹肌；内收大腿由大腿内收肌群负责；外旋大腿由臀大肌、梨状肌等完成，均非股四头肌作用"},{"q":"患者，女，56岁。胃癌术后发现左锁骨上大窝有一肿大的淋巴结，试分析可能是下述哪组淋巴结","o":["右锁骨上淋巴结","左锁骨上淋巴结","颈浅淋巴结","左锁骨下淋巴结","右锁骨下淋巴结"],"a":1,"e":"胃癌细胞栓子可经胸导管转移至左锁骨上淋巴结（Virchow淋巴结），常在胸锁乳突肌后缘与锁骨上缘夹角处触及肿大。右锁骨上淋巴结引流右侧胸腔和右上肢（经右淋巴导管）；颈浅淋巴结、锁骨下淋巴结均非胃癌转移的典型标志性部位"},{"q":"患者，男，20岁。因肛肠手术，需行椎管内麻醉。麻醉药物可经何处注入骶管","o":["骶粗隆","骶管裂孔","骶前孔","骶后孔","骶角"],"a":1,"e":"骶管下端开口于骶管裂孔，裂孔两侧有骶角作为体表标志，骶管麻醉即经骶角定位后由此孔注入药物。骶前、后孔是骶神经前、后支穿出之处，并不开口于骶管下端；骶粗隆为骶骨背面的骨性突起，与注药通道无关"},{"q":"患者，男，63岁。主诉：中上腹痛伴呕吐14小时。患者14小时前出现中上腹部疼痛，呈持续性钝痛，并逐渐加重，腰酸明显，疼痛在仰卧位加重，蜷曲位减轻，伴恶心、呕吐，呕吐2次胃内容物，解黄色稀便1次，在某卫生院肌内注射“消旋山莨菪碱”后疼痛无缓解，腹痛前参加聚餐饮白酒约200g及进食较多。既往曾有右上腹发作性疼痛史，3年前B超发现有“胆囊炎、胆囊结石”。体格检查：巩膜无黄染，皮肤黏膜未见瘀点、瘀斑心界无扩大，腹软，剑突下及剑脐间有压痛，无明显反跳痛及肌卫，Murphy征（-），肝脾肋下未及。腹部平片：肠腔少量积气以左上腹为主，气液平不明显，两膈下未见游离气体。B超：胆囊结石、胆囊炎；胰腺体积饱满回声稍低，肝、脾、双肾未见明显异常。上腹CT（平扫及增强）：胰腺体积增大，边缘毛糙，增强后密度尚均匀，余未见明显异常。急诊行腹腔探查。探查时下列动脉直接起于腹主动脉的有","o":["胃左动脉","肝总动脉","肠系膜上动脉","胃右动脉","脾动脉"],"a":2,"e":"腹主动脉的直接分支包括腹腔干、肠系膜上动脉、肠系膜下动脉和肾动脉等，肠系膜上动脉直接起自腹主动脉。胃左动脉、肝总动脉、脾动脉均为腹腔干的分支；胃右动脉起自肝固有动脉（肝总动脉系统），均非腹主动脉直接分支"},{"q":"患者，女，53岁。近期自觉心悸气短入院检查。心电图、彩超检查均无异常，患者坚持要求进行冠脉造影检查。在检查过程中，可作为确定心缘标志的是","o":["前室间支","左缘支","后室间支","右缘支","右旋支"],"a":3,"e":"右缘支走行于右心缘、粗大恒定，冠状动脉造影时是确认右心缘的标志。左缘支为左心缘的标志；前室间支与后室间支走行于室间沟内，是左右心室分界的标志，不用于判定心缘；右旋支并非冠状动脉的固定分支名称"},{"q":"患者，女，47岁，一位女网球专业人士。告诉她的医生，她有肩袖损伤，需要手术。她的医生解释说，多年来肩关节周围的韧带损伤，逐渐加重了下方的肌肉损伤。下列哪一个韧带是医生最可能提到的","o":["肩锁韧带","喙肱韧带","肩胛横韧带","盂肱韧带","喙肩韧带"],"a":4,"e":"喙肩韧带连于喙突与肩峰之间，与二者共同构成喙肩弓，架于肩关节上方，防止肱骨头向上脱位；肩袖损伤时该弓下结构受累。肩锁韧带加强肩锁关节，喙肱韧带、盂肱韧带为肩关节囊的加强韧带，肩胛横韧带并非肩关节稳定装置，均不直接防止肱骨头上移"},{"q":"一患者脑血管意外入院治疗，经检查右侧大脑中动脉中央支闭塞，患者会出现下列哪种症状","o":["右耳听力丧失","左耳听力丧失","左眼视野鼻侧和右眼视野颞侧偏盲","右眼视野鼻侧和左眼视野颞侧偏盲","双眼左侧视野同向性偏盲"],"a":4,"e":"右侧大脑中动脉中央支闭塞累及右侧视辐射，损伤视束以后的视觉传导路，导致双眼对侧即左侧视野同向性偏盲，右眼鼻侧半与左眼颞侧半偏盲即其具体表现。视交叉中部损伤致双颞侧偏盲；一侧视神经损伤致该眼全盲；听力障碍与听辐射或前庭蜗神经有关，均非本例表现"},{"q":"患者，女，50岁。车祸导致第10～12胸椎受损伤。可累及的脊髓节段是","o":["下胸段","全部腰段","全部骶段","全部腰骶段","全部骶尾段"],"a":1,"e":"成人脊髓节段与椎骨不同高，腰髓节段约平对第10至12胸椎，故第10至12胸椎损伤累及全部腰段。下胸髓节段约平对同序数椎骨上三块椎骨，当第6至9胸椎水平；骶髓、尾髓节段平对第1腰椎，均不与第10至12胸椎对应"},{"q":"患者，女，40岁。右侧乳房癌根治手术后，撑墙出现右侧“翼状肩”体征。损伤的肌是","o":["三角肌","前锯肌","斜方肌","肩胛下肌","背阔肌"],"a":1,"e":"胸长神经支配前锯肌，该肌拉肩胛骨向前并紧贴胸廓；乳腺癌根治术清扫腋窝淋巴结时易损伤此神经，致前锯肌瘫痪、肩胛骨内侧缘翘起呈翼状肩。三角肌由腋神经支配；斜方肌由副神经支配；背阔肌由胸背神经支配；肩胛下肌由肩胛下神经支配，损伤均不产生翼状肩"},{"q":"患者，女，64岁。5天前无明显诱因出现吞咽疼痛，呈持续性，刀割样，吞咽、说话时诱发疼痛，不能自行缓解。咽部喷洒局麻药（利多卡因）疼痛能轻微缓解。该患者诊断为“舌咽神经痛”。关于舌咽神经的描述，错误的是","o":["为混合性脑神经","与迷走神经和副神经同穿颈静脉孔","其咽支分布于咽壁，为一般内脏运动纤维","其舌支传导舌后1/3黏膜的一般感觉和味觉","其颈动脉窦支分布于颈动脉窦和颈动脉小球"],"a":2,"e":"舌咽神经咽支实为一般内脏感觉和特殊内脏运动纤维，分布于咽缩肌、软腭肌及咽部黏膜，接受咽壁感觉传入并参与咽反射，并非一般内脏运动纤维。舌咽神经为混合性脑神经，与迷走、副神经同穿颈静脉孔；舌支传导舌后1/3一般感觉和味觉；颈动脉窦支分布于颈动脉窦及颈动脉小球"},{"q":"患者，男，27岁，著名钢琴家。因腕管综合征导致手指运动困难。瘫痪的肌包括","o":["骨间掌侧肌和拇收肌","骨间背侧肌和第1、2蚓状肌","第1、2蚓状肌和拇对掌肌","拇短展肌和骨间掌侧肌","第1、2、3、4蚓状肌"],"a":2,"e":"正中神经支配第1、2蚓状肌和鱼际肌（含拇对掌肌），腕管综合征压迫该神经时上述肌瘫痪。拇收肌、骨间掌侧肌、骨间背侧肌及第3、4蚓状肌由尺神经支配；拇短展肌虽由正中神经支配，但与骨间掌侧肌组合的选项错误"},{"q":"患者，男，45岁。手术中损伤椎动脉后出现右侧软腭及咽喉肌麻痹，吞咽困难，声音嘶哑。请问该患者可能损伤了以下哪个结构","o":["左侧面神经核","左侧疑核","右侧疑核","右侧迷走神经背核","左侧迷走神经背核"],"a":2,"e":"疑核为特殊内脏运动核，其轴突加入舌咽、迷走与副神经，支配同侧软腭及咽喉肌；右侧疑核受损即出现右侧软腭咽喉肌麻痹、吞咽困难和声音嘶哑。迷走神经背核为副交感核、支配腺体与平滑肌；左侧疑核或左侧面神经核损伤均表现为左侧体征，与本例右侧不符"},{"q":"患者，女，60岁。有风湿性心脏病史，长期服药治疗。近期出现全身无力、嘴唇发绀入院。心脏彩超检查发现患者二尖瓣关闭不全比较严重，拟进行瓣膜置换手术治疗。手术的入路部位是","o":["右心室前壁","右心室下壁","左心室前壁","左心室下壁","左心室侧壁"],"a":2,"e":"左心室前壁位于前室间沟、左房室沟与左缘支之间，该区血管较少，是左心室手术的常用入路。左心室下壁、侧壁血管较丰富且邻近重要结构；右心室前、下壁与二尖瓣置换的左侧入路不符，均不作此手术通路"},{"q":"患者，男，40岁。发现颈部有一包块，可随吞咽而上下移动。经医生诊断后行甲状腺次全切术，术后出现手足搐搦。与此症状相关的问题是","o":["甲状腺素分泌不足","甲状旁腺功能相对亢进","甲状腺侧叶切除时损伤甲状旁腺","甲状旁腺离甲状腺较远","分布于甲状腺的神经受损"],"a":2,"e":"甲状旁腺多位于甲状腺侧叶后缘与被膜之间，位置恒定的上甲状旁腺和下甲状旁腺均紧邻甲状腺，行甲状腺侧叶切除时易被误切或损伤，致低钙血症和手足搐搦。甲状腺素不足致黏液性水肿；甲旁亢致高钙；神经损伤表现为声嘶"},{"q":"患者，男，24岁，是一位木工。遭受了整个小指的挤压伤。下列哪一种肌最有可能幸免","o":["指深屈肌","指伸肌","骨间掌侧肌","骨间背侧肌","蚓状肌"],"a":3,"e":"骨间背侧肌共4块，分别外展第2、3、4指，并不作用于小指，故小指挤压伤时该肌最可能幸免。指深屈肌腱止于小指远节指骨；指伸肌腱止于小指指背；骨间掌侧肌内收第5指；第3、4蚓状肌亦作用于小指，这些结构均受累"},{"q":"患者因头痛、恶心、呕吐入院，经诊断为脑水肿引起的颅内高压。该患者除了上述症状之外还有可能出现","o":["嗅觉障碍","听觉障碍","味觉障碍","面瘫","瞳孔对光反射减弱"],"a":4,"e":"脑水肿致颅内压增高可压迫动眼神经或使脑干移位，影响瞳孔对光反射通路中的传出环节，出现瞳孔对光反射减弱，常为脑疝先兆。嗅觉障碍多见于颅前窝筛板损伤；听觉、味觉障碍及面瘫分别涉及前庭蜗神经、面神经或鼓索，均非颅内压增高的常见伴发体征"},{"q":"患者，男，76岁。突发脑出血后，出现右侧上、下肢及躯干意识性本体感觉和精细触觉障碍。经检查为椎动脉延髓支阻塞，请问该患者可能损伤了哪个结构","o":["左侧内侧丘系","左侧皮质核束","左侧锥体束","右侧内侧丘系","右侧皮质核束"],"a":0,"e":"右侧躯干四肢意识性本体感觉障碍提示内侧丘系受损，该束在延髓交叉后上行，左侧损伤表现为对侧即右侧障碍，椎动脉延髓支阻塞可累及。右侧内侧丘系损伤应表现为左侧障碍；皮质核束与锥体束为运动通路，损伤致瘫痪而非感觉障碍，均与本例不符"},{"q":"患者，男，32岁。左腰部被刺，伤口持续出血，急诊入院。查体：脉搏120次/min，四肢冰冷，左上腹压痛，无腹肌紧张及反跳痛。考虑可能有腹腔器官损伤，最可能损伤的器官是","o":["肝","脾","胃","肾","横结肠"],"a":3,"e":"肾位于腹膜后隙、脊柱两侧，左腰部受刺伤且伤口持续出血、出现休克，首先考虑肾损伤。肝、脾位于腹腔内且位置偏右季肋或左上腹，横结肠为空腔脏器、损伤以腹膜炎为主；本例创口在左腰部、腹膜刺激征不明显，符合腹膜后位肾的损伤特点"},{"q":"患者，女，53岁。因处于更年期心情烦躁，经常发脾气，此次和同事争吵后突发胸痛、气短入院。入院心脏彩超检查发现心包积液。关于心包错误的是","o":["分为纤维心包和浆膜心包","纤维心包伸缩性很小","浆膜心包又分为脏、壁两层","纤维心包与浆膜心包间为心包腔","心包腔内有少量浆液"],"a":3,"e":"心包腔是浆膜心包脏、壁两层之间的潜在腔隙，内含少量浆液，并非纤维心包与浆膜心包之间的间隙，故该叙述错误。心包分纤维心包和浆膜心包，前者伸缩性小，后者又分脏、壁两层，脏层即心外膜，这些表述均正确"},{"q":"患者，男，43岁。检查发现其双侧对称分布的痛、温觉消失，本体感觉和精细触觉无障碍。可能损伤的部位是","o":["脊髓横断","脊髓半横断","脊髓白质前连合受损","脊髓前角损伤","脊髓后角损伤"],"a":2,"e":"脊髓白质前连合内有脊髓丘脑束的交叉纤维，病变阻断双侧痛温觉传导，出现双侧对称分布的痛温觉消失；后索未受损，故本体感觉和精细触觉保留，为分离性感觉障碍。脊髓半横断表现为同侧深感觉障碍与对侧痛温觉障碍；前角损伤只有肌无力而无感觉异常；后角损伤为单侧节段性痛温觉障碍"},{"q":"患者，女，67岁。无明显诱因感觉右侧肩部疼痛。根据牵涉性痛的特点，可以考虑下列哪一器官可能出现病变","o":["肝胆","心","胃","十二指肠","右肺"],"a":0,"e":"肝胆疾患的牵涉痛常表现为右肩部疼痛，因病变脏器传入神经与右肩皮肤感觉神经进入同一脊髓节段并在后角密切联系。心绞痛牵涉至胸前区及左上臂内侧；胃、十二指肠疾患多表现为上腹部疼痛；右肺病变并不以右肩牵涉痛为典型表现"},{"q":"患者，男，69岁。因突发腹部疼痛6小时入院。既往胃镜曾证实为胃溃疡。体质中等，无酗酒，脂肪餐史。伴有恶心，无呕吐，排大便1次，量少，有腹胀。查体：腹部平坦，腹肌紧张，全腹压痛，上腹部剑突下为重，伴反跳痛，肠鸣音弱。检验：白细胞明显升高，尿淀粉酶正常。腹部立位平片：2个小液平面，未见膈下游离气体。行开腹探查术，发现胃后壁穿孔。手术涉及到的行于胃小弯侧的动脉是","o":["胃左动脉、胃右动脉","胃左动脉、胃右动脉、肝总动脉","胃网膜左动脉、胃网膜右动脉","胃左动脉、肝总动脉、脾动脉","胃短动脉、胃后动脉"],"a":0,"e":"胃小弯侧由胃左动脉与胃右动脉沿小弯走行并互相吻合，供应小弯侧胃壁，胃后壁穿孔手术涉及此二动脉。胃网膜左、右动脉行于胃大弯；肝总动脉、脾动脉为腹腔干分支；胃短动脉、胃后动脉主要分布于胃底与胃后壁，均不沿小弯走行"},{"q":"患者，女，35岁。主诉上腹部剧烈疼痛伴呕吐2天。患者于前日下午1时左右出现上腹部疼痛，剑突下为甚。疼痛剧烈难以忍受，呈持续性，放射至腰背部，伴有呕吐，呕吐物为胃内容物。检查：血糖依次为28.4mmol/L、26.9mmol/L、33.3mmol/L，血淀粉酶为865U/L。怀疑为急性重症胰腺炎（SAP）。急诊手术探查时需结扎的胰腺动脉来自","o":["胃左动脉","胃右动脉","胃短动脉","肝固有动脉","脾动脉"],"a":4,"e":"胰的动脉主要来自脾动脉，其沿途发出胰背动脉、胰大动脉、胰尾动脉等供应胰体尾，胰头另由胃十二指肠动脉的胰十二指肠上动脉供血；急性重症胰腺炎手术常需结扎脾动脉分支。胃左、胃右、胃短动脉主要供应胃；肝固有动脉供应肝与胆囊，均非胰腺主要供血来源"},{"q":"患者，男，37岁。在某星期六的早晨，与朋友踢足球时，足部损伤后被送往医院。一系列影像显示骨折累及距小腿关节（踝关节）。损伤主要影响的运动是","o":["足的背屈和跖屈","足的背屈、跖屈、内翻和外翻","足的内翻和外翻","足的背屈和外翻","足的跖屈和内翻"],"a":0,"e":"踝关节由胫、腓骨下端与距骨滑车构成，只能作背屈和跖屈，距骨滑车前宽后窄是其结构基础。足的内翻和外翻由距跟关节与距跟舟关节完成，不属于踝关节运动；内翻多伴跖屈、外翻多伴背屈，故另列的混合选项均混淆了关节分工"},{"q":"患者，女，50岁。因进行性吞咽困难就诊。经食管镜检查并行活检，诊断为食管癌。食管癌常发生于食管的狭窄，关于食管狭窄的描述正确的是","o":["第1个狭窄距中切牙10cm","第1个狭窄对第7颈椎水平","第2个狭窄在左主支气管跨越食管左前方处","第2个狭窄距中切牙20cm","第3个狭窄在第11胸椎高度"],"a":2,"e":"食管第2狭窄位于食管与左主支气管交叉处，即左主支气管跨越其左前方处，平第4、5胸椎之间，距中切牙约25cm，是异物滞留和食管癌好发处。第1狭窄平第6颈椎下缘、距中切牙15cm，非第7颈椎或10cm；第2狭窄距中切牙25cm而非20cm；第3狭窄平第10胸椎而非第11胸椎"},{"q":"患者，女，46岁。自感轻度呼吸困难，声音嘶哑。经医生检查，发现甲状腺上有包块。诊断为结节性甲状腺肿。该病在做甲状腺检查时可发现","o":["吞咽时可随喉向上下移动","吞咽时不随喉向上下移动","包块的移动与吞咽时喉的运动无关","吞咽时随喉向上下移动，是与甲状腺囊有关","吞咽时不随喉向上下移动，是与甲状腺鞘有关"],"a":0,"e":"甲状腺假被膜内侧增厚形成甲状腺悬韧带，将腺体固定于喉和气管，故吞咽时甲状腺可随喉上下移动，是颈部肿块的鉴别要点。甲状腺不随喉移动或移动与喉无关的说法错误；该固定主要依靠悬韧带而非单纯囊壁"},{"q":"患者，女，40岁。诊断为右卵巢肿瘤而行腹腔镜手术，术中可见卵巢位于盆腔侧壁的什么位置","o":["髂总动脉起始处","髂总动脉末端前部","髂内动脉分叉处","髂内、外动脉起始处之间","髂外动脉与输尿管之间"],"a":3,"e":"卵巢位于盆腔侧壁的卵巢窝，相当于髂内、外动脉分叉夹角处，故术中在此区域寻找。髂总动脉起始处或末端、髂内动脉分叉处定位偏高或偏内；髂外动脉与输尿管之间并非卵巢的恒定位置"},{"q":"患者，女，62岁。因肿瘤压迫中脑被盖后出现右侧除外直肌和上斜肌外的所有眼球外肌麻痹，瞳孔散大，左上、下肢及躯干意识性本体觉和精细触觉障碍。请问该患者可能损伤了哪些结构","o":["右动眼神经、右内侧丘系","右动眼神经、右脊髓丘脑束","左展神经、左内侧丘系","左动眼神经、左内侧丘系","右展神经、右内侧丘系"],"a":0,"e":"右侧除外直肌、上斜肌外的眼外肌麻痹伴瞳孔散大，提示右侧动眼神经损伤；左上、下肢及躯干意识性本体觉障碍提示右侧内侧丘系受损（已在脑干交叉），二者合为右侧中脑被盖腹内侧部病变。展神经仅支配外直肌；脊髓丘脑束传导痛温觉而非本体感觉，左侧动眼神经损伤体征应在左侧"},{"q":"患者，男，40岁。近日逐渐出现左侧上、下肢瘫痪，腱反射亢进，右侧眼球不能外视。可能的病变部位及其受损的结构是","o":["在左侧半中脑下丘高度腹内侧部，受损结构有锥体束和动眼神经根","在右侧半中脑下丘高度腹内侧部，受损结构有锥体束和动眼神经根","在左侧半脑桥上部高度腹内侧部，受损结构有锥体束和滑车神经根","在右侧半脑桥上部高度腹内侧部，受损结构有锥体束和滑车神经根","在右侧半脑桥下部高度腹内侧部，受损结构有锥体束和展神经根"],"a":4,"e":"左侧肢体瘫痪提示右侧锥体束受损（交叉后支配对侧）；右眼不能外视即外直肌麻痹，由右侧展神经支配，病变在右侧脑桥下部腹内侧部，即展神经交叉性偏瘫。动眼神经损伤致上睑下垂和瞳孔散大；滑车神经损伤致眼不能外下视；中脑病变累及动眼神经根"},{"q":"患者，女，67岁。突发脑出血后，出现左侧舌肌瘫痪。经检查为椎动脉延髓支阻塞。请问该患者可能损伤了哪个结构","o":["左侧舌下神经根","左侧舌咽神经根","左侧迷走神经","右侧舌下神经根","右侧舌咽神经根"],"a":0,"e":"舌下神经支配同侧舌内肌和大部分舌外肌，其根受损致同侧半舌肌瘫痪、伸舌偏向患侧，故左侧舌肌瘫痪为左侧舌下神经根损伤。舌咽神经支配茎突咽肌和腮腺；迷走神经支配咽喉肌；右侧舌下神经根损伤则出现右侧舌肌瘫痪"},{"q":"患儿，男，14岁。从滑板上摔下来，头撞在柏油路上。影像学检查显示蝶鞍破坏。损伤的骨是","o":["筛骨","枕骨","额骨","蝶骨","顶骨"],"a":3,"e":"蝶鞍位于蝶骨体上面，呈马鞍状，容纳垂体，蝶鞍破坏即蝶骨体受损。筛骨构成鼻腔上部及眶内侧壁；枕骨围成枕骨大孔；额骨构成颅前窝及眶上壁；顶骨构成颅盖，均不参与蝶鞍构成"},{"q":"一患者因脑血管意外入院治疗，经检查发现该患者左侧大脑中动脉闭塞。根据解剖学知识，该患者不会产生","o":["顶下小叶区域血供受到影响","听区血供受到影响","感觉性失语症","失读症","视觉出现障碍"],"a":4,"e":"视觉中枢位于枕叶，由大脑后动脉供血，大脑中动脉闭塞不会引起视觉障碍。顶下小叶、听区（颞横回）在中动脉供血区；左侧颞上回后部（Wernicke区）受损致感觉性失语；左侧顶叶角回受累可致失读"},{"q":"患者，男，67岁。行腹股沟斜疝修补术后，感觉右侧腹股沟区阴囊部的皮肤感觉减退。最有可能损伤的神经是","o":["闭孔神经","髂腹股沟神经","髂腹下神经","生殖股神经","股神经"],"a":1,"e":"髂腹股沟神经经腹股沟管与精索伴行，自浅环穿出后分布于腹股沟区及阴囊部皮肤，斜疝修补术易损伤该神经致相应区域感觉减退。髂腹下神经主要分布于耻骨上区；生殖股神经股支支配股三角区皮肤；股神经支配大腿前面，均不以阴囊部皮肤感觉减退为主要表现"},{"q":"患者，男，35岁。头痛，恶心、呕吐，发热。查体：脑膜刺激征阳性。诊断为脑脊髓膜炎。在第3腰椎和第4腰椎棘突间行腰椎穿刺抽脑脊液化验。腰椎的棘突特征是","o":["短而分叉","长而不分叉","呈叠瓦状","呈板状，水平向后延伸","向下倾斜排列"],"a":3,"e":"腰椎棘突宽短呈板状，水平伸向后方，棘突间隙较宽，是腰椎穿刺的解剖学基础。短而分叉为颈椎棘突；细长且呈叠瓦状排列为胸椎棘突；长而不分叉、向下倾斜均不符合腰椎棘突特征"},{"q":"患儿，男，10岁。因垂体瘤出现双眼视野颞侧缺损。该肿瘤可压迫的结构是","o":["视交叉","上丘","视束","视辐射","视神经"],"a":0,"e":"垂体位于蝶鞍内，向上毗邻视交叉，肿瘤压迫视交叉中部的交叉纤维可致双眼视野颞侧半偏盲。一侧视神经损伤致该眼全盲；视束或视辐射损伤致双眼对侧同向性偏盲；上丘为视觉反射中枢，非视野缺损的责任结构"},{"q":"患者，男，63岁。因背部疼痛、虚弱和呼吸短促被送往急诊室。检查发现在膈肌主动脉裂孔处有腹主动脉瘤。下列结构最有可能被压缩的是","o":["迷走神经和奇静脉","食管及迷走神经","奇静脉和胸导管","胸导管与迷走神经","下腔静脉和膈神经"],"a":2,"e":"主动脉裂孔位于第12胸椎前方，有主动脉和胸导管通过，奇静脉亦由此跨膈，腹主动脉瘤在此处最易压迫胸导管与奇静脉。食管及迷走神经经食管裂孔；下腔静脉与膈神经经腔静脉孔；这些结构均不通过主动脉裂孔，故不受该处动脉瘤直接压迫"}];
